import { Client } from "@modelcontextprotocol/sdk/client/index.js";
import { UnauthorizedError } from "@modelcontextprotocol/sdk/client/auth.js";
import { SSEClientTransport } from "@modelcontextprotocol/sdk/client/sse.js";
import { StreamableHTTPClientTransport } from "@modelcontextprotocol/sdk/client/streamableHttp.js";

import pkg from "../../package.json" with { type: "json" };
import { DEFAULT_REDIRECT_URL, StoredOAuthProvider } from "./oauthProvider.js";

/**
 * **One remote MCP server, as a seam.**
 *
 * `connect()`, `listTools()`, `callTool()`, `close()` — and the two halves of a login that
 * the routes need, `finishAuth()` and `disconnect()`. Nothing above this knows
 * about transports, OAuth or the SDK: a connect either works or comes back
 * `{ ok: false, authUrl }`, and a 401 anywhere is "needs auth", never a crash.
 *
 * The SDK `Client` and the transport are built through two injected factories,
 * which is the whole of how the tests run without a network.
 */

export const NOTION_MCP_URL = "https://mcp.notion.com/mcp";

const CLIENT_INFO = { name: pkg.name, version: pkg.version };

/** @typedef {"streamable" | "sse"} TransportKind */
/** @typedef {"oauth" | "none"} AuthKind */
/** @typedef {{ name: string, description?: string, inputSchema?: object, outputSchema?: object }} McpTool */

function defaultCreateClient() {
  return new Client(CLIENT_INFO, { capabilities: {} });
}

/** @param {{ kind: TransportKind, url: URL, authProvider?: StoredOAuthProvider }} options */
function defaultCreateTransport({ kind, url, authProvider }) {
  const options = authProvider ? { authProvider } : {};
  return kind === "sse" ? new SSEClientTransport(url, options) : new StreamableHTTPClientTransport(url, options);
}

/** A 401 the SDK could not refresh its way out of. */
export function isUnauthorized(err) {
  return err instanceof UnauthorizedError || err?.code === 401;
}

/**
 * A failure as one sentence. `fetch failed` on its own says nothing about a
 * local server that simply is not running; its cause's code does.
 */
export function describeError(err) {
  const message = err?.message ?? String(err);
  const code = err?.cause?.code;
  return code && !message.includes(code) ? `${message} (${code})` : message;
}

/** Notion serves the legacy SSE transport beside `/mcp`, at `/sse`. */
function sseUrlFor(url) {
  const sse = new URL(url);
  sse.pathname = sse.pathname.replace(/\/mcp\/?$/, "/sse");
  return sse;
}

export class McpClient {
  #server;
  #auth;
  #url;
  #sseUrl;
  #store;
  #redirectUrl;
  #createClient;
  #createTransport;

  /** The live connection. @type {{ client: any, transport: any, provider: StoredOAuthProvider, kind: TransportKind } | null} */
  #live = null;
  /** The transport a login was started on; `finishAuth` belongs to it. */
  #pending = null;
  /** One connect at a time: a double click is one handshake. */
  #connecting = null;

  /** @type {{ name: string, version: string } | null} */
  serverInfo = null;
  /** The last listing, for the status line. @type {McpTool[] | null} */
  tools = null;
  /** Where the user has to go, if the last attempt ended in a 401. @type {string | null} */
  authUrl = null;
  /** Why the last connect failed, when it was not a 401 — "is it running?". @type {string | null} */
  lastError = null;

/**
   * @param {{
   *   authStore?: import("../store/mcpAuthStore.js").McpAuthStore,
   *   server?: string,
   *   auth?: AuthKind,
   *   url?: string | URL,
   *   sseUrl?: string | URL,
   *   redirectUrl?: string,
   *   createClient?: () => any,
   *   createTransport?: (options: { kind: TransportKind, url: URL, authProvider?: StoredOAuthProvider }) => any,
   * }} options - `auth: "none"` is a server with nothing to log in to: no
   *   provider, no store, no SSE fallback, and a 401 is just an error.
   */
  constructor({
    authStore,
    server = "notion",
    auth = "oauth",
    url = NOTION_MCP_URL,
    sseUrl,
    redirectUrl = DEFAULT_REDIRECT_URL,
    createClient = defaultCreateClient,
    createTransport = defaultCreateTransport,
  }) {
    if (auth !== "oauth" && auth !== "none") throw new Error(`Unknown MCP auth kind "${auth}"`);
    if (auth === "oauth" && !authStore) throw new Error("An OAuth MCP server needs an authStore");
    this.#store = authStore;
    this.#server = server;
    this.#auth = auth;
    this.#url = new URL(url);
    this.#sseUrl = sseUrl ? new URL(sseUrl) : sseUrlFor(this.#url);
    this.#redirectUrl = redirectUrl;
    this.#createClient = createClient;
    this.#createTransport = createTransport;
  }

  get server() {
    return this.#server;
  }

  get auth() {
    return this.#auth;
  }

  get url() {
    return this.#url.href;
  }

  get connected() {
    return this.#live !== null;
  }

async status() {
    return {
      connected: this.connected,
      server: this.#server,
      toolCount: this.tools?.length ?? null,
      serverInfo: this.serverInfo,
      // Stored tokens: worth a silent connect without asking anyone to log in.
      // A server without auth always is.
      authorized: this.#auth === "none" ? true : await this.#provider().hasTokens(),
      ...(this.lastError && !this.connected ? { error: this.lastError } : {}),
    };
  }

  /**
   * Connect with whatever is stored. Tokens that have expired are refreshed by
   * the SDK on the way; no tokens, or a refresh that fails, is `authUrl`.
   *
   * @returns {Promise<{ ok: true, serverInfo: object | null } | { ok: false, authUrl: string | null }>}
   */
  connect() {
    if (this.#live) return Promise.resolve({ ok: true, serverInfo: this.serverInfo });
    this.#connecting ??= this.#connect()
      .then((result) => {
        this.lastError = null;
        return result;
      })
      .catch((err) => {
        this.lastError = describeError(err);
        throw err;
      })
      .finally(() => {
        this.#connecting = null;
      });
    return this.#connecting;
  }

async #connect() {
    let first;
    const oauth = this.#auth === "oauth";
    // The SSE fallback is for hosted servers that predate streamable HTTP; a
    // server without auth is one of ours, and speaks the current transport.
    const kinds = /** @type {TransportKind[]} */ (oauth ? ["streamable", "sse"] : ["streamable"]);
    for (const kind of kinds) {
      const provider = oauth ? this.#provider() : null;
      try {
        return await this.#attempt(kind, provider);
      } catch (err) {
        // A 401 is an answer, not a transport problem: falling back to SSE
        // would only ask the same server the same question again.
        if (oauth && isUnauthorized(err)) return this.#needsAuth(provider);
        first ??= err;
        if (kind === "streamable" && kinds.length > 1) {
          console.warn(`[mcp:${this.#server}] streamable HTTP failed (${err?.message ?? err}); trying SSE`);
        }
      }
    }
    throw first;
  }

  async #attempt(kind, provider) {
    const transport = this.#createTransport({
      kind,
      url: kind === "sse" ? this.#sseUrl : this.#url,
      ...(provider ? { authProvider: provider } : {}),
    });
    const client = this.#createClient();
    try {
      await client.connect(transport);
    } catch (err) {
      this.#pending = { transport, provider };
      await client.close?.().catch(() => {});
      throw err;
    }

    this.#live = { client, transport, provider, kind };
    this.#pending = null;
    this.authUrl = null;
    this.serverInfo = client.getServerVersion?.() ?? null;
    client.onclose = () => {
      if (this.#live?.client === client) this.#drop();
    };
    return { ok: true, serverInfo: this.serverInfo };
  }

#needsAuth(provider) {
    this.authUrl = provider.authorizationUrl?.href ?? null;
    return { ok: false, authUrl: this.authUrl };
  }

  /**
   * The redirect came back: trade the code for tokens, then connect for real.
   *
   * @param {string} code
   * @param {string | undefined} state
   */
  async finishAuth(code, state) {
    if (this.#auth !== "oauth") throw new Error(`${this.#server} has no login to finish.`);
    const check = this.#provider();
    if (!(await check.checkState(state))) {
      throw new Error("OAuth state did not match — start the connection again.");
    }

    // The transport the login started on remembers where the resource
    // metadata was; after a restart a fresh one reads it from the store.
    const { transport } = this.#pending ?? {
      transport: this.#createTransport({ kind: "streamable", url: this.#url, authProvider: check }),
    };
    await transport.finishAuth(code);
    this.#pending = null;
    return this.connect();
  }

  /** Whether a callback's `state` belongs to a login this server started. */
  async ownsState(state) {
    return this.#auth === "oauth" && (await this.#provider().checkState(state));
  }

  /**
   * Every tool the server offers, every page of them.
   *
   * @returns {Promise<McpTool[]>}
   */
  async listTools() {
    const live = this.#live;
    if (!live) throw new Error("Not connected.");

const tools = [];
    const seen = new Set();
    let cursor;
    try {
      do {
        const page = await live.client.listTools(cursor ? { cursor } : undefined);
        tools.push(...(page?.tools ?? []));
        cursor = page?.nextCursor;
        // A server that hands back a cursor it already gave is a loop, not a
        // longer list.
        if (cursor && seen.has(cursor)) break;
        if (cursor) seen.add(cursor);
      } while (cursor);
    } catch (err) {
      await this.#onCallError(err, live);
      throw err;
    }

    // `outputSchema` too, when a server declares one: it is what tells the
    // pipeline planner the shape of a result before anything is called.
    this.tools = tools.map(({ name, description, inputSchema, outputSchema }) => ({
      name,
      description,
      inputSchema,
      ...(outputSchema ? { outputSchema } : {}),
    }));
    return this.tools;
  }

/**
   * Run one tool. Connects first if nothing is live, so a caller does not have
   * to know whether the panel was ever opened.
   *
   * A tool that fails *as a tool* comes back as a result with `isError: true`
   * — that is the server's answer. This throws only when there was no answer:
   * not connected, not authorized, the connection broke.
   *
   * @param {string} name
   * @param {object} [args]
   * @returns {Promise<{ content?: Array<{ type: string, text?: string }>, structuredContent?: object, isError?: boolean }>}
   */
  async callTool(name, args = {}) {
    if (!this.#live) {
      const result = await this.connect();
      if (!result.ok) throw new Error(`${this.#server} needs authorization — connect it in the MCP panel first.`);
    }
    const live = this.#live;
    try {
      return await live.client.callTool({ name, arguments: args });
    } catch (err) {
      await this.#onCallError(err, live);
      throw err;
    }
  }

  async #onCallError(err, live) {
    if (this.#auth === "oauth" && isUnauthorized(err)) {
      // The token died mid-session and could not be refreshed: back to
      // "needs auth", with the URL the SDK just produced.
      this.#needsAuth(live.provider);
      await this.close();
    }
  }

  async close() {
    const live = this.#live;
    this.#drop();
    await live?.client.close?.().catch(() => {});
  }

  /** Close, and forget the login: the next connect starts from scratch. */
  async disconnect() {
    await this.close();
    this.#pending = null;
    this.authUrl = null;
    this.lastError = null;
    if (this.#auth === "oauth") await this.#store.clear(this.#server);
  }

#drop() {
    this.#live = null;
    this.serverInfo = null;
    this.tools = null;
  }

  #provider() {
    return new StoredOAuthProvider({ store: this.#store, server: this.#server, redirectUrl: this.#redirectUrl });
  }
}

export const DEFAULT_REDIRECT_URL = "http://localhost:3000/mcp/oauth/callback";

export class StoredOAuthProvider {
  #store;
  #server;
  #redirectUrl;

  /** The URL the SDK wanted to send the user to, from the last attempt. @type {URL | null} */
  authorizationUrl = null;

  /**
   * @param {{ store: import("../store/mcpAuthStore.js").McpAuthStore, server: string, redirectUrl?: string }} options
   */
  constructor({ store, server, redirectUrl = DEFAULT_REDIRECT_URL }) {
    this.#store = store;
    this.#server = server;
    this.#redirectUrl = redirectUrl;
  }

  get redirectUrl() {
    return this.#redirectUrl;
  }

  get clientMetadata() {
    return {
      client_name: "first-agent",
      redirect_uris: [this.#redirectUrl],
      grant_types: ["authorization_code", "refresh_token"],
      response_types: ["code"],
      // A public client: no secret, PKCE instead.
      token_endpoint_auth_method: "none",
    };
  }

  /** A fresh `state` per authorization, kept so the callback can be checked. */
  async state() {
    const state = crypto.randomBytes(16).toString("base64url");
    await this.#patch((record) => {
      record.state = state;
    });
    return state;
  }

/** Whether a callback's `state` is the one we sent. */
  async checkState(state) {
    const { state: expected } = await this.#store.load(this.#server);
    if (!expected || typeof state !== "string") return false;
    const a = Buffer.from(expected);
    const b = Buffer.from(state);
    return a.length === b.length && crypto.timingSafeEqual(a, b);
  }

  async clientInformation() {
    return (await this.#store.load(this.#server)).clientInformation;
  }

  async saveClientInformation(clientInformation) {
    await this.#patch((record) => {
      record.clientInformation = clientInformation;
    });
  }

  async tokens() {
    return (await this.#store.load(this.#server)).tokens;
  }

  async saveTokens(tokens) {
    await this.#patch((record) => {
      record.tokens = tokens;
      // The login this verifier and state belonged to is over.
      delete record.codeVerifier;
      delete record.state;
    });
  }

  /** Not a browser: the URL is kept for whoever asked to connect. */
  redirectToAuthorization(authorizationUrl) {
    this.authorizationUrl = new URL(authorizationUrl);
  }

  async saveCodeVerifier(codeVerifier) {
    await this.#patch((record) => {
      record.codeVerifier = codeVerifier;
    });
  }

  async codeVerifier() {
    const { codeVerifier } = await this.#store.load(this.#server);
    if (!codeVerifier) throw new Error("No PKCE code verifier saved — start the authorization again.");
    return codeVerifier;
  }

async saveDiscoveryState(discoveryState) {
    await this.#patch((record) => {
      record.discoveryState = discoveryState;
    });
  }

  async discoveryState() {
    return (await this.#store.load(this.#server)).discoveryState;
  }

  /**
   * The SDK saying some of what we hold is no good: a revoked refresh token,
   * a registration the server has forgotten.
   *
   * @param {"all" | "client" | "tokens" | "verifier" | "discovery"} scope
   */
  async invalidateCredentials(scope) {
    if (scope === "all") return this.#store.clear(this.#server);
    await this.#patch((record) => {
      if (scope === "client") delete record.clientInformation;
      if (scope === "tokens") delete record.tokens;
      if (scope === "verifier") delete record.codeVerifier;
      if (scope === "discovery") delete record.discoveryState;
    });
  }

  /** Whether there is anything to try connecting with. */
  async hasTokens() {
    return Boolean((await this.#store.load(this.#server)).tokens?.access_token);
  }

  #patch(mutate) {
    return this.#store.update(this.#server, mutate);
  }
}

/**
 * Read at call time, not import time, so `.env` has been loaded by then.
 *
 * @param {Record<string, string | undefined>} [env]
 * @returns {McpServerDefinition[]}
 */
export function mcpServerDefinitions(env = process.env) {
  return [
    { id: "notion", name: "Notion", url: env.NOTION_MCP_URL || NOTION_MCP_URL, auth: "oauth" },
    { id: "omdb", name: "OMDb", url: env.OMDB_MCP_URL || OMDB_MCP_URL, auth: "none" },
    // Mostly called by the app's own code (the ticker and the schedule
    // routes); a scheduled agent's model sees only an allowlisted pair.
    { id: "scheduler", name: "Scheduler", url: env.SCHEDULER_MCP_URL || SCHEDULER_MCP_URL, auth: "none" },
  ];
}

/** One `McpClient` per registered server, built once and shared. */
export class McpRegistry {
  /** @type {Map<string, { definition: McpServerDefinition, client: McpClient }>} */
  #entries = new Map();

  /**
   * @param {{
   *   servers?: McpServerDefinition[],
   *   authStore?: import("../store/mcpAuthStore.js").McpAuthStore,
   *   redirectUrl?: string,
   *   createClient?: () => any,
   *   createTransport?: (options: object) => any,
   * }} [options] - The two factories are handed to every client, which is how
   *   the tests stand a whole registry up without a network.
   */
  constructor({ servers = mcpServerDefinitions(), authStore, redirectUrl = DEFAULT_REDIRECT_URL, createClient, createTransport } = {}) {
    for (const definition of servers) {
      if (this.#entries.has(definition.id)) throw new Error(`MCP server "${definition.id}" is registered twice`);
      const client = new McpClient({
        server: definition.id,
        url: definition.url,
        auth: definition.auth,
        authStore,
        redirectUrl,
        ...(createClient ? { createClient } : {}),
        ...(createTransport ? { createTransport } : {}),
      });
      this.#entries.set(definition.id, { definition: { ...definition }, client });
    }
  }

has(id) {
    return this.#entries.has(id);
  }

  /** @returns {McpClient | undefined} */
  get(id) {
    return this.#entries.get(id)?.client;
  }

  /** @returns {McpServerDefinition | undefined} */
  definition(id) {
    const entry = this.#entries.get(id);
    return entry ? { ...entry.definition } : undefined;
  }

  /** Every registered server, in order: one section each in the panel. */
  list() {
    return [...this.#entries.values()].map(({ definition }) => ({ ...definition }));
  }

  /** @returns {McpClient[]} */
  clients() {
    return [...this.#entries.values()].map(({ client }) => client);
  }

  async closeAll() {
    await Promise.all(this.clients().map((client) => client.close()));
  }
}

export const SEPARATOR = "__";
/** How much of a result is kept on the stored message. The model gets all of it. */
export const PREVIEW_CHARS = 1500;

/** And how much of a result the model gets: a runaway tool must not fill the context. */
export const MAX_RESULT_CHARS = 20000;

/** Anthropic's rule for a tool name: `^[a-zA-Z0-9_-]{1,64}$`. */
export function prefixedName(server, tool) {
  return `${server}${SEPARATOR}${tool}`.replace(/[^a-zA-Z0-9_-]/g, "_").slice(0, 64);
}

/** A result's text parts, joined; structured content only when there is no text. */
export function resultText(result) {
  const text = (result?.content ?? [])
    .map((part) => (part?.type === "text" ? part.text : part?.type ? `[${part.type} content]` : ""))
    .filter(Boolean)
    .join("\n");
  if (text) return text;
  return result?.structuredContent ? JSON.stringify(result.structuredContent) : "";
}

export function preview(text, limit = PREVIEW_CHARS) {
  const value = String(text ?? "");
  return value.length > limit ? value.slice(0, limit - 1) + "…" : value;
}

export class McpToolbox {
  #registry;
  /** Prefixed name → where it goes. Filled by `toolsFor`, read by `call`. @type {Map<string, { server: string, tool: string }>} */
  #routes = new Map();

  /** @param {{ registry: import("./servers.js").McpRegistry }} deps */
  constructor({ registry }) {
    this.#registry = registry;
  }

  /**
   * The tools of every server named, connecting to each on demand. A listing
   * is cached on the client, so a turn does not re-list what it listed last
   * turn.
   *
   * @param {string[]} serverIds
   * @returns {Promise<{ tools: Array<{ name: string, description: string, inputSchema: object }>, unavailable: Array<{ server: string, error: string }> }>}
   */
  async toolsFor(serverIds) {
    const tools = [];
    const unavailable = [];
    for (const server of serverIds ?? []) {
      const client = this.#registry.get(server);
      if (!client) {
        unavailable.push({ server, error: "not a registered MCP server" });
        continue;
      }
      try {
        const connected = await client.connect();
        if (!connected.ok) {
          unavailable.push({ server, error: "needs authorization" });
          continue;
        }
        const listed = client.tools ?? (await client.listTools());
        for (const tool of listed) {
          const name = prefixedName(server, tool.name);
          this.#routes.set(name, { server, tool: tool.name });
          tools.push({
            name,
            description: tool.description ?? "",
            inputSchema: tool.inputSchema ?? { type: "object", properties: {} },
          });
        }
      } catch (err) {
        unavailable.push({ server, error: describeError(err) });
      }
    }
    return { tools, unavailable };
  }

/** Which server and tool a prefixed name is. */
  route(name) {
    const known = this.#routes.get(name);
    if (known) return known;
    const at = String(name).indexOf(SEPARATOR);
    return at > 0 ? { server: name.slice(0, at), tool: name.slice(at + SEPARATOR.length) } : { server: "", tool: String(name) };
  }

  /**
   * @param {string} name - A prefixed name from `toolsFor`.
   * @param {object} input
   * @returns {Promise<{ server: string, tool: string, ok: boolean, text: string, preview: string, ms: number }>}
   */
  async call(name, input) {
    const { server, tool } = this.route(name);
    const started = Date.now();
    const client = this.#registry.get(server);
    const done = (ok, text) => ({ server, tool, ok, text, preview: preview(text), ms: Date.now() - started });
    if (!client) return done(false, `Unknown tool "${name}".`);
    try {
      const result = await client.callTool(tool, input ?? {});
      const text = resultText(result) || (result?.isError ? "The tool failed without saying why." : "(no output)");
      return done(!result?.isError, text.slice(0, MAX_RESULT_CHARS));
    } catch (err) {
      return done(false, `Tool call failed: ${describeError(err)}`);
    }
  }
}

import express from "express";

import { describeError, isUnauthorized } from "./mcp/mcpClient.js";

/**
 * **The MCP routes: connect, log in, list tools, disconnect — per server.**
 *
 * `/mcp/servers` lists what is registered; everything else is
 * `/mcp/:server/…` and goes through that server's `McpClient`, so none of it
 * knows about transports, OAuth or the SDK, and none of it knows which server
 * is Notion. Two answers are states the UI draws, not errors:
 *
 *   - a 401 — no tokens, or tokens the SDK could not refresh — is
 *     `200 { ok: false, authUrl }`: a Connect button;
 *   - a server that cannot be reached is `200 { ok: false, connected: false,
 *     error }`: a red dot with the reason.
 *
 * A server with `auth: "none"` never produces an `authUrl`.
 *
 * @param {{ registry: import("./mcp/servers.js").McpRegistry }} deps
 */
export function mcpRoutes({ registry }) {
  const router = express.Router();

  router.get("/mcp/servers", (_req, res) => {
    res.json({ servers: registry.list().map(({ id, name, auth }) => ({ id, name, auth })) });
  });

// The OAuth callback is one URL for every OAuth server — it is what was
  // registered with them — so the `state` decides whose login it finishes.
  // Declared before the `:server` routes so "oauth" is never read as an id.
  router.get("/mcp/oauth/callback", async (req, res) => {
    const { code, state, error, error_description: description } = req.query;
    if (error) {
      return res.status(400).type("html").send(page("Not connected", String(description || error), false));
    }
    if (typeof code !== "string" || !code) {
      return res.status(400).type("html").send(page("Not connected", "The callback had no authorization code.", false));
    }

    try {
      const mcp = await ownerOf(registry, typeof state === "string" ? state : undefined);
      if (!mcp) throw new Error("OAuth state did not match — start the connection again.");
      const result = await mcp.finishAuth(code, state);
      if (!result.ok) {
        return res.status(401).type("html").send(page("Not connected", "The server still wants authorization.", false, mcp.server));
      }
      res.type("html").send(page("Connected", `${nameOf(registry, mcp.server)} is connected. You can close this tab.`, true, mcp.server));
    } catch (err) {
      console.error("[/mcp/oauth/callback]", err?.message ?? err);
      res.status(400).type("html").send(page("Not connected", String(err?.message ?? err), false));
    }
  });

  /** Resolve `:server`, or answer 404 and return nothing. */
  const client = (req, res) => {
    const mcp = registry.get(req.params.server);
    if (!mcp) res.status(404).json({ ok: false, error: `No MCP server "${req.params.server}".` });
    return mcp;
  };

router.get("/mcp/:server/status", async (req, res) => {
    const mcp = client(req, res);
    if (!mcp) return;
    try {
      const { name, auth } = registry.definition(mcp.server);
      res.json({ ...(await mcp.status()), name, auth });
    } catch (err) {
      console.error(`[/mcp/${mcp.server}/status]`, err?.message ?? err);
      res.status(500).json({ error: "Could not read the MCP status." });
    }
  });

  router.post("/mcp/:server/connect", async (req, res) => {
    const mcp = client(req, res);
    if (!mcp) return;
    try {
      const result = await mcp.connect();
      if (result.ok) return res.json({ ok: true, connected: true, serverInfo: result.serverInfo });
      res.json({ ok: false, connected: false, authUrl: result.authUrl });
    } catch (err) {
      console.warn(`[/mcp/${mcp.server}/connect]`, describeError(err));
      res.json({ ok: false, connected: false, error: unreachable(registry, mcp, err) });
    }
  });

router.get("/mcp/:server/tools", async (req, res) => {
    const mcp = client(req, res);
    if (!mcp) return;
    try {
      const connected = await mcp.connect();
      if (!connected.ok) return res.json({ ok: false, authUrl: connected.authUrl, tools: [] });
      const tools = await mcp.listTools();
      res.json({ ok: true, tools });
    } catch (err) {
      if (mcp.auth === "oauth" && isUnauthorized(err)) return res.json({ ok: false, authUrl: mcp.authUrl, tools: [] });
      console.warn(`[/mcp/${mcp.server}/tools]`, describeError(err));
      res.json({ ok: false, connected: false, error: unreachable(registry, mcp, err), tools: [] });
    }
  });

  router.post("/mcp/:server/disconnect", async (req, res) => {
    const mcp = client(req, res);
    if (!mcp) return;
    try {
      await mcp.disconnect();
      res.json({ ok: true });
    } catch (err) {
      console.error(`[/mcp/${mcp.server}/disconnect]`, err?.message ?? err);
      res.status(500).json({ ok: false, error: "Could not disconnect." });
    }
  });

  return router;
}

/** Which OAuth server started the login this `state` belongs to. */
async function ownerOf(registry, state) {
  if (!state) return null;
  for (const mcp of registry.clients()) {
    if (await mcp.ownsState(state).catch(() => false)) return mcp;
  }
  return null;
}

function nameOf(registry, id) {
  return registry.definition(id)?.name ?? id;
}

function unreachable(registry, mcp, err) {
  return `Could not reach ${nameOf(registry, mcp.server)} at ${mcp.url}: ${describeError(err)}`;
}

/**
 * The page the popup lands on. It tells the opener, then tries to close
 * itself; the text is for the browsers that will not let it.
 */
function page(title, message, ok, server = null) {
  const text = escapeHtml(message);
  return `<!doctype html>
<meta charset="utf-8">
<title>${escapeHtml(title)}</title>
<meta name="color-scheme" content="light dark">
<body style="font: 14px system-ui, sans-serif; padding: 40px; max-width: 480px; margin: auto">
<h1 style="font-size: 18px">${escapeHtml(title)}</h1>
<p>${text}</p>
<p><a href="/">Back to the app</a></p>
<script>
  try { window.opener && window.opener.postMessage({ type: "mcp-auth", server: ${JSON.stringify(server).replace(/</g, "\\u003c")}, ok: ${ok ? "true" : "false"} }, location.origin); } catch (e) {}
  ${ok ? "setTimeout(() => window.close(), 800);" : ""}
</script>
</body>`;
}

function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);
}

import express from "express";

import { agentFor, agentOf, isValidAgent } from "./agents.js";
import { exchangeStarts } from "./context/boundaries.js";
import { compareProfiles } from "./context/comparison.js";
import { createStrategy } from "./context/index.js";
import { isValidSessionId, memoryOf } from "./store/conversationStore.js";
import { DEFAULT_PROJECT, isValidProject } from "./store/invariantStore.js";
import { DEFAULT_USER, isValidUser } from "./store/profileStore.js";

/**
   * Load the record and hand its memory state to `work`. Whatever comes back is
   * persisted and answered with a fresh panel — so every handler below is three
   * lines about memory and nothing about storage.
   */
  async function onConversation(req, res, work) {
    const { id } = req.params;
    if (!isValidSessionId(id)) {
      return res.status(400).json({ error: "Not a valid conversation id." });
    }

    let record;
    try {
      record = await store.load(id);
    } catch (err) {
      console.error("[memory] could not load the conversation:", err);
      return res.status(500).json({ error: "Could not load that conversation." });
    }
    // **A conversation nobody has spoken in yet is a real state, not an
    // error.** The page mints a session id when it opens and the record is
    // only written on the first turn, so a 404 here meant *every button in the
    // memory panel was dead until you had said something* — the profile
    // editor, and now the invariant box, which is the one thing in the panel
    // that has nothing to do with the conversation at all. You should be able
    // to write down the rules of a project before typing a word at it.
    //
    // This is the argument `/memory/compare` below already makes for itself,
    // applied where it belongs: in the one helper every memory route shares.
    // The record is an empty conversation — exactly what the store would have
    // created — and it reaches disk only if the handler succeeds.
    record ??= { messages: [], memory: {} };

// Which agent this conversation belongs to. The record's answer wins, the
    // same way the project's does — and the request is only consulted for a
    // conversation that does not exist yet. **Leaving this out is the bug that
    // hides here:** the record below is written, and an `agentId` the save did
    // not carry would silently move a brand-new chat to the default agent the
    // first time anything in the panel was clicked.
    const agentId = isValidAgent(record.agentId)
      ? record.agentId
      : agentOf(req.body?.agent);

    // Whose long-term memory this request is about. It arrives with the
    // request because the picker is in the topbar rather than in the
    // conversation: the same conversation can be replayed against two
    // profiles, which is the whole point of the comparison below.
    const user = profileId(req.body?.profile);
    // Which project's rules this request is about. It arrives with the request
    // like the profile does — the picker is in the topbar, not in the
    // conversation — and the record remembers the last answer, so reopening a
    // chat does not quietly move it under another set of rules.
    const project = projectId(req.body?.project) ?? record.project ?? DEFAULT_PROJECT;
    const strategy = createStrategy("memory", { profileStore, invariantStore, user, project });
    const history = record.messages ?? [];
    const turns = exchangeStarts(history).length;
    const stored = memoryOf(record.memory);
    const state = Object.keys(stored).length ? stored : strategy.emptyState();

    let result;
    try {
      result = await work({ strategy, state, history, turns });
    } catch (err) {
      // These are user mistakes — an id that is not there, an answer that is
      // neither yes nor no — far more often than they are server faults.
      console.error("[memory]", err?.message ?? err);
      return res.status(400).json({ error: err?.message ?? "Could not change memory." });
    }

try {
      await store.save(id, record.messages, record.usage, {
        memory: result.state,
        project,
        agentId,
      });
    } catch (err) {
      console.error("[memory] could not persist the change:", err);
      return res.status(500).json({ error: "Could not save that change." });
    }
    // The cached Agent is holding the state as it was a moment ago. Left in
    // place it would write that back over this on the next turn.
    invalidate(id);

    // The panel is built synchronously, so what it should draw is read here,
    // where awaiting is allowed. Without this a conversation nobody has spoken
    // in yet draws an empty rule set and an empty profile — which is a
    // different claim from "nothing has been sent yet", and the wrong one.
    const [liveInvariants, liveProfile] = await Promise.all([
      invariantStore.load(project).catch(() => null),
      profileStore.load(user).catch(() => null),
    ]);

    res.json({
      ok: result.ok !== false,
      note: result.note ?? "",
      panel: strategy.panel(result.state, {
        turns,
        invariants: liveInvariants,
        profile: liveProfile,
        user,
        project,
      }),
      ...(result.extra ?? {}),
    });
  }

/**
   * **One edge of the state machine, as HTTP.**
   *
   * Every stage change in the app is this request — the strip's buttons, and
   * a model proposal only after somebody has clicked it. There is no separate
   * *Finish task* endpoint any more: `→ done` is this route with
   * `to: "done"`, and the promotion call, the proposals and the clearing into
   * `pastTasks` happen on the way in, inside `transition`, exactly once.
   *
   * An illegal or guarded edge comes back `ok: false` with the guard's own
   * sentence and the state untouched. It is a 200 rather than a 400: the
   * request was well formed and the answer is "no, and here is why", which is
   * a thing the strip renders rather than an error it reports.
   *
   * The proposals it may return are **pending** and live in the conversation
   * record. Nothing here writes to the profile store — an unapproved write
   * must not exist in long-term, not even with a flag on it, because every
   * flag is one forgotten `WHERE` clause away from being read as fact.
   */
  router.post("/conversations/:id/memory/transition", (req, res) =>
    onConversation(req, res, async ({ strategy, state, history }) => {
      const to = text(req.body?.to);
      if (!to) throw new Error("A 'to' stage is required.");
      const moved = await strategy.transition({
        state,
        to,
        // The model never sends this request. A proposal it made is applied by
        // the person who clicked the button beside it, and `by` records that
        // honestly rather than crediting the click to whoever suggested it.
        by: "user",
        reason: text(req.body?.reason),
        history,
        provider,
      });
      return {
        ok: moved.ok,
        state: moved.state,
        note: moved.note,
        extra: {
          proposals: moved.proposals ?? [],

warning: moved.warning ?? null,
          // Leaving planning does not move the stage on this request: it
          // writes a brief and waits. The flag tells the page to render the
          // editor rather than to expect a stage that has changed.
          awaitingBrief: moved.awaitingBrief === true,
        },
      };
    })
  );

/**
   * The handoff, answered.
   *
   * `→ execution` writes a brief and stops; this is the other half. Accepting
   * it is what actually leaves planning, and the text that arrives here is the
   * text that gets stored — this is the moment a person is allowed to disagree
   * with what the model understood, and the last moment it is cheap.
   */
  router.post("/conversations/:id/memory/brief", (req, res) =>
    onConversation(req, res, async ({ strategy, state, history }) => {
      const action = text(req.body?.action);
      if (action !== "accept" && action !== "discard") {
        throw new Error("An answer is either 'accept' or 'discard'.");
      }
      const answered = await strategy.answerBrief({
        state,
        history,
        action,
        text: typeof req.body?.text === "string" ? req.body.text : undefined,
        // Which of the brief's open questions to leave out. Absent, empty or
        // wrong all mean *record every one of them*, which is the direction
        // this should fail in: a page that sends a stale key must not quietly
        // throw away the record the accept exists to create.
        drop: Array.isArray(req.body?.drop)
          ? req.body.drop.map((value) => text(value).toLowerCase()).filter(Boolean).slice(0, 12)
          : [],
      });
      return {
        ok: answered.ok,
        state: answered.state,
        note: answered.note,
        extra: { warning: answered.warning ?? null },
      };
    })
  );

/**
   * *Start a new task* — the only thing offered once a task is `done`.
   *
   * `done` never reopens, so resuming is a fresh record in `planning` that
   * carries the finished task's id. It takes no model call and changes no
   * memory: working memory was already cleared on the way into `done`.
   */
  router.post("/conversations/:id/memory/new-task", (req, res) =>
    onConversation(req, res, async ({ strategy, state }) => {
      const started = strategy.startTask({ state });
      return { ok: started.ok, state: started.state, note: started.note };
    })
  );

/**
   * **Typed prose in, structured proposals out.** One model call, read-only,
   * writes nothing.
   *
   * It is not a turn — no persona, no reply, nothing appended to the
   * transcript — and it is the only new call the whole feature adds. It fires
   * when somebody presses a button, never on a turn, because a cost you did
   * not press is a cost you press four times by accident.
   *
   * What comes back is rows for a review box, every field editable. Accepting
   * one goes to `/memory/ops` like every other write, with `origin: 'person'`
   * — which is what keeps the namespace person-only: **the accept is the
   * write**, and there is no other door into it.
   */
  router.post("/conversations/:id/memory/invariants/propose", (req, res) =>
    onConversation(req, res, async ({ strategy, state, turns }) => {
      const typed = typeof req.body?.text === "string" ? req.body.text : "";
      const proposed = await strategy.proposeInvariants({ state, text: typed, turns, provider });
      return {
        ok: proposed.ok,
        // The state is handed back because the call is billed to the
        // conversation's overhead — it is the only thing about it that
        // changes, and leaving it out would make the one figure that says what
        // memory costs quietly wrong.
        state: proposed.state,
        note: proposed.note,
        extra: { rows: proposed.rows },
      };
    })
  );

/** Approve — with an edit, if the phrasing was wrong — or reject. */
  router.post("/conversations/:id/memory/proposals/:proposalId", (req, res) =>
    onConversation(req, res, async ({ strategy, state, turns }) => {
      const action = text(req.body?.action);
      if (action !== "approve" && action !== "reject") {
        throw new Error("An answer is either 'approve' or 'reject'.");
      }
      return await strategy.answerProposal({
        state,
        id: req.params.proposalId,
        action,
        value: typeof req.body?.value === "string" ? req.body.value : undefined,
        turns,
      });
    })
  );

/**
   * *Forget* and *promote*, from the panel — the same `applyOps` path the
   * extractor's patch takes, so there is one code path to test rather than a
   * second one that only the UI can reach.
   */
  router.post("/conversations/:id/memory/ops", (req, res) =>
    onConversation(req, res, async ({ strategy, state, turns }) => {
      const ops = Array.isArray(req.body?.ops) ? req.body.ops.slice(0, 40) : null;
      if (!ops?.length) throw new Error("An 'ops' array is required.");
      // The profile editor is not a second write path — it is this one, with a
      // flag saying the sentences came from the user rather than from a model.
      // That flag is the only thing `declared` provenance means, and putting
      // the form anywhere else would be the second code path with no test
      // behind it that `applyOps` exists to prevent.
      // `acknowledged` is the one way past the invariant check, and it is
      // only ever the key of a collision row the person is answering. It is
      // named in the request rather than inferred, so "a human waved this
      // through" is a thing you can see in the log rather than a mood the
      // server was in.
      const acknowledged = Array.isArray(req.body?.acknowledged)
        ? req.body.acknowledged.map((value) => text(value).toLowerCase()).filter(Boolean).slice(0, 40)
        : [];
      return await strategy.applyPanelOps({
        state,
        ops,
        turns,
        declared: req.body?.declared === true,
        acknowledged,
      });
    })
  );

/**
   * **The comparison: same message, same history, N profiles, side by side.**
   *
   * It does not go through `onConversation`, and that is the point rather than
   * an oversight. `onConversation` loads the record, hands the state to the strategy
   * and then **saves** — which is right for every other handler here, because
   * every other handler is a user changing memory on purpose. This one is a
   * user *looking* at memory, and looking must not write. So it reads the
   * record, never touches `store.save`, and hands the profile store to
   * `compareProfiles`, which wraps it in a read-only view before any arm can
   * reach it.
   */
  router.post("/conversations/:id/memory/compare", async (req, res) => {
    const { id } = req.params;
    if (!isValidSessionId(id)) return res.status(400).json({ error: "Not a valid conversation id." });

    let record;
    try {
      record = await store.load(id);
    } catch (err) {
      console.error("[memory] could not load the conversation:", err);
      return res.status(500).json({ error: "Could not load that conversation." });
    }


    // A comparison on a conversation that does not exist yet is still a
    // comparison: an empty history is the most common way to ask this
    // question, and refusing it would mean opening a chat, saying something
    // and only then being allowed to see what the profiles do.
    const history = record?.messages ?? [];
    const state = record?.memory ?? null;

    const profiles = Array.isArray(req.body?.profiles)
      ? req.body.profiles.map((value) => text(value)).filter((value) => isValidUser(value)).slice(0, 4)
      : [];
    if (profiles.length < 2) {
      return res.status(400).json({ error: "Pick at least two profiles to compare." });
    }

try {
      const comparison = await compareProfiles({
        message: text(req.body?.message),
        history,
        state,
        // Answered as the agent whose conversation this is. Comparing two
        // profiles under a persona the conversation has never used would vary
        // two things and call the difference one of them.
        systemPrompt: agentFor(record?.agentId ?? req.body?.agent).systemPrompt,
        provider,
        profileStore,
        profiles,
        invariantStore,
        projects: Array.isArray(req.body?.projects)
          ? req.body.projects.map((value) => text(value)).filter((value) => isValidProject(value)).slice(0, 4)
          : [],
        samples: Number(req.body?.samples) || 3,
        contextMessages: Number(req.body?.contextMessages) || 10,
        maxTokens: Number(req.body?.maxTokens) || 1024,
      });
      res.json({ ok: true, ...comparison });
    } catch (err) {
      console.error("[memory] the comparison failed:", err?.message ?? err);
      res.status(400).json({ error: err?.message ?? "Could not run the comparison." });
    }
  });

  return router;
}

function text(value) {
  return typeof value === "string" && value.trim() ? value.trim() : "";
}

/**
 * A profile id from a request body, refused before it can become a path.
 *
 * The store throws on a bad id, which is the right behaviour there and the
 * wrong error here: a browser sending nonsense should get the default profile
 * and a working app, not a 500 from a filesystem call two layers down.
 */
function profileId(value) {
  const id = text(value).toLowerCase();
  return isValidUser(id) ? id : DEFAULT_USER;
}

/**
 * A project id from a request body, or null when none was sent.
 *
 * Null rather than the default on purpose: "the request did not say" and "the
 * request said `default`" are different, and only the first should fall back
 * to whatever the conversation record already holds.
 */
function projectId(value) {
  const id = text(value).toLowerCase();
  return isValidProject(id) ? id : null;
}

export const SUBMIT_PLAN = "submit_plan";
export const PLANNER_MAX_TOKENS = 4096;
/** How much of one step's output a repair prompt carries, as JSON. */
export const MAX_REPAIR_OUTPUT_CHARS = 2000;

const TEXT = { type: "string" };

/** The one tool the planner is given, and made to call. */
export const SUBMIT_PLAN_TOOL = {
  name: SUBMIT_PLAN,
  description: "Submit the whole pipeline plan: every step, in order. Call it exactly once.",
  inputSchema: {
    type: "object",
    properties: {
      steps: {
        type: "array",
        minItems: 1,
        description: "The steps, in the order they run.",
        items: {
          type: "object",
          properties: {
            kind: { type: "string", enum: ["tool", "prompt"] },
            tool: { ...TEXT, description: 'Tool steps: the catalog name, exactly, e.g. "omdb.get_movie".' },
            args: { type: "object", description: "Tool steps: the arguments, matching the tool's inputSchema. Strings may hold templates." },
            text: { ...TEXT, description: "Prompt steps: the whole instruction, with the data it needs inlined through templates." },
            format: { type: "string", enum: ["text", "json"], description: 'Prompt steps: "text" (default) or "json".' },
            outputSchema: {
              type: "object",
              description: 'Json prompt steps: the JSON Schema of the object it returns ({ type: "object", properties, required }).',
            },
            why: { ...TEXT, description: "One short sentence: why this step, and why this tool." },
          },
          required: ["kind", "why"],
        },
      },
      notes: { ...TEXT, description: "Optional: anything the person should know — an assumption, or what could not be planned." },
    },
    required: ["steps"],
  },
};

Example (the shape, not the tools: use the catalog's). Goal: "Fetch the two products, choose the cheaper one, write a one-line ad for it, post the ad, and log which one won."
1. tool shop.get_product { "sku": "A-1" }
2. tool shop.get_product { "sku": "B-2" }
3. prompt, format json: "Two products:\n{{steps.1}}\n{{steps.2}}\nChoose the cheaper one. Return its sku and name, and a one-line ad for it." outputSchema { sku, name, ad } (all required)
4. tool social.post { "text": "{{steps.3.ad}}" }
5. tool log.write { "key": "{{steps.3.sku}}", "label": "{{steps.3.name}}" }
One json step makes the choice and writes the text; the ids it returns are what later steps key on.

Call ${SUBMIT_PLAN} once, with the whole plan.`;

/**
 * **What the planner may use**: the tools of the servers it is allowed,
 * filtered to its allowlist, from each server's live listing.
 *
 * A server that cannot be reached — or needs a login — contributes nothing
 * and is listed in `down` with the reason, so the planner can be told.
 *
 * @param {{
 *   registry: import("../mcp/servers.js").McpRegistry,
 *   allow: Record<string, string[] | "*">,
 * }} params - `allow` names the servers and, per server, the tools (or "*").
 * @returns {Promise<import("./validatePlan.js").Catalog>}
 */
export async function buildCatalog({ registry, allow }) {
  const tools = [];
  const down = [];
  for (const [server, names] of Object.entries(allow)) {
    const client = registry.get(server);
    if (!client) {
      down.push({ server, error: "not a registered MCP server" });
      continue;
    }
    let listed;
    try {
      const connected = await client.connect();
      if (!connected.ok) {
        down.push({ server, error: "needs authorization: connect it in the MCP panel" });
        continue;
      }
      listed = client.tools ?? (await client.listTools());
    } catch (err) {
      down.push({ server, error: describeError(err) });
      continue;
    }
    for (const tool of listed) {
      if (names !== "*" && !names.includes(tool.name)) continue;
      tools.push(catalogEntry(server, tool));
    }
  }
  return { tools, down };
}

/** One listed tool as the planner sees it: namespaced, with no field it must not fill. */
export function catalogEntry(server, tool) {
  const inputSchema = withoutField(tool.inputSchema ?? { type: "object", properties: {} }, "scheduleId");
  return {
    name: `${server}.${tool.name}`,
    server,
    tool: tool.name,
    description: tool.description ?? "",
    inputSchema,
    ...(tool.outputSchema ? { outputSchema: tool.outputSchema } : {}),
  };
}

/**
 * `submit_plan`'s input, as steps in the stored format. Nothing is dropped or
 * repaired here — whatever is wrong is the validator's to say — except that a
 * tool step's `server.tool` is split and a prompt step's format is spelled out.
 */
export function stepsFromSubmission(input) {
  const steps = Array.isArray(input?.steps) ? input.steps : [];
  return steps.map((step) => {
    if (!step || typeof step !== "object") return step;
    const { kind, tool, args, text, format, outputSchema, why, ...rest } = step;
    const reason = typeof why === "string" ? { why: why.trim() } : why === undefined ? {} : { why };
    if (kind === "tool") {
      const name = String(tool ?? "");
      const dot = name.indexOf(".");
      return {
        kind,
        server: dot > 0 ? name.slice(0, dot) : "",
        tool: dot > 0 ? name.slice(dot + 1) : name,
        args: args ?? {},
        ...reason,
        ...rest,
      };
    }
    if (kind === "prompt") {
      return { kind, text, format: format ?? "text", ...(outputSchema !== undefined ? { outputSchema } : {}), ...reason, ...rest };
    }
    return step;
  });
}

/** The catalog as the planner reads it: one block per tool. */
export function describeCatalog(catalog) {
  const blocks = catalog.tools.map((tool) =>
    [
      `### ${tool.name}`,
      tool.description.trim() || "(no description)",
      `inputSchema: ${JSON.stringify(stripDraft(tool.inputSchema))}`,
      tool.outputSchema
        ? `outputSchema: ${JSON.stringify(stripDraft(tool.outputSchema))}`
        : "outputSchema: none declared — its output shape is unknown: use it whole, or reshape it with a json prompt step.",
    ].join("\n")
  );
  const down = catalog.down.length
    ? catalog.down.map(({ server, error }) => `- ${server}: ${error}`).join("\n")
    : "(none — every registered server is up)";
  return `## Catalog: the only tools that exist\n\n${blocks.join("\n\n") || "(empty)"}\n\n## Servers that are down right now (their tools are not in the catalog)\n${down}`;
}

function stripDraft(schema) {
  if (!schema || typeof schema !== "object") return schema;
  const { $schema: _draft, ...rest } = schema;
  return rest;
}

export class Planner {
  #provider;
  #catalog;
  #model;
  #maxTokens;
  #now;

  /**
   * @param {{
   *   provider: import("../llm/provider.js").LlmProvider,
   *   catalog: () => Promise<import("./validatePlan.js").Catalog>,
   *   model?: string,
   *   maxTokens?: number,
   *   now?: () => number,
   * }} deps - `catalog` is read fresh on every plan, so a server that just
   *   came up (or went down) is seen.
   */
  constructor({ provider, catalog, model, maxTokens = PLANNER_MAX_TOKENS, now = Date.now }) {
    this.#provider = provider;
    this.#catalog = catalog;
    this.#model = model;
    this.#maxTokens = maxTokens;
    this.#now = now;
  }

  /**
   * A plan for a goal.
   *
   * @param {{ goal: string }} params
   * @returns {Promise<PlanResult>}
   */
  async propose({ goal }) {
    const catalog = await this.#catalog();
    const ask = `${describeCatalog(catalog)}\n\n## Goal\n${goal.trim()}\n\nPlan it.`;
    return this.#plan(ask, catalog);
  }

/**
   * A corrected plan for a run that failed.
   *
   * @param {{ goal: string, plan: object[], run: { id: number, error: string }, steps?: object[] }} params -
   *   `steps` is what each step of the failed run did (index, status, output, error).
   * @returns {Promise<PlanResult>}
   */
  async repair({ goal, plan, run, steps = [] }) {
    const catalog = await this.#catalog();
    const outputs = steps.map((step) => ({
      step: step.index,
      status: step.status,
      ...(step.input !== undefined ? { input: capped(step.input) } : {}),
      ...(step.output !== undefined ? { output: capped(step.output) } : {}),
      ...(step.error ? { error: step.error } : {}),
    }));
    const ask = [
      describeCatalog(catalog),
      `## Goal\n${goal.trim() || "(no goal was written: infer it from the plan)"}`,
      `## The plan that ran\n${JSON.stringify(plan, null, 2)}`,
      `## What happened\nRun #${run.id} failed: ${run.error}\n\nStep by step:\n${JSON.stringify(outputs, null, 2)}`,
      "Propose a corrected plan that reaches the goal and avoids this failure. Change only what the failure calls for. " +
        "If the failure is outside the plan's control (a server that is down, a missing login), keep the plan and say so in notes.",
    ].join("\n\n");
    return this.#plan(ask, catalog);
  }

async #plan(ask, catalog) {
    const messages = [{ role: "user", content: ask }];
    const usage = { inputTokens: 0, outputTokens: 0 };
    let attempt;
    let firstErrors = [];
    for (let round = 1; round <= 2; round++) {
      attempt = await this.#submit(messages, usage);
      attempt.errors = attempt.called ? validatePlan(attempt.steps, catalog) : [`The planner did not call ${SUBMIT_PLAN}.`];
      if (!attempt.errors.length) break;
      if (round === 2) break;
      firstErrors = attempt.errors;

      // One retry, with every problem in it.
      const problems = `The plan did not validate:\n${attempt.errors.map((error) => `- ${error}`).join("\n")}\n\n` +
        `Fix every problem and call ${SUBMIT_PLAN} again with the whole corrected plan.`;
      if (attempt.use) {
        messages.push(
          { role: "assistant", content: attempt.content },
          { role: "user", content: [{ type: "tool_result", toolUseId: attempt.use.id, content: problems, isError: true }] }
        );
      } else {
        messages.push({ role: "assistant", content: attempt.text || "(no plan)" }, { role: "user", content: problems });
      }
    }
    return {
      ok: !attempt.errors.length,
      steps: attempt.steps,
      notes: attempt.notes,
      errors: attempt.errors,
      attempts: messages.length === 1 ? 1 : 2,
      firstErrors,
      usage,
      createdAt: new Date(this.#now()).toISOString(),
    };
  }

async #submit(messages, usage) {
    const result = await completeWithRetry(this.#provider, {
      system: PLANNER_SYSTEM,
      messages,
      tools: [SUBMIT_PLAN_TOOL],
      toolChoice: { name: SUBMIT_PLAN },
      model: this.#model,
      maxTokens: this.#maxTokens,
      temperature: 0,
    });
    usage.inputTokens += result.usage?.inputTokens ?? 0;
    usage.outputTokens += result.usage?.outputTokens ?? 0;
    const use = (result.content ?? []).find((block) => block.type === "tool_use" && block.name === SUBMIT_PLAN);
    const notes = typeof use?.input?.notes === "string" ? use.input.notes.trim() : "";
    return {
      called: Boolean(use),
      use,
      content: result.content,
      text: result.text,
      steps: use ? stepsFromSubmission(use.input) : [],
      notes,
    };
  }
}

/**
 * @typedef {{
 *   ok: boolean, steps: object[], notes: string, errors: string[], attempts: 1 | 2, firstErrors: string[],
 *   usage: { inputTokens: number, outputTokens: number }, createdAt: string,
 * }} PlanResult - `errors` are the last attempt's; empty when `ok`.
 *   `firstErrors` are what the retry was asked to fix (empty with no retry).
 */

function capped(value) {
  const json = JSON.stringify(value);
  if (json === undefined || json.length <= MAX_REPAIR_OUTPUT_CHARS) return value;
  return `${json.slice(0, MAX_REPAIR_OUTPUT_CHARS)}… (${json.length} characters in all)`;
}

/**
 * **After a failed run: a corrected plan, as a proposal.**
 *
 * The ticker calls this once per failed run. It asks the planner for a repair
 * — the goal, the plan that ran, what each step produced and the error — and
 * stores the answer as the schedule's pending proposal, reason "repair", with
 * the failed run beside it. It never touches the plan: the next interval run
 * executes the same accepted plan, and nothing changes until a person accepts.
 *
 * A repair the planner could not make valid is stored too, with its errors, so
 * the panel can say so; it cannot be accepted. A proposal that is already
 * pending — a repair of an earlier failure, or a plan the person generated —
 * is left alone: a pipeline failing every 15 seconds asks the planner once,
 * not every tick, and never overwrites what somebody is looking at.
 *
 * @param {{
 *   planner: Pick<import("./planner.js").Planner, "repair">,
 *   scheduler: Pick<import("../scheduler/client.js").SchedulerClient, "getSchedule" | "updateSchedule">,
 *   log?: Pick<Console, "log">,
 * }} deps
 * @returns {(failed: { run: { id: number }, schedule: object, outcome: { error?: string, steps?: object[] } }) => Promise<object | null>}
 *   The stored proposal, or null when there was nothing to do.
 */
export function repairer({ planner, scheduler, log = console }) {
  return async ({ run, schedule, outcome }) => {
    const current = (await scheduler.getSchedule(schedule.conversationId)) ?? schedule;
    if (!current.plan?.length) return null;
    if (current.proposal) {
      log.log(`[repair] run ${run.id} failed; schedule ${current.id} already has a proposal pending, so no new one`);
      return null;
    }

const failed = { id: run.id, error: outcome.error ?? "The run failed without saying why." };
    const result = await planner.repair({ goal: current.goal ?? "", plan: current.plan, run: failed, steps: outcome.steps ?? [] });
    const proposal = {
      steps: result.steps,
      ...(result.notes ? { notes: result.notes } : {}),
      createdAt: result.createdAt,
      reason: "repair",
      run: failed,
      ...(result.ok ? {} : { errors: result.errors }),
    };
    await scheduler.updateSchedule(current.id, { proposal });
    log.log(`[repair] run ${run.id} failed; proposed a ${result.ok ? "" : "(still invalid) "}repair for schedule ${current.id}`);
    return proposal;
  };
}

import { agentFor } from "../agents.js";
import { estimateCost } from "../llm/pricing.js";
import { describeError, isUnauthorized } from "../mcp/mcpClient.js";
import { resultText } from "../mcp/toolbox.js";
import { scopedTools } from "../scheduler/scope.js";
import { emptyUsage, nextMessageId } from "../store/conversationStore.js";
import { addCounts, completeWithRetry, runToolLoop } from "../toolLoop.js";
import { validationErrors } from "./schemas.js";
import { interpolate, resolve } from "./templates.js";

export const MAX_STEP_TOOL_ROUNDS = 5;
/**
 * A prompt step's output ceiling. A json step that writes a page of text plus
 * its fields needs well over 1024; one that hits the ceiling fails as such,
 * never as a half-written answer.
 */
export const STEP_MAX_TOKENS = 4096;

export const SCOPE_NOTE =
  "scheduleId context is handled for you: the record and aggregate tools already belong to this task's " +
  "schedule, so never ask for one or pass one.";

/** The message is for reading; the full output is on the stored step. */
export const MAX_MESSAGE_CHARS = 20000;
/**
 * Scheduler tools that belong to the run's own schedule. The planner never
 * sees their `scheduleId`; the runner always fills it in, overruling whatever
 * a step says, so a plan can only ever write to its own schedule.
 */
const OWN_SCHEDULE_TOOLS = new Set(["record", "aggregate"]);

/** The tool a json prompt step answers through. */
export const RESPOND_TOOL = "respond";

/** A step that failed, with the input it had resolved by then (if it got that far). */
class StepFailure extends Error {
  constructor(message, input) {
    super(message);
    this.name = "StepFailure";
    this.input = input;
  }
}

/** What a step is called on the strip: the tool it calls, or "prompt". */
export function stepLabel(step) {
  return step?.kind === "tool" ? String(step.tool ?? "tool") : "prompt";
}

/**
 * A tool result as the next step sees it: structured content if the server
 * sent it, else the text — parsed, if it is JSON.
 */
export function toolOutput(result) {
  if (result?.structuredContent !== undefined && result?.structuredContent !== null) return result.structuredContent;
  const text = resultText(result);
  try {
    return JSON.parse(text);
  } catch {
    return text;
  }
}

export class PipelineRunner {
  #provider;
  #store;
  #registry;
  #toolbox;
  #now;
  #onAppended;
  #maxTokens;

  /**
   * @param {{
   *   provider: import("../llm/provider.js").LlmProvider,
   *   store: import("../store/conversationStore.js").ConversationStore,
   *   registry: import("../mcp/servers.js").McpRegistry,
   *   toolbox: { toolsFor: Function, route: Function, call: Function },
   *   now?: () => number,
   *   onAppended?: (conversationId: string) => void,
   *   maxTokens?: number,
   * }} deps - `registry` is how a tool step reaches a server directly;
   *   `toolbox` is what a prompt step with tools goes through (behind the
   *   agent's allowlist). `now` is also the clock `{{now}}` reads.
   */
  constructor({ provider, store, registry, toolbox, now = Date.now, onAppended = () => {}, maxTokens = STEP_MAX_TOKENS }) {
    this.#provider = provider;
    this.#store = store;
    this.#registry = registry;
    this.#toolbox = toolbox;
    this.#now = now;
    this.#onAppended = onAppended;
    this.#maxTokens = maxTokens;
  }

  /**
   * @param {{ run: { id: number }, schedule: { id: number, conversationId: string, plan: object[] } }} claimed
   * @returns {Promise<{ ok: boolean, output?: string, error?: string, tokens?: number, steps?: object[], orphan?: boolean }>}
   *   `orphan` means the conversation is gone, so the schedule should go too.
   */
  async run({ run, schedule }) {
    const started = this.#now();
    const conversationId = schedule.conversationId;
    const record = await this.#store.load(conversationId);
    if (!record) return { ok: false, orphan: true, error: "The conversation this schedule belongs to no longer exists." };

const definition = agentFor(record.agentId);
    if (definition.kind !== "scheduled") {
      return { ok: false, error: `The conversation belongs to "${definition.id}", which is not a scheduled agent.` };
    }

    const steps = Array.isArray(schedule.plan) ? schedule.plan : [];
    const outputs = [];
    const done = [];
    const usage = { inputTokens: null, outputTokens: null };
    let model = null;
    let failure = steps.length ? null : { index: 0, label: "", message: "The pipeline has no accepted plan — generate one in the Pipeline panel and accept it." };

for (const [i, step] of steps.entries()) {
      const index = i + 1;
      const where = step.kind === "tool" ? { server: step.server, tool: step.tool } : {};
      if (failure) {
        done.push({ index, kind: step.kind, ...where, status: "skipped" });
        continue;
      }
      const t0 = this.#now();
      try {
        const out =
          step.kind === "tool"
            ? await this.#tool(step, outputs, schedule.id)
            : await this.#prompt(step, outputs, definition, schedule.id);
        const tokens = sum(out.usage?.inputTokens, out.usage?.outputTokens);
        if (out.usage) {
          usage.inputTokens = addCounts(usage.inputTokens, out.usage.inputTokens);
          usage.outputTokens = addCounts(usage.outputTokens, out.usage.outputTokens);
          model = out.model ?? model;
        }
        outputs.push(out.output);
        done.push({
          index,
          kind: step.kind,
          ...where,
          input: out.input,
          output: out.output,
          ...(out.toolCalls?.length ? { toolCalls: out.toolCalls } : {}),
          status: "ok",
          ms: this.#now() - t0,
          ...(tokens != null ? { tokens } : {}),
        });
      } catch (err) {
        const message = err instanceof StepFailure || err?.name === "TemplateError" ? err.message : describeError(err);
        failure = { index, label: stepLabel(step), message };
        done.push({
          index,
          kind: step.kind,
          ...where,
          ...(err?.input !== undefined ? { input: err.input } : {}),
          status: "error",
          error: message,
          ms: this.#now() - t0,
        });
      }
    }

const durationMs = this.#now() - started;
    const tokens = sum(usage.inputTokens, usage.outputTokens);
    const strip = done.map((step, i) => ({ index: step.index, kind: step.kind, label: stepLabel(steps[i]), status: step.status, ms: step.ms ?? null }));
    const content = failure
      ? `⚠️ Run #${run.id} failed${failure.index ? ` at step ${failure.index} (${failure.label})` : ""}: ${failure.message}`
      : messageText(outputs.at(-1));
    const cost = tokens != null ? estimateCost({ model, inputTokens: usage.inputTokens, outputTokens: usage.outputTokens }) : null;

    const message = {
      role: "assistant",
      content,
      steps: strip,
      ...(tokens != null
        ? {
            tokens: { input: usage.inputTokens, output: usage.outputTokens, total: tokens },
            cost: { input: cost.inputCost, output: cost.outputCost, total: cost.totalCost },
            model,
          }
        : {}),
      ms: durationMs,
      run: { runId: run.id, durationMs, tokens, ok: !failure, ...(failure ? { error: failure.message } : {}) },
    };

    const appended = await this.#append(conversationId, message, { billed: tokens != null ? usage : null, counted: !failure });
    if (!appended) return { ok: false, orphan: true, error: "The conversation was deleted while the run was in flight.", steps: done };

    return failure
      ? { ok: false, error: failure.index ? `Step ${failure.index} (${failure.label}): ${failure.message}` : failure.message, steps: done, ...(tokens != null ? { tokens } : {}) }
      : { ok: true, output: content, steps: done, ...(tokens != null ? { tokens } : {}) };
  }

/** A fixed MCP call: args resolved, the server called directly, no model. */
  async #tool(step, outputs, scheduleId) {
    const input = resolve(step.args ?? {}, { steps: outputs, now: this.#now });
    if (step.server === "scheduler" && OWN_SCHEDULE_TOOLS.has(step.tool) && input && typeof input === "object" && !Array.isArray(input)) {
      input.scheduleId = scheduleId;
    }
    const client = this.#registry.get(step.server);
    if (!client) throw new StepFailure(`There is no MCP server "${step.server}".`, input);
    const name = this.#registry.definition(step.server)?.name ?? step.server;
    const reconnect = `Reconnect ${name} in the panel.`;

    let result;
    try {
      if (client.auth === "oauth" && !(await client.connect()).ok) throw new StepFailure(reconnect, input);
      result = await client.callTool(step.tool, input);
    } catch (err) {
      if (err instanceof StepFailure) throw err;
      if (client.auth === "oauth" && isUnauthorized(err)) throw new StepFailure(reconnect, input);
      if (client.auth === "oauth" && /needs authorization/i.test(err?.message ?? "")) throw new StepFailure(reconnect, input);
      throw new StepFailure(`${step.server}.${step.tool} could not be called: ${describeError(err)}`, input);
    }
    if (result?.isError) throw new StepFailure(resultText(result) || `${step.server}.${step.tool} failed without saying why.`, input);
    return { input, output: toolOutput(result) };
  }

/**
   * One model call from a fresh context: persona + this step's text, tools
   * only if allowed. A json step's output is an object, checked against its
   * outputSchema; a text step's is the reply.
   */
  async #prompt(step, outputs, definition, scheduleId) {
    const text = interpolate(step.text, { steps: outputs, now: this.#now });
    const complete = (request) =>
      completeWithRetry(this.#provider, { ...request, temperature: 0.7, maxTokens: this.#maxTokens, model: definition.model });
    const messages = [{ role: "user", content: text }];
    const json = step.format === "json";
    const schema = step.outputSchema ?? { type: "object" };

    let result;
    let usage;
    let toolCalls = [];
    if (json && !step.allowTools) {
      result = await complete({
        system: `${definition.systemPrompt}

Return the result by calling ${RESPOND_TOOL}.`,
        messages,
        tools: [{ name: RESPOND_TOOL, description: "Return this step's result.", inputSchema: schema }],
        toolChoice: { name: RESPOND_TOOL },
      });
      usage = { inputTokens: result.usage?.inputTokens ?? null, outputTokens: result.usage?.outputTokens ?? null };
      this.#checkComplete(result, text);
      const use = (result.content ?? []).find((block) => block.type === "tool_use" && block.name === RESPOND_TOOL);
      if (!use) throw new StepFailure("The model returned no JSON.", text);
      return { input: text, output: checkedJson(use.input, schema, text), usage, model: result.model, toolCalls };
    }
    if (step.allowTools) {
      const offered = await scopedTools({ toolbox: this.#toolbox, servers: definition.mcpServers ?? [], allow: definition.tools, scheduleId });
      for (const { server, error } of offered.unavailable) {
        console.warn(`[pipeline] MCP server "${server}" is unavailable for schedule ${scheduleId}: ${error}`);
      }
      const loop = await runToolLoop({
        complete,
        system: `${definition.systemPrompt}\n\n${SCOPE_NOTE}`,
        messages,
        tools: offered.tools,
        call: offered.call,
        maxRounds: MAX_STEP_TOOL_ROUNDS,
      });
      ({ result, usage, toolCalls } = loop);
    } else {
      result = await complete({ system: definition.systemPrompt, messages });
      usage = { inputTokens: result.usage?.inputTokens ?? null, outputTokens: result.usage?.outputTokens ?? null };
    }

this.#checkComplete(result, text);
    const output = result.text?.trim() ?? "";
    if (!output) throw new StepFailure("The model returned no text.", text);
    if (json) {
      let parsed;
      try {
        parsed = JSON.parse(output.replace(/^```(?:json)?\s*|\s*```$/g, ""));
      } catch {
        throw new StepFailure("The model's reply was not JSON.", text);
      }
      return { input: text, output: checkedJson(parsed, schema, text), usage, model: result.model, toolCalls };
    }
    return { input: text, output, usage, model: result.model, toolCalls };
  }

  /** A reply cut off at the ceiling is not an answer: say so, rather than pass half of it on. */
  #checkComplete(result, input) {
    if (result.stopReason === "max_tokens") {
      throw new StepFailure(
        `The model's answer was cut off at the ${this.#maxTokens}-token output limit, so it is incomplete. Ask this step for less text.`,
        input
      );
    }
  }

  /**
   * Re-read, append, save. Re-read rather than reusing the record from the
   * start of the run: the chat may have been deleted in the meantime, and a
   * save would quietly bring it back.
   */
  async #append(conversationId, message, { billed, counted }) {
    const record = await this.#store.load(conversationId);
    if (!record) return false;

const usage = { ...emptyUsage(), ...record.usage };
    if (billed) {
      usage.totalInputTokens += billed.inputTokens ?? 0;
      usage.totalOutputTokens += billed.outputTokens ?? 0;
      usage.totalCostUsd += message.cost?.total ?? 0;
    }
    if (counted) usage.turnCount += 1;
    const messages = [...record.messages, { ...message, id: nextMessageId(record.messages) }];
    await this.#store.save(conversationId, messages, usage, {});
    this.#onAppended(conversationId);
    return true;
  }
}

/** A json step's output, or a step failure that says how it misses its schema. */
function checkedJson(value, schema, input) {
  let problems;
  try {
    problems = validationErrors(schema, value);
  } catch (err) {
    throw new StepFailure(`The step's outputSchema is not valid JSON Schema: ${err?.message ?? err}`, input);
  }
  if (problems.length) throw new StepFailure(`The model's JSON does not match the step's outputSchema: ${problems.join("; ")}.`, input);
  return value;
}

/** The last output as the message's text: a string as it is, anything else as a JSON block. */
function messageText(output) {
  if (output === "") return "(the last step returned nothing)";
  const text = typeof output === "string" ? output : "```json\n" + JSON.stringify(output ?? null, null, 2) + "\n```";
  return text.length > MAX_MESSAGE_CHARS ? text.slice(0, MAX_MESSAGE_CHARS - 1) + "…" : text;
}

function sum(a, b) {
  return typeof a === "number" && typeof b === "number" ? a + b : null;
}

const ajv = new Ajv({ strict: false, allErrors: true, validateFormats: false });
/** @type {WeakMap<object, import("ajv").ValidateFunction>} */
const compiled = new WeakMap();

/**
 * @param {object} schema
 * @returns {import("ajv").ValidateFunction}
 * @throws when the schema itself is not valid JSON Schema.
 */
export function compile(schema) {
  let validate = compiled.get(schema);
  if (!validate) {
    const { $schema: _draft, ...rest } = schema;
    validate = ajv.compile(rest);
    compiled.set(schema, validate);
  }
  return validate;
}

/** Whether `schema` compiles; the reason when it does not. */
export function schemaProblem(schema) {
  try {
    compile(schema);
    return null;
  } catch (err) {
    return err?.message ?? String(err);
  }
}

/**
 * Validate a value; every problem as `path: message`.
 *
 * @param {object} schema
 * @param {unknown} value
 * @param {{ ignore?: (instancePath: string) => boolean }} [options] - Drop the
 *   problems at paths this says to ignore (the planner's: a value that is still
 *   a template, and will only be known when the step runs).
 * @returns {string[]}
 */
export function validationErrors(schema, value, { ignore = () => false } = {}) {
  const validate = compile(schema);
  if (validate(value)) return [];
  const seen = new Set();
  const out = [];
  for (const error of validate.errors ?? []) {
    if (ignore(error.instancePath)) continue;
    const where = error.instancePath ? error.instancePath.slice(1).replaceAll("/", ".") : "(top level)";
    const detail =
      error.keyword === "additionalProperties"
        ? `unknown field "${error.params.additionalProperty}"`
        : error.keyword === "enum"
          ? `${error.message} (${error.params.allowedValues.map((v) => JSON.stringify(v)).join(", ")})`
          : error.message;
    const line = `${where}: ${detail}`;
    if (!seen.has(line)) {
      seen.add(line);
      out.push(line);
    }
  }
  return out;
}

/** The value at an ajv `instancePath` ("/pages/0/content"), or undefined. */
export function valueAt(root, instancePath) {
  if (!instancePath) return root;
  let value = root;
  for (const raw of instancePath.slice(1).split("/")) {
    const key = raw.replaceAll("~1", "/").replaceAll("~0", "~");
    if (value === null || typeof value !== "object") return undefined;
    value = value[key];
  }
  return value;
}

/**
 * Walk a dotted path down a schema.
 *
 * @param {object} schema
 * @param {string[]} path
 * @returns {{ ok: true } | { ok: false, at: number, key: string, reason: string }}
 *   `at` is how many keys matched before the one that did not.
 */
export function walkPath(schema, path, at = 0) {
  if (at >= path.length) return { ok: true };
  if (!schema || typeof schema !== "object") return { ok: true };

  // A union (or an intersection, read loosely): fine if any branch has the
  // path. A `null` branch never has one, and is not worth reporting.
  const union = schema.anyOf ?? schema.oneOf ?? schema.allOf;
  if (Array.isArray(union)) {
    const tries = union.filter((branch) => !isNullOnly(branch)).map((branch) => walkPath(branch, path, at));
    if (!tries.length) return { ok: false, at, key: path[at], reason: "it is always null" };
    return tries.find((each) => each.ok) ?? tries.reduce((deepest, each) => (each.at > deepest.at ? each : deepest));
  }

  const key = path[at];
  const types = typesOf(schema);
  const isObject = types.includes("object") || schema.properties || schema.additionalProperties;
  const isArray = types.includes("array") || schema.items || schema.prefixItems;

if (isObject && !(isArray && /^\d+$/.test(key))) {
    if (schema.properties && Object.hasOwn(schema.properties, key)) return walkPath(schema.properties[key], path, at + 1);
    if (schema.additionalProperties && typeof schema.additionalProperties === "object") {
      return walkPath(schema.additionalProperties, path, at + 1);
    }
    if (!schema.properties && schema.additionalProperties !== false) return { ok: true };
    const known = Object.keys(schema.properties ?? {});
    return { ok: false, at, key, reason: known.length ? `it has ${known.join(", ")}` : "it has no fields" };
  }
  if (isArray) {
    if (!/^\d+$/.test(key)) return { ok: false, at, key, reason: "it is a list: use an index, like .0" };
    const index = Number(key);
    if (Array.isArray(schema.prefixItems) && index < schema.prefixItems.length) return walkPath(schema.prefixItems[index], path, at + 1);
    return walkPath(schema.items ?? {}, path, at + 1);
  }
  if (!types.length) return { ok: true }; // `{}`: anything, so nothing more can be said.
  const kind = types.filter((type) => type !== "null").join(" or ") || "null";
  return { ok: false, at, key, reason: `it is a ${kind}, which has no fields` };
}

/**
 * A copy of an object schema without one property — how `scheduleId` is kept
 * out of what the planner and the model see.
 */
export function withoutField(schema, field) {
  if (!schema?.properties || !(field in schema.properties)) return schema;
  const { [field]: _dropped, ...properties } = schema.properties;
  const out = { ...schema, properties };
  if (Array.isArray(schema.required)) out.required = schema.required.filter((name) => name !== field);
  return out;
}

const REFERENCE = /^(prev|now|steps\.(\d+))((?:\.[^.\s]+)*)$/;

export class TemplateError extends Error {
  constructor(message) {
    super(message);
    this.name = "TemplateError";
  }
}

/**
 * @typedef {object} TemplateContext
 * @property {unknown[]} steps - Outputs of the steps that have run, in order: `steps[0]` is step 1.
 * @property {() => number} [now] - The clock `{{now}}` reads. Default `Date.now`.
 */

/**
 * The value a single reference (the text between the braces) stands for.
 *
 * @param {string} reference - e.g. `prev`, `steps.2.title`, `now`.
 * @param {TemplateContext} context
 */
export function lookup(reference, { steps = [], now = Date.now } = {}) {
  const match = REFERENCE.exec(reference.trim());
  if (!match) throw new TemplateError(`{{${reference}}} is not a template: use {{prev}}, {{steps.N}} or {{now}}.`);
  const [, head, number, rest] = match;

  if (head === "now") {
    if (rest) throw new TemplateError(`{{${reference}}}: {{now}} has no fields.`);
    return new Date(now()).toISOString();
  }

  let value;
  if (head === "prev") {
    if (!steps.length) throw new TemplateError(`{{${reference}}} refers to a previous step, and there is none.`);
    value = steps[steps.length - 1];
  } else {
    const n = Number(number);
    if (n < 1 || n > steps.length) {
      throw new TemplateError(`{{${reference}}} refers to step ${n}, which has not run (${steps.length ? `steps 1–${steps.length} have` : "no step has"}).`);
    }
    value = steps[n - 1];
  }

  const path = rest ? rest.slice(1).split(".") : [];
  for (const [i, key] of path.entries()) {
    const container = value;
    if (container === null || typeof container !== "object" || !Object.hasOwn(container, key)) {
      const at = [head === "prev" ? "prev" : `steps.${number}`, ...path.slice(0, i)].join(".");
      throw new TemplateError(`{{${reference}}}: ${at} has no "${key}".`);
    }
    value = container[key];
  }
  return value;
}

/** A value as it reads inside a sentence: strings as they are, everything else as JSON. */
export function asText(value) {
  if (typeof value === "string") return value;
  if (value === undefined) return "";
  return JSON.stringify(value);
}

/**
 * Text with every template replaced by its value as text.
 *
 * @param {string} text
 * @param {TemplateContext} context
 * @returns {string}
 */
export function interpolate(text, context) {
  return String(text).replace(TEMPLATE, (_whole, reference) => asText(lookup(reference, context)));
}

/**
 * Tool args (or any JSON value) with templates resolved: a string that is one
 * whole template becomes the raw value, anything else is interpolated.
 *
 * @template T
 * @param {T} template
 * @param {TemplateContext} context
 * @returns {unknown}
 */
export function resolve(template, context) {
  if (typeof template === "string") {
    const whole = WHOLE.exec(template);
    return whole ? lookup(whole[1], context) : interpolate(template, context);
  }
  if (Array.isArray(template)) return template.map((item) => resolve(item, context));
  if (template && typeof template === "object") {
    return Object.fromEntries(Object.entries(template).map(([key, value]) => [key, resolve(value, context)]));
  }
  return template;
}

/**
 * Every template in a string, parsed but not resolved — what a plan is checked
 * with before anything runs. A reference that is not one of the three names is
 * `{ whole, bad: true }`.
 *
 * @param {string} text
 * @returns {Generator<{ whole: string, bad: true } | { whole: string, bad?: false, name: "prev" | "now" | "steps", step: number | null, path: string[] }>}
 */
export function* templatesIn(text) {
  for (const [whole, inner] of String(text).matchAll(TEMPLATE)) {
    const match = REFERENCE.exec(inner.trim());
    if (!match) {
      yield { whole, bad: true };
      continue;
    }
    const [, head, number, rest] = match;
    yield {
      whole,
      name: number === undefined ? head : "steps",
      step: number === undefined ? null : Number(number),
      path: rest ? rest.slice(1).split(".") : [],
    };
  }
}

/** Whether a string holds a template anywhere. */
export function hasTemplate(text) {
  return typeof text === "string" && new RegExp(TEMPLATE.source).test(text);
}

export const MAX_PLAN_STEPS = 20;
export const MAX_PROMPT_CHARS = 8000;
export const MAX_ARGS_CHARS = 20000;

export const FORMATS = ["text", "json"];
const NAME = /^[A-Za-z0-9_.-]{1,64}$/;

/** What a step is called in a sentence: `omdb.get_movie`, `prompt (json)`. */
export function stepName(step) {
  if (step?.kind === "tool") return `${step.server}.${step.tool}`;
  return step?.format === "json" ? "prompt (json)" : "prompt";
}

/**
 * @param {unknown} steps
 * @param {Catalog} catalog
 * @returns {string[]} Every problem, one sentence each, "Step N (name): …".
 */
export function validatePlan(steps, catalog) {
  if (!Array.isArray(steps) || !steps.length) return ["The plan has no steps."];
  if (steps.length > MAX_PLAN_STEPS) return [`The plan has ${steps.length} steps; at most ${MAX_PLAN_STEPS}.`];

  const tools = new Map(catalog.tools.map((tool) => [tool.name, tool]));
  const down = new Map(catalog.down.map(({ server, error }) => [server, error]));
  const problems = [];
  /** What each step's output looks like, as far as can be known now. @type {Array<{ schema?: object, unknown?: string, invalid?: true }>} */
  const shapes = [];

  steps.forEach((step, i) => {
    const n = i + 1;
    const say = (text) => problems.push(`Step ${n} (${stepName(step)}): ${text}`);
    if (!step || typeof step !== "object" || Array.isArray(step)) {
      problems.push(`Step ${n}: must be an object.`);
      shapes.push({ invalid: true });
      return;
    }
    if (step.why !== undefined && typeof step.why !== "string") say("why must be a sentence.");

    if (step.kind === "tool") {
      shapes.push(checkTool(step, { tools, down, say }));
      for (const problem of templateProblems(step.args, n, shapes)) say(problem);
    } else if (step.kind === "prompt") {
      shapes.push(checkPrompt(step, say));
      for (const problem of templateProblems(step.text, n, shapes)) say(problem);
    } else {
      problems.push(`Step ${n}: kind must be "tool" or "prompt".`);
      shapes.push({ invalid: true });
    }
  });
  return problems;
}

function checkTool(step, { tools, down, say }) {
  extraKeys(step, ["kind", "server", "tool", "args", "why"], say);
  if (typeof step.server !== "string" || !NAME.test(step.server) || typeof step.tool !== "string" || !NAME.test(step.tool)) {
    say("needs a tool from the catalog, as server.tool.");
    return { invalid: true };
  }
  const args = step.args ?? {};
  if (!args || typeof args !== "object" || Array.isArray(args)) {
    say("args must be a JSON object.");
    return { invalid: true };
  }
  if (JSON.stringify(args).length > MAX_ARGS_CHARS) say(`args must be at most ${MAX_ARGS_CHARS} characters of JSON.`);

  const name = `${step.server}.${step.tool}`;
  const tool = tools.get(name);
  if (!tool) {
    say(
      down.has(step.server)
        ? `the ${step.server} server is down (${down.get(step.server)}), so none of its tools can be used.`
        : `${name} is not in the catalog. Use only the tools listed there, exactly as named.`
    );
    return { invalid: true };
  }

// A value that is still a template is only known at run time: its type and
  // format are not checked here. Its path is, below.
  const ignore = (instancePath) => {
    const value = valueAt(args, instancePath);
    return typeof value === "string" && hasTemplate(value);
  };
  try {
    for (const problem of validationErrors(tool.inputSchema ?? { type: "object" }, args, { ignore })) say(`args.${problem}`.replace("args.(top level)", "args"));
  } catch (err) {
    // A server's schema ajv cannot compile is the server's problem, not the plan's.
    console.warn(`[planner] could not compile ${name}'s inputSchema: ${err?.message ?? err}`);
  }
  return tool.outputSchema ? { schema: tool.outputSchema } : { unknown: `${name} declares no outputSchema` };
}

function checkPrompt(step, say) {
  extraKeys(step, ["kind", "text", "format", "outputSchema", "allowTools", "why"], say);
  if (typeof step.text !== "string" || !step.text.trim()) say("needs a prompt text.");
  else if (step.text.length > MAX_PROMPT_CHARS) say(`text must be at most ${MAX_PROMPT_CHARS} characters.`);
  if (step.allowTools !== undefined && typeof step.allowTools !== "boolean") say("allowTools must be true or false.");
  const format = step.format ?? "text";
  if (!FORMATS.includes(format)) {
    say(`format must be "text" or "json".`);
    return { invalid: true };
  }
  if (format === "text") {
    if (step.outputSchema !== undefined) say(`outputSchema needs format "json".`);
    return { schema: { type: "string" }, text: true };
  }

  const schema = step.outputSchema;
  if (!schema || typeof schema !== "object" || Array.isArray(schema)) {
    say('a json step needs an outputSchema: a JSON Schema { type: "object", properties, required } of what it returns.');
    return { invalid: true };
  }
  if (schema.type !== "object") say('its outputSchema must have type "object".');
  const problem = schemaProblem(schema);
  if (problem) {
    say(`its outputSchema is not valid JSON Schema: ${problem}.`);
    return { invalid: true };
  }
  return { schema };
}

/**
 * Every template inside a step (args or text) that cannot resolve when step
 * `n` runs, or that reaches for a field the target step's shape does not have.
 */
function templateProblems(value, n, shapes) {
  const problems = [];
  for (const text of strings(value)) {
    for (const ref of templatesIn(text)) {
      if (ref.bad) {
        problems.push(`${ref.whole} is not a template: use {{prev}}, {{steps.N}} or {{now}}.`);
        continue;
      }
      if (ref.name === "now") {
        if (ref.path.length) problems.push(`${ref.whole}: {{now}} has no fields.`);
        continue;
      }
      const target = ref.name === "prev" ? n - 1 : ref.step;
      if (ref.name === "prev" && n === 1) {
        problems.push(`${ref.whole} has no previous step to refer to.`);
        continue;
      }
      if (target < 1 || target >= n) {
        problems.push(`${ref.whole} must refer to an earlier step (${n > 1 ? `1 to ${n - 1}` : "there is none"}).`);
        continue;
      }
      if (!ref.path.length) continue;

const shape = shapes[target - 1];
      const head = ref.name === "prev" ? "prev" : `steps.${target}`;
      if (shape.invalid) continue; // Already reported at that step.
      if (shape.unknown) {
        problems.push(
          `${ref.whole}: step ${target}'s output shape is unknown (${shape.unknown}), so its fields cannot be referenced. ` +
            `Use {{steps.${target}}} whole, or add a json prompt step that reshapes it.`
        );
        continue;
      }
      if (shape.text) {
        problems.push(`${ref.whole}: step ${target} is a text prompt, its output is a plain string with no fields. Give it format "json" and an outputSchema.`);
        continue;
      }
      const walked = walkPath(shape.schema, ref.path);
      if (!walked.ok) {
        const at = [head, ...ref.path.slice(0, walked.at)].join(".");
        problems.push(`${ref.whole}: ${at} has no "${walked.key}" (${walked.reason}).`);
      }
    }
  }
  return problems;
}

function extraKeys(step, allowed, say) {
  const extra = Object.keys(step).filter((key) => !allowed.includes(key));
  if (extra.length) say(`unknown field${extra.length > 1 ? "s" : ""} ${extra.map((key) => `"${key}"`).join(", ")}.`);
}

/** Every string value inside a value. Keys are never resolved, so they are not checked. */
function* strings(value) {
  if (typeof value === "string") yield value;
  else if (Array.isArray(value)) for (const item of value) yield* strings(item);
  else if (value && typeof value === "object") for (const item of Object.values(value)) yield* strings(item);
}

export const MIN_INTERVAL_SECONDS = 15;
export const MAX_INTERVAL_SECONDS = 7 * 24 * 3600;
export const DEFAULT_INTERVAL_SECONDS = 60;

export const MAX_GOAL_CHARS = 4000;
const MODES = ["once", "interval"];
const MAX_RUNS = 50;

export const READ_ONLY_REASON =
  "This chat belongs to a pipeline agent: it is a read-only feed of its runs. " +
  "Write its goal, generate and accept a plan, and press Run in the Pipeline panel instead.";

/**
 * @param {{
 *   store: import("./store/conversationStore.js").ConversationStore,
 *   scheduler: import("./scheduler/client.js").SchedulerClient,
 *   planner: Pick<import("./pipeline/planner.js").Planner, "propose">,
 *   kick?: () => unknown,
 *   invalidate?: (conversationId: string) => void,
 *   now?: () => number,
 * }} deps - `kick` asks the ticker for a tick right away, so Run does not
 *   wait up to 15 s for the next one.
 */
export function pipelineRoutes({ store, scheduler, planner, kick = () => {}, invalidate = () => {}, now = Date.now }) {
  const router = express.Router();
  /** Chats with a planner call in flight: a double click is one plan, not two. */
  const planning = new Set();

  /** The record, if `id` is a scheduled chat; otherwise null. */
  async function scheduledRecord(id) {
    if (!isValidSessionId(id)) return null;
    const record = await store.load(id);
    return record && isScheduledAgent(record.agentId) ? record : null;
  }

  /**
   * The chat's schedule, created if it has none. A chat made while the
   * scheduler was down, or one whose schedule was lost with the database,
   * heals the first time its panel is opened.
   */
  async function ensureSchedule(conversationId) {
    return (
      (await scheduler.getSchedule(conversationId)) ??
      (await scheduler.createSchedule({ conversationId, mode: "once", goal: "", plan: [], intervalSeconds: DEFAULT_INTERVAL_SECONDS, enabled: false }))
    );
  }

/** `/conversations/:id/pipeline…` on something that is not a pipeline chat. */
  async function requireScheduled(req, res) {
    const { id } = req.params;
    if (!isValidSessionId(id)) {
      res.status(400).json({ error: "Not a valid conversation id." });
      return null;
    }
    const record = await scheduledRecord(id);
    if (!record) res.status(404).json({ error: "No pipeline chat with that id." });
    return record;
  }

  const route = (handler) => async (req, res, next) => {
    try {
      await handler(req, res, next);
    } catch (err) {
      fail(res, err, `${req.method} ${req.path}`);
    }
  };

  // ---- the chat itself -----------------------------------------------------

  router.post(
    "/conversations",
    route(async (req, res) => {
      const wanted = req.body?.agent;
      if (wanted !== undefined && !isValidAgent(wanted)) {
        return res.status(400).json({ error: "'agent' must be one this server knows." });
      }
      const agentId = agentOf(wanted ?? DEFAULT_AGENT);
      const id = crypto.randomUUID();
      const saved = await store.save(id, [], undefined, { agentId });

      let schedule = null;
      if (isScheduledAgent(agentId)) {
        try {
          schedule = await ensureSchedule(id);
        } catch (err) {
          // The chat exists either way; its schedule is created the first time
          // the panel can reach the scheduler.
          console.warn(`[POST /conversations] no schedule yet for ${id}: ${err?.message ?? err}`);
        }
      }
      res.status(201).json({ id, title: saved.title, agentId, updatedAt: saved.updatedAt, schedule });
    })
  );

router.delete(
    "/conversations/:id",
    route(async (req, res, next) => {
      const record = await scheduledRecord(req.params.id);
      if (!record) return next();

      // The schedule first: a chat deleted with its schedule left behind would
      // keep a task running against nothing. If the scheduler is down, the chat
      // still goes, and the ticker deletes the orphan on its next run.
      let scheduleDeleted = false;
      try {
        const schedule = await scheduler.getSchedule(record.id);
        if (schedule) await scheduler.deleteSchedule(schedule.id);
        scheduleDeleted = true;
      } catch (err) {
        console.warn(`[DELETE /conversations/:id] schedule not deleted: ${err?.message ?? err}`);
      }
      await store.clear(record.id);
      invalidate(record.id);
      res.json({ ok: true, scheduleDeleted });
    })
  );

  router.post(
    "/chat",
    route(async (req, res, next) => {
      const { sessionId, agent } = req.body ?? {};
      const record = isValidSessionId(sessionId) ? await store.load(sessionId) : null;
      const agentId = record ? record.agentId : agent;
      if (isScheduledAgent(agentId)) return res.status(400).json({ error: READ_ONLY_REASON });
      next();
    })
  );

  router.post(
    "/conversations/:id/fork",
    route(async (req, res, next) => {
      if (await scheduledRecord(req.params.id)) {
        return res.status(400).json({ error: "A pipeline chat cannot be forked: it is a feed of runs, not a conversation." });
      }
      next();
    })
  );

  // ---- the pipeline --------------------------------------------------------

router.get(
    "/conversations/:id/pipeline",
    route(async (req, res) => {
      const record = await requireScheduled(req, res);
      if (!record) return;
      const schedule = await ensureSchedule(record.id);
      res.json({ pipeline: pipelineOf(schedule), now: new Date(now()).toISOString() });
    })
  );

  router.put(
    "/conversations/:id/pipeline",
    route(async (req, res) => {
      const record = await requireScheduled(req, res);
      if (!record) return;
      const changes = pipelineChanges(req.body);
      if (changes.error) return res.status(400).json({ error: changes.error });

      const current = await ensureSchedule(record.id);
      const next = { ...pipelineOf(current), ...changes.value };
      if (next.mode === "interval" && next.enabled && !next.plan.length) {
        return res.status(400).json({ error: "Accept a plan before enabling the pipeline: a run with nothing to do has nothing to post." });
      }

      const schedule = await update(current.id, changes.value, res);
      if (!schedule) return;
      if (changes.value.goal !== undefined) await retitle(record.id, schedule);
      res.json(answer(schedule));
    })
  );

/**
   * Run the planner on the goal and store what it proposes. The body may carry
   * the goal, which is saved first — the Generate button sends what is in the
   * box. A plan that does not validate, even after the planner's one retry, is
   * a 422 with every error, and nothing is stored.
   */
  router.post(
    "/conversations/:id/pipeline/plan",
    route(async (req, res) => {
      const record = await requireScheduled(req, res);
      if (!record) return;
      const body = req.body ?? {};
      if (body.goal !== undefined) {
        const problem = goalProblem(body.goal);
        if (problem) return res.status(400).json({ error: problem });
      }
      if (planning.has(record.id)) return res.status(409).json({ error: "A plan is already being generated for this pipeline." });

      planning.add(record.id);
      try {
        let current = await ensureSchedule(record.id);
        if (body.goal !== undefined && body.goal !== current.goal) {
          current = await update(current.id, { goal: body.goal }, res);
          if (!current) return;
          await retitle(record.id, current);
        }
        const goal = current.goal ?? "";
        if (!goal.trim()) return res.status(400).json({ error: "Write a goal first: the planner plans from it." });

const result = await planner.propose({ goal });
        if (!result.ok) {
          return res.status(422).json({
            error: "The planner's plan did not validate, even after one retry. Nothing was stored.",
            errors: result.errors,
            ...(result.notes ? { notes: result.notes } : {}),
            steps: result.steps,
          });
        }
        const proposal = {
          steps: result.steps,
          ...(result.notes ? { notes: result.notes } : {}),
          createdAt: result.createdAt,
          reason: "generated",
        };
        const schedule = await update(current.id, { proposal }, res);
        if (!schedule) return;
        res.json({ ...answer(schedule), attempts: result.attempts, usage: result.usage });
      } finally {
        planning.delete(record.id);
      }
    })
  );

  /** Accept (the proposal becomes the plan) or discard (it goes). Neither runs anything. */
  router.post(
    "/conversations/:id/pipeline/proposal",
    route(async (req, res) => {
      const record = await requireScheduled(req, res);
      if (!record) return;
      const action = req.body?.action;
      if (action !== "accept" && action !== "discard") {
        return res.status(400).json({ error: "'action' must be \"accept\" or \"discard\"." });
      }
      const current = await ensureSchedule(record.id);
      const proposal = current.proposal;
      if (!proposal) return res.status(409).json({ error: "There is no proposal to " + action + "." });

if (action === "discard") {
        const schedule = await update(current.id, { proposal: null }, res);
        if (schedule) res.json(answer(schedule));
        return;
      }
      if (proposal.errors?.length) {
        return res.status(409).json({ error: "This proposal did not validate, so it cannot be accepted. Discard it, or generate a new plan." });
      }
      if (!proposal.steps?.length) return res.status(409).json({ error: "This proposal has no steps." });
      const schedule = await update(current.id, { plan: proposal.steps, proposal: null }, res);
      if (!schedule) return;
      await retitle(record.id, schedule);
      res.json(answer(schedule));
    })
  );

  router.post(
    "/conversations/:id/pipeline/run",
    route(async (req, res) => {
      const record = await requireScheduled(req, res);
      if (!record) return;
      const current = await ensureSchedule(record.id);
      if (!current.plan?.length) return res.status(409).json({ error: "Generate a plan and accept it first." });
      const schedule = await scheduler.runNow(current.id);
      // Fire and forget: the run posts its own message, and a tick that is
      // already busy leaves the run pending for the next one.
      Promise.resolve()
        .then(kick)
        .catch((err) => console.warn(`[pipeline/run] tick failed: ${err?.message ?? err}`));
      res.json({ pipeline: pipelineOf(schedule), now: new Date(now()).toISOString() });
    })
  );

router.get(
    "/conversations/:id/runs",
    route(async (req, res) => {
      const record = await requireScheduled(req, res);
      if (!record) return;
      const limit = req.query.limit === undefined ? 10 : Number(req.query.limit);
      if (!Number.isInteger(limit) || limit < 1 || limit > MAX_RUNS) {
        return res.status(400).json({ error: `'limit' must be an integer between 1 and ${MAX_RUNS}.` });
      }
      const schedule = await ensureSchedule(record.id);
      res.json({ runs: await scheduler.listRuns(schedule.id, limit) });
    })
  );

  /** One run's steps, each with its exact resolved input and output. */
  router.get(
    "/conversations/:id/runs/:runId",
    route(async (req, res) => {
      const record = await requireScheduled(req, res);
      if (!record) return;
      const runId = Number(req.params.runId);
      if (!Number.isInteger(runId) || runId < 1) return res.status(400).json({ error: "Not a valid run id." });
      const schedule = await ensureSchedule(record.id);
      let found;
      try {
        found = await scheduler.getRun(runId);
      } catch (err) {
        if (err instanceof SchedulerToolError) return res.status(404).json({ error: `No run ${runId}.` });
        throw err;
      }
      // Another chat's run is not this chat's business.
      if (found.run.scheduleId !== schedule.id) return res.status(404).json({ error: `No run ${runId} in this chat.` });
      res.json(found);
    })
  );

/** A scheduler update; its refusal is a 400 with the scheduler's sentence (and null). */
  async function update(scheduleId, changes, res) {
    try {
      return await scheduler.updateSchedule(scheduleId, changes);
    } catch (err) {
      if (err instanceof SchedulerToolError) {
        res.status(400).json({ error: err.message });
        return null;
      }
      throw err;
    }
  }

  /**
   * A pipeline chat has no user message to be titled by, so it is named after
   * its goal (or, with none, its plan). Re-read first: a run may have
   * appended since.
   */
  async function retitle(conversationId, schedule) {
    const title = pipelineTitle(schedule);
    const latest = title ? await store.load(conversationId) : null;
    if (!latest) return;
    await store.save(latest.id, latest.messages, undefined, { title });
    invalidate(latest.id);
  }

  function answer(schedule) {
    return { pipeline: pipelineOf(schedule), now: new Date(now()).toISOString() };
  }

  return router;
}

/** A schedule as the panel sees it: the pipeline, without the scheduler's bookkeeping. */
export function pipelineOf(schedule) {
  return {
    scheduleId: schedule.id,
    goal: schedule.goal ?? "",
    plan: schedule.plan ?? [],
    proposal: schedule.proposal ?? null,
    mode: schedule.mode ?? "interval",
    intervalSeconds: schedule.intervalSeconds,
    enabled: Boolean(schedule.enabled),
    nextRunAt: schedule.nextRunAt ?? null,
    runPending: Boolean(schedule.runPending),
  };
}

/**
 * The goal's first line (the store cuts it to fit), or with no goal the
 * plan's tools ("get_movie → prompt → record").
 */
export function pipelineTitle({ goal = "", plan = [] } = {}) {
  const line = goal.trim().split("\n")[0].replace(/\s+/g, " ");
  return line || plan.map((step) => (step.kind === "tool" ? step.tool : "prompt")).join(" → ");
}

function goalProblem(goal) {
  if (typeof goal !== "string") return "'goal' must be text.";
  if (goal.length > MAX_GOAL_CHARS) return `'goal' must be at most ${MAX_GOAL_CHARS} characters.`;
  return null;
}

/**
 * The body of a PUT, checked for shape. Absent means unchanged; present and
 * wrong is a 400 that names the field, never a silent clamp. Steps are not
 * accepted: a plan comes from the planner, through a proposal.
 *
 * @returns {{ value: { goal?: string, mode?: string, enabled?: boolean, intervalSeconds?: number } } | { error: string }}
 */
export function pipelineChanges(body) {
  if (!body || typeof body !== "object" || Array.isArray(body)) return { error: "Send a JSON object." };
  if (body.steps !== undefined || body.plan !== undefined) {
    return { error: "Steps are not edited by hand: write a goal, press Generate plan, and accept the proposal." };
  }
  const value = {};
  if (body.goal !== undefined) {
    const problem = goalProblem(body.goal);
    if (problem) return { error: problem };
    value.goal = body.goal;
  }
  if (body.mode !== undefined) {
    if (!MODES.includes(body.mode)) return { error: "'mode' must be \"once\" or \"interval\"." };
    value.mode = body.mode;
  }
  if (body.enabled !== undefined) {
    if (typeof body.enabled !== "boolean") return { error: "'enabled' must be true or false." };
    value.enabled = body.enabled;
  }
  if (body.intervalSeconds !== undefined) {
    const n = body.intervalSeconds;
    if (!Number.isInteger(n) || n < MIN_INTERVAL_SECONDS || n > MAX_INTERVAL_SECONDS) {
      return { error: `'intervalSeconds' must be a whole number from ${MIN_INTERVAL_SECONDS} to ${MAX_INTERVAL_SECONDS}.` };
    }
    value.intervalSeconds = n;
  }
  if (!Object.keys(value).length) return { error: "Nothing to change: send goal, mode, enabled and/or intervalSeconds." };
  return { value };
}

function fail(res, err, where) {
  if (err instanceof SchedulerUnavailableError) {
    return res.status(503).json({ error: `${err.message}. Start scheduler_mcp_server (npm start, port 3002).` });
  }
  if (err instanceof SchedulerToolError) {
    return res.status(502).json({ error: `The scheduler refused: ${err.message}` });
  }
  console.error(`[${where}]`, err);
  res.status(500).json({ error: "Something went wrong with the pipeline." });
}

export class SchedulerUnavailableError extends Error {
  constructor(message, cause) {
    super(message, { cause });
    this.name = "SchedulerUnavailableError";
  }
}

export class SchedulerToolError extends Error {
  constructor(message) {
    super(message);
    this.name = "SchedulerToolError";
  }
}

/**
 * How much of one step's input or output goes to `finish_run`, as JSON. The
 * run's message keeps the whole last output; the stored step is for looking
 * at, and a runaway tool should not make the run impossible to close.
 */
export const MAX_STEP_JSON_CHARS = 100_000;

/** A value, or a note saying how big it was and its start, if its JSON is too long. */
export function capJson(value, limit = MAX_STEP_JSON_CHARS) {
  if (value === undefined) return undefined;
  const json = JSON.stringify(value);
  if (json === undefined || json.length <= limit) return value;
  return { truncated: true, chars: json.length, preview: json.slice(0, limit) };
}

export class SchedulerClient {
  #mcp;

  /** @param {{ mcp: import("../mcp/mcpClient.js").McpClient }} deps */
  constructor({ mcp }) {
    if (!mcp) throw new Error("SchedulerClient needs the scheduler's McpClient");
    this.#mcp = mcp;
  }

  get url() {
    return this.#mcp.url;
  }

  async #call(name, args = {}) {
    let result;
    try {
      result = await this.#mcp.callTool(name, args);
    } catch (err) {
      throw new SchedulerUnavailableError(`Could not reach the scheduler at ${this.#mcp.url}: ${describeError(err)}`, err);
    }
    if (result?.isError) throw new SchedulerToolError(resultText(result) || `${name} failed`);
    if (result?.structuredContent) return result.structuredContent;
    try {
      return JSON.parse(resultText(result));
    } catch {
      throw new SchedulerToolError(`${name} answered something that was not JSON`);
    }
  }

  createSchedule({ conversationId, mode = "interval", steps = [], intervalSeconds = 60, enabled = false }) {
    return this.#call("create_schedule", { conversationId, mode, steps, intervalSeconds, enabled });
  }

  /** @returns {Promise<object | null>} */
  async getSchedule(conversationId) {
    return (await this.#call("get_schedule", { conversationId })).schedule ?? null;
  }

  updateSchedule(scheduleId, changes) {
    return this.#call("update_schedule", { scheduleId, ...changes });
  }

  deleteSchedule(scheduleId) {
    return this.#call("delete_schedule", { scheduleId });
  }

async listSchedules() {
    return (await this.#call("list_schedules")).schedules ?? [];
  }

  claimDueRuns({ now, graceMs } = {}) {
    return this.#call("claim_due_runs", { ...(now === undefined ? {} : { now }), ...(graceMs === undefined ? {} : { graceMs }) });
  }

  finishRun({ runId, ok, output, error, tokens, steps }) {
    const args = { runId, ok };
    if (typeof output === "string") args.output = output.slice(0, 20000);
    if (typeof error === "string") args.error = error.slice(0, 4000);
    if (Number.isInteger(tokens) && tokens >= 0) args.tokens = tokens;
    if (Array.isArray(steps) && steps.length) args.steps = steps.map(stepForStorage);
    return this.#call("finish_run", args);
  }

  /** @returns {Promise<{ run: object, steps: object[] }>} */
  getRun(runId) {
    return this.#call("get_run", { runId });
  }

  async listRuns(scheduleId, limit = 10) {
    return (await this.#call("list_runs", { scheduleId, limit })).runs ?? [];
  }

  runNow(scheduleId) {
    return this.#call("run_now", { scheduleId });
  }

  releaseRuns() {
    return this.#call("release_runs");
  }

  aggregate(scheduleId) {
    return this.#call("aggregate", { scheduleId });
  }
}

/** One step as `finish_run` takes it: only the fields it has, the big ones capped. */
function stepForStorage(step) {
  const out = { index: step.index, kind: step.kind, status: step.status };
  if (step.server) out.server = step.server;
  if (step.tool) out.tool = step.tool;
  if (step.input !== undefined) out.input = capJson(step.input);
  if (step.output !== undefined) out.output = capJson(step.output);
  if (step.toolCalls?.length) out.toolCalls = step.toolCalls.slice(0, 50);
  if (typeof step.error === "string") out.error = step.error.slice(0, 4000);
  if (Number.isInteger(step.ms) && step.ms >= 0) out.ms = step.ms;
  if (Number.isInteger(step.tokens) && step.tokens >= 0) out.tokens = step.tokens;
  return out;
}

import { SchedulerToolError, SchedulerUnavailableError } from "./client.js";

/**
 * **A scheduler server in a Map, for the tests.** Same methods and answers as
 * `SchedulerClient`, the same claim rules (an accepted plan, enabled, due, not
 * already running; next run = now + interval), and a `down` switch that makes every call fail
 * the way an unreachable server does. Every call is logged in `calls`.
 */
export class FakeScheduler {
  down = false;
  calls = [];
  schedules = new Map();
  runs = [];
  records = [];
  #ids = { schedule: 0, run: 0 };

  constructor({ now = Date.now } = {}) {
    this.now = now;
  }

  #enter(name, args) {
    this.calls.push({ name, args });
    if (this.down) throw new SchedulerUnavailableError("Could not reach the scheduler at http://127.0.0.1:3002/mcp: fetch failed (ECONNREFUSED)");
  }

  #schedule(id) {
    const schedule = this.schedules.get(id);
    if (!schedule) throw new SchedulerToolError(`No schedule with id ${id}.`);
    return schedule;
  }

  #out(schedule) {
    return structuredClone({ ...schedule, nextRunAt: schedule.nextRunAt == null ? null : new Date(schedule.nextRunAt).toISOString() });
  }

async createSchedule({ conversationId, mode = "interval", goal = "", plan = [], proposal = null, intervalSeconds = 60, enabled = false }) {
    this.#enter("createSchedule", { conversationId, mode, goal, plan, intervalSeconds, enabled });
    if ([...this.schedules.values()].some((s) => s.conversationId === conversationId)) {
      throw new SchedulerToolError(`Conversation ${conversationId} already has a schedule.`);
    }
    this.#check(plan);
    const schedule = {
      id: ++this.#ids.schedule,
      conversationId,
      mode,
      goal,
      plan: structuredClone(plan),
      proposal: structuredClone(proposal),
      intervalSeconds,
      enabled,
      nextRunAt: mode === "interval" ? this.now() : null,
      runPending: false,
    };
    this.schedules.set(schedule.id, schedule);
    return this.#out(schedule);
  }

  /** The server's step rule, cut down to what the route tests need: kinds, and templates that look back. */
  #check(steps) {
    steps.forEach((step, i) => {
      if (!["tool", "prompt"].includes(step?.kind)) throw new SchedulerToolError(`Step ${i + 1}: kind must be "tool" or "prompt".`);
      const text = JSON.stringify(step);
      for (const [, n] of text.matchAll(/\{\{\s*steps\.(\d+)/g)) {
        if (Number(n) > i) throw new SchedulerToolError(`Step ${i + 1}: {{steps.${n}}} must refer to an earlier step.`);
      }
      if (i === 0 && /\{\{\s*prev/.test(text)) throw new SchedulerToolError("Step 1: {{prev}} has no previous step to refer to.");
    });
  }

async getSchedule(conversationId) {
    this.#enter("getSchedule", { conversationId });
    const found = [...this.schedules.values()].find((s) => s.conversationId === conversationId);
    return found ? this.#out(found) : null;
  }

async updateSchedule(scheduleId, changes) {
    this.#enter("updateSchedule", { scheduleId, ...changes });
    const schedule = this.#schedule(scheduleId);
    if (changes.plan) this.#check(changes.plan);
    const wasTicking = schedule.mode === "interval" && schedule.enabled;
    Object.assign(schedule, structuredClone(changes));
    if (schedule.mode === "once") schedule.nextRunAt = null;
    else if ((schedule.enabled && !wasTicking) || schedule.nextRunAt == null) schedule.nextRunAt = this.now();
    return this.#out(schedule);
  }

  async deleteSchedule(scheduleId) {
    this.#enter("deleteSchedule", { scheduleId });
    const deleted = this.schedules.delete(scheduleId);
    this.runs = this.runs.filter((run) => run.scheduleId !== scheduleId);
    this.records = this.records.filter((record) => record.scheduleId !== scheduleId);
    return { deleted, scheduleId };
  }

async claimDueRuns({ now = this.now(), graceMs = 0 } = {}) {
    this.#enter("claimDueRuns", { now, graceMs });
    const claimed = [];
    for (const schedule of this.schedules.values()) {
      const busy = this.runs.some((run) => run.scheduleId === schedule.id && run.status === "running");
      const ticking = schedule.mode === "interval" && schedule.enabled && schedule.nextRunAt <= now + graceMs;
      if (busy || !schedule.plan.length || !(ticking || schedule.runPending)) continue;
      const run = { id: ++this.#ids.run, scheduleId: schedule.id, status: "running", claimedAt: now };
      this.runs.push(run);
      schedule.runPending = false;
      if (schedule.mode === "once") schedule.nextRunAt = null;
      else if (schedule.enabled) schedule.nextRunAt = now + schedule.intervalSeconds * 1000;
      claimed.push({ run: { ...run }, schedule: this.#out(schedule) });
    }
    return { claimed, released: 0 };
  }

  async finishRun({ runId, ok, output, error, tokens, steps }) {
    this.#enter("finishRun", { runId, ok, output, error, tokens, ...(steps ? { steps } : {}) });
    const run = this.runs.find((each) => each.id === runId);
    if (!run) throw new SchedulerToolError(`No run with id ${runId}.`);
    Object.assign(run, { status: ok ? "ok" : "error", output, error, tokens, steps: steps ?? [], finishedAt: this.now() });
    return { ...run };
  }

async getRun(runId) {
    this.#enter("getRun", { runId });
    const run = this.runs.find((each) => each.id === runId);
    if (!run) throw new SchedulerToolError(`No run with id ${runId}.`);
    const { steps = [], ...rest } = run;
    return { run: { ...rest }, steps: structuredClone(steps) };
  }

  async listRuns(scheduleId, limit = 10) {
    this.#enter("listRuns", { scheduleId, limit });
    this.#schedule(scheduleId);
    return this.runs.filter((run) => run.scheduleId === scheduleId).reverse().slice(0, limit).map((run) => ({ ...run }));
  }

  async runNow(scheduleId) {
    this.#enter("runNow", { scheduleId });
    const schedule = this.#schedule(scheduleId);
    schedule.runPending = true;
    return this.#out(schedule);
  }

  async releaseRuns() {
    this.#enter("releaseRuns", {});
    let released = 0;
    for (const run of this.runs) {
      if (run.status === "running") {
        run.status = "error";
        released += 1;
      }
    }
    return { released };
  }

  async aggregate(scheduleId) {
    this.#enter("aggregate", { scheduleId });
    this.#schedule(scheduleId);
    const mine = this.records.filter((record) => record.scheduleId === scheduleId);
    return { invocations: mine.length, uniqueKeys: new Set(mine.map((record) => record.key)).size, mostRepeated: null, first: null, last: null };
  }
}

export const SCOPED_FIELD = "scheduleId";

/**
 * @param {object} params
 * @param {{ toolsFor: Function, route: Function, call: Function }} params.toolbox
 * @param {string[]} params.servers - The agent's `mcpServers`.
 * @param {Record<string, string[]>} [params.allow] - The agent's `tools`. A
 *   server with no entry contributes nothing.
 * @param {number} params.scheduleId - The schedule this run belongs to.
 */
export async function scopedTools({ toolbox, servers, allow = {}, scheduleId }) {
  const offered = await toolbox.toolsFor(servers);
  const allowed = new Set();
  const scoped = new Set();
  const tools = [];

  for (const tool of offered.tools) {
    const { server, tool: name } = toolbox.route(tool.name);
    if (!allow[server]?.includes(name)) continue;
    allowed.add(tool.name);
    const schema = tool.inputSchema ?? { type: "object", properties: {} };
    if (schema.properties && SCOPED_FIELD in schema.properties) {
      scoped.add(tool.name);
      tools.push({ ...tool, inputSchema: withoutField(schema, SCOPED_FIELD) });
    } else {
      tools.push(tool);
    }
  }

  /** The toolbox's `call`, behind the allowlist and with the schedule filled in. */
  async function call(name, input) {
    if (!allowed.has(name)) {
      const { server, tool } = toolbox.route(name);
      const text = `The tool "${name}" is not available to this task.`;
      return { server, tool, ok: false, text, preview: preview(text), ms: 0 };
    }
    const args = { ...(input ?? {}) };
    if (scoped.has(name)) args[SCOPED_FIELD] = scheduleId;
    return toolbox.call(name, args);
  }

  return { tools, unavailable: offered.unavailable, call };
}

export const DEFAULT_TICK_MS = 15000;
/**
 * How close to due a schedule may be and still be claimed on this tick. A
 * schedule's next run is its claim time plus its interval, and its claim time
 * is a tick — so with a 15 s interval on a 15 s tick, the next run is due *on*
 * the next tick, give or take the few milliseconds a timer is early or late.
 * Without slack, "due 3 ms after the tick" waits a whole extra tick: every
 * 30 s instead of every 15. Running a moment early is the better mistake.
 */
export const CLAIM_GRACE_MS = 1000;

export class Ticker {
  #scheduler;
  #runner;
  #intervalMs;
  #now;
  #setInterval;
  #clearInterval;
  #log;
  #repair;
  #timer = null;
  #claiming = false;
  #down = false;
  /** Runs left "running" by a previous process are released once, on the first tick that reaches the server. */
  #released = false;
  /** Every run still executing, so `stop()` and the tests can wait for them. */
  #inFlight = new Set();

  /**
   * @param {{
   *   scheduler: Pick<import("./client.js").SchedulerClient, "claimDueRuns" | "finishRun" | "releaseRuns" | "deleteSchedule">,
   *   runner: { run: (claimed: { run: object, schedule: object }) => Promise<{ ok: boolean, output?: string, error?: string, tokens?: number, steps?: object[], orphan?: boolean }> },
   *   intervalMs?: number,
   *   now?: () => number,
   *   setInterval?: typeof globalThis.setInterval,
   *   clearInterval?: typeof globalThis.clearInterval,
   *   log?: Pick<Console, "log" | "warn">,
   *   repair?: (failed: { run: object, schedule: object, outcome: object }) => Promise<unknown>,
   * }} deps - `repair` is called after a failed run is finished (never for
   *   an orphan); what it throws is logged, never raised.
   */
  constructor({
    scheduler,
    runner,
    intervalMs = DEFAULT_TICK_MS,
    now = Date.now,
    setInterval = globalThis.setInterval,
    clearInterval = globalThis.clearInterval,
    log = console,
    repair = null,
  }) {
    this.#scheduler = scheduler;
    this.#runner = runner;
    this.#intervalMs = intervalMs;
    this.#now = now;
    this.#setInterval = setInterval;
    this.#clearInterval = clearInterval;
    this.#log = log;
    this.#repair = repair;
  }

get running() {
    return this.#timer !== null;
  }

  start() {
    if (this.#timer) return;
    this.#timer = this.#setInterval(() => {
      this.tick().catch((err) => this.#log.warn(`[ticker] tick failed: ${describeError(err)}`));
    }, this.#intervalMs);
    this.#timer?.unref?.();
    this.#log.log(`[ticker] claiming due runs every ${this.#intervalMs / 1000} s`);
  }

  async stop() {
    if (this.#timer) this.#clearInterval(this.#timer);
    this.#timer = null;
    await Promise.allSettled([...this.#inFlight]);
  }

  /**
   * One tick: claim, then run everything claimed.
   *
   * @returns {Promise<{ skipped: "busy" | "down" } | { claimed: number }>}
   *   Resolves when every run this tick claimed has been finished.
   */
  async tick() {
    // Read the moment the tick fired, before anything is awaited.
    const at = this.#now();
    if (this.#claiming) return { skipped: "busy" };
    this.#claiming = true;
    let claimed;
    try {
      if (!this.#released) {
        const { released } = await this.#scheduler.releaseRuns();
        if (released) this.#log.log(`[ticker] released ${released} run(s) left open by a previous start`);
        this.#released = true;
      }
      ({ claimed = [] } = await this.#scheduler.claimDueRuns({ now: at, graceMs: CLAIM_GRACE_MS }));
      if (this.#down) this.#log.log("[ticker] the scheduler is reachable again");
      this.#down = false;
    } catch (err) {
      if (!this.#down) this.#log.warn(`[ticker] skipping ticks until the scheduler answers: ${describeError(err)}`);
      this.#down = true;
      return { skipped: "down" };
    } finally {
      this.#claiming = false;
    }

await Promise.all(claimed.map((each) => this.#track(this.#execute(each))));
    return { claimed: claimed.length };
  }

  #track(promise) {
    this.#inFlight.add(promise);
    return promise.finally(() => this.#inFlight.delete(promise));
  }

  async #execute({ run, schedule }) {
    let outcome;
    try {
      outcome = await this.#runner.run({ run, schedule });
    } catch (err) {
      outcome = { ok: false, error: describeError(err) };
    }
    if (!outcome?.ok) this.#log.warn(`[ticker] run ${run.id} (schedule ${schedule.id}) failed: ${outcome?.error ?? "no reason given"}`);

    try {
      await this.#scheduler.finishRun({
        runId: run.id,
        ok: Boolean(outcome?.ok),
        output: outcome?.output,
        error: outcome?.ok ? undefined : (outcome?.error ?? "The run failed without saying why."),
        tokens: outcome?.tokens,
        steps: outcome?.steps,
      });
    } catch (err) {
      // Left "running", it is released as stale in five minutes.
      this.#log.warn(`[ticker] could not finish run ${run.id}: ${describeError(err)}`);
    }

    if (!outcome?.ok && !outcome?.orphan && this.#repair) {
      try {
        await this.#repair({ run, schedule, outcome });
      } catch (err) {
        this.#log.warn(`[ticker] could not propose a repair for run ${run.id}: ${describeError(err)}`);
      }
    }

    if (outcome?.orphan) {
      try {
        await this.#scheduler.deleteSchedule(schedule.id);
        this.#log.log(`[ticker] deleted schedule ${schedule.id}: its conversation is gone`);
      } catch (err) {
        this.#log.warn(`[ticker] could not delete orphaned schedule ${schedule.id}: ${describeError(err)}`);
      }
    }
  }
}

import crypto from "node:crypto";
import path from "node:path";
import { fileURLToPath } from "node:url";

import "dotenv/config";
import express from "express";

import { Agent } from "./agent.js";
import { DEFAULT_AGENT, agentCatalog, agentFor, agentOf, isScheduledAgent, isValidAgent } from "./agents.js";
import { AnthropicProvider, FakeProvider } from "./llm/anthropic.js";
import { estimateCost } from "./llm/pricing.js";
import { forkFrom, isValidSessionId } from "./store/conversationStore.js";
import { memoryRoutes } from "./memoryRoutes.js";
import { McpRegistry } from "./mcp/servers.js";
import { McpToolbox } from "./mcp/toolbox.js";
import { mcpRoutes } from "./mcpRoutes.js";
import { Planner, buildCatalog } from "./pipeline/planner.js";
import { repairer } from "./pipeline/repair.js";
import { PipelineRunner } from "./pipeline/runner.js";
import { pipelineRoutes } from "./pipelineRoutes.js";
import { SchedulerClient } from "./scheduler/client.js";
import { DEFAULT_TICK_MS, Ticker } from "./scheduler/ticker.js";
import { JsonMcpAuthStore } from "./store/mcpAuthStore.js";
import { JsonFileStore } from "./store/jsonFileStore.js";
import { MemoryStore } from "./store/memoryStore.js";
import { DEFAULT_PROJECT, defaultInvariantStore, isValidProject } from "./store/invariantStore.js";
import { DEFAULT_USER, defaultProfileStore, isValidUser } from "./store/profileStore.js";

const PORT = Number(process.env.PORT) || 3000;
const __dirname = path.dirname(fileURLToPath(import.meta.url));
const PUBLIC_DIR = path.join(__dirname, "..", "public");

const DEFAULT_CONTEXT_MESSAGES = 10;
const MAX_CONTEXT_MESSAGES = 100;
const MAX_OUTPUT_TOKENS = 8192;

// One provider and one store, built once at startup and shared by every agent.
const provider = createProvider();
const store = await createStore();
// And one profile store: long-term memory belongs to the user, not to any one
// conversation, so there is exactly one of it for the whole process.
const profileStore = defaultProfileStore();

// And one invariant store. Long-term memory belongs to the user; the rules
// belong to the codebase, which is why they are two stores and not one.
const invariantStore = defaultInvariantStore();

// Every registered MCP server, connected on demand. The routes and the agents
// only see ids; the OAuth callback URL has to match the port the app is on.
const mcpRegistry = new McpRegistry({
  authStore: new JsonMcpAuthStore(),
  redirectUrl: `http://localhost:${PORT}/mcp/oauth/callback`,
});

// What an agent that opted into MCP servers calls its tools through.
const toolbox = new McpToolbox({ registry: mcpRegistry });

// A cache in front of the store, not the source of truth: a miss is a load,
// not a blank slate. That is what lets a conversation survive a restart.
/** @type {Map<string, Agent>} */
const sessions = new Map();

// Pipelines: the scheduler server called from code (never by a model), a
// runner that executes one claimed run's steps and posts one message, and the
// plain-code ticker that claims due runs. A run writes to the store directly,
// so it drops any cached Agent for that conversation, which would be stale.
const scheduler = new SchedulerClient({ mcp: mcpRegistry.get("scheduler") });

const runner = new PipelineRunner({ provider, store, registry: mcpRegistry, toolbox, onAppended: (id) => sessions.delete(id) });
// The planner turns a pipeline chat's goal into a proposed plan, from the
// catalog of every connected server the Pipeline agent may plan with. It runs
// when asked (Generate plan) and after a failed run (a repair proposal) —
// never on a tick that goes well.
const pipelineAgent = agentFor("pipeline");

const planner = new Planner({
  provider,
  model: pipelineAgent.model,
  catalog: () => buildCatalog({ registry: mcpRegistry, allow: pipelineAgent.plannerTools }),
});

const ticker = new Ticker({
  scheduler,
  runner,
  intervalMs: Number(process.env.SCHEDULER_TICK_MS) || DEFAULT_TICK_MS,
  repair: repairer({ planner, scheduler }),
});

function createProvider() {
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (apiKey) {
    return new AnthropicProvider({
      apiKey,
      // Optional: only identity-linked keys need it.
      workspaceId: process.env.ANTHROPIC_WORKSPACE_ID,
    });
  }

  console.warn(
    "⚠️  ANTHROPIC_API_KEY is not set — falling back to FakeProvider (canned replies, no network).\n" +
      "   Copy .env.example to .env and add your key for real responses."
  );
  return new FakeProvider();
}

/**
 * Conversations on disk, or in memory if the data directory cannot be
 * written to. Losing history on restart beats refusing to start.
 */
async function createStore() {
  const fileStore = new JsonFileStore();
  try {
    await fileStore.listSessions();
    return fileStore;
  } catch (err) {
    console.warn(
      `⚠️  ${fileStore.dir} is not writable (${err?.message ?? err}) — falling back to MemoryStore.\n` +
        "   Conversations will not survive a restart."
    );
    return new MemoryStore();
  }
}

/**
 * The Agent for a conversation, from the cache or from the store.
 *
 * `wanted` is the agent the request asked for, and it only decides anything for
 * a conversation with no messages yet: `Agent.load` restores the agent from
 * the record when there is one, because the transcript was answered by that
 * persona and a dropdown must not rewrite history.
 */
async function agentSession(sessionId, wanted) {
  let agent = sessions.get(sessionId);
  if (!agent) {
    agent = await Agent.load({
      provider,
      store,
      sessionId,
      name: "Assistant",
      agentId: agentOf(wanted),
      // The two stores that outlive a conversation, handed to whichever
      // strategy turns out to want them. The Agent itself never touches
      // either.
      strategyOptions: { profileStore, invariantStore },
      // Only agents that list `mcpServers` ever touch it.
      toolbox,
    });
    sessions.set(sessionId, agent);
  } else {
    // A chat opened but not yet spoken in may have been cached by a request
    // that named no agent (the panel refresh); the one that names it decides.
    agent.adoptAgent(wanted);
  }
  return agent;
}

const app = express();
// 100 KB (the default) is small enough to reject a long pasted message before
// the agent ever sees it — and a long pasted message is exactly the input this
// version exists to put a token count on.
app.use(express.json({ limit: "5mb" }));
app.use(express.static(PUBLIC_DIR));

// The browser gets the same PRICING table and the same formatters the server
// uses, rather than a second copy that can quietly disagree with it.
app.get("/pricing.js", (_req, res) => {
  res.type("application/javascript").sendFile(PRICING_FILE);
});

app.get("/vendor/:file", (req, res) => {
  const file = VENDOR[req.params.file];
  if (!file) return res.status(404).json({ error: "No such vendor file." });
  res.type("application/javascript").sendFile(file);
});

// The task boundary — finishing a task, answering a proposal, forgetting a row.
// None of it is a turn, so none of it belongs on /chat. Dropping the cached
// agent is what stops the next turn writing stale memory back over it.
app.use(
  memoryRoutes({ store, provider, profileStore, invariantStore, invalidate: (id) => sessions.delete(id) })
);

app.use(mcpRoutes({ registry: mcpRegistry }));

// Before the chat routes on purpose: it answers POST /chat, fork and delete for
// a pipeline chat, and hands everything else on. Run kicks the ticker, so a
// run starts now rather than on the next 15 s tick.
app.use(
  pipelineRoutes({
    store,
    scheduler,
    planner,
    kick: () => ticker.tick(),
    invalidate: (id) => sessions.delete(id),
  })
);

/**
 * Which agents exist — the dropdown in the title, built from the registry.
 *
 * Same discipline as the two pickers below: the list comes from the thing that
 * owns it, never from a second list in the UI that can quietly disagree.
 */
app.get("/agents", (_req, res) => {
  res.json({ agents: agentCatalog(), default: DEFAULT_AGENT });
});

/**
 * Which profiles exist — the topbar picker, built from the store.
 *
 * The list comes from the thing that owns it, never from a second list in the
 * UI that can quietly disagree. A profile
 * id that has never been written has no file and is not listed, which is
 * correct — it comes into existence the moment something is declared in it.
 */
app.get("/profiles", async (_req, res) => {
  try {
    const profiles = await profileStore.list();
    // The default is always offered, even before anything has been written to
    // it: a picker whose first entry appears only after you have used it is a
    // picker you cannot use.
    if (!profiles.some((profile) => profile.id === DEFAULT_USER)) {
      profiles.unshift({ id: DEFAULT_USER, entryCount: 0, updatedAt: null });
    }
    res.json({ profiles, default: DEFAULT_USER });
  } catch (err) {
    console.error("[/profiles]", err);
    res.status(500).json({ error: "Could not list profiles." });
  }
});

/**
 * Which projects have rules — the topbar's other picker.
 *
 * Same discipline as `/profiles`: the list comes from the store that owns it.
 * The default is always offered even before anything has been written to it,
 * because a picker whose first entry appears only after you have used it is a
 * picker you cannot use.
 */
app.get("/projects", async (_req, res) => {
  try {
    const projects = await invariantStore.list();
    if (!projects.some((project) => project.id === DEFAULT_PROJECT)) {
      projects.unshift({ id: DEFAULT_PROJECT, entryCount: 0, updatedAt: null });
    }
    res.json({ projects, default: DEFAULT_PROJECT });
  } catch (err) {
    console.error("[/projects]", err);
    res.status(500).json({ error: "Could not list projects." });
  }
});

/**
 * One profile, as it stands in the store right now.
 *
 * The panel's profile section is *what was sent on the last turn of this
 * conversation* — a snapshot, stamped, and deliberately conversation-local. The
 * editor needs the other thing: what the store actually holds for the profile
 * you have selected, right now, whether or not this conversation has ever used
 * it. Seeding a form from the snapshot would mean editing a copy of something
 * that may be a fork and several turns old.
 */
app.get("/profiles/:id", async (req, res) => {
  const { id } = req.params;
  if (!isValidUser(id)) return res.status(400).json({ error: "Not a valid profile id." });

try {
    const profile = await profileStore.load(id.toLowerCase());
    res.json({
      id: profile.user,
      updatedAt: profile.updatedAt,
      entries: Object.values(profile.entries)
        .map((entry) => ({ key: entry.key, value: entry.value, source: entry.source, updatedAt: entry.updatedAt }))
        .sort((a, b) => a.key.localeCompare(b.key)),
    });
  } catch (err) {
    console.error("[/profiles/:id]", err);
    res.status(500).json({ error: "Could not read that profile." });
  }
});

/**
 * Delete a profile, or a project's rules.
 *
 * **The default id is emptied rather than removed.** Both list routes always
 * offer it, because a picker whose first entry appears only after you have used
 * it is a picker you cannot use — so deleting its file makes it empty, not
 * absent, and the response says which of the two happened rather than leaving
 * the page to guess.
 *
 * No cached `Agent` is dropped, and that is not an oversight: neither store is
 * read through an Agent. Every turn loads the profile and the rules fresh, so
 * the next one already sees this. What a conversation keeps is the *snapshot* of
 * what it was last sent, which is history and stays true.
 */
function deleteScoped({ route, store, isValid, defaultId, noun }) {
  app.delete(route + "/:id", async (req, res) => {
    const id = String(req.params.id ?? "").trim().toLowerCase();
    if (!isValid(id)) return res.status(400).json({ error: `Not a valid ${noun} id.` });

    try {
      await store.clear(id);
      res.json({ ok: true, id, emptied: id === defaultId });
    } catch (err) {
      console.error(`[DELETE ${route}/:id]`, err);
      res.status(500).json({ error: `Could not delete that ${noun}.` });
    }
  });
}

deleteScoped({
  route: "/profiles",
  store: profileStore,
  isValid: isValidUser,
  defaultId: DEFAULT_USER,
  noun: "profile",
});

deleteScoped({
  route: "/projects",
  store: invariantStore,
  isValid: isValidProject,
  defaultId: DEFAULT_PROJECT,
  noun: "project",
});

/**
 * What the memory panel should draw, read here because a panel is built
 * synchronously and these live in stores.
 *
 * The ids come from the request because the pickers are in the topbar rather
 * than in the conversation: the panel answers *what would the next turn be
 * sent*, and the next turn is sent whatever the pickers currently say. Without
 * them a conversation nobody has spoken in yet draws an empty rule set and an
 * empty profile, which reads as "there are no rules and nothing is known about
 * you" when the truth is "nothing has been sent yet".
 */
async function panelContext(req, agent) {
  const user = isValidUser(req.query?.profile) ? String(req.query.profile).toLowerCase() : (agent.profileUser ?? DEFAULT_USER);
  const project = isValidProject(req.query?.project) ? String(req.query.project).toLowerCase() : (agent.project ?? DEFAULT_PROJECT);
  const [invariants, profile] = await Promise.all([
    invariantStore.load(project).catch(() => null),
    profileStore.load(user).catch(() => null),
  ]);
  return { invariants, profile, user, project };
}

app.post("/chat", async (req, res) => {
  const { message, sessionId, contextMessages, maxTokens, profile, project } = req.body ?? {};
  // The agent the page is on. It decides only for a conversation that does not
  // exist yet — an existing record names its own, and that one wins.
  const wantedAgent = req.body?.agent;

  if (typeof message !== "string" || !message.trim()) {
    return res.status(400).json({ error: "A non-empty 'message' is required." });
  }
  if (!isValidSessionId(sessionId)) {
    return res.status(400).json({ error: "A 'sessionId' in UUID v4 form is required." });
  }

const window = boundedInt(contextMessages, 1, MAX_CONTEXT_MESSAGES, DEFAULT_CONTEXT_MESSAGES);
  if (window === null) {
    return res
      .status(400)
      .json({ error: `'contextMessages' must be an integer between 1 and ${MAX_CONTEXT_MESSAGES}.` });
  }

  const ceiling = boundedInt(maxTokens, 1, MAX_OUTPUT_TOKENS, 1024);
  if (ceiling === null) {
    return res
      .status(400)
      .json({ error: `'maxTokens' must be an integer between 1 and ${MAX_OUTPUT_TOKENS}.` });
  }

  if (profile !== undefined && !isValidUser(profile)) {
    return res.status(400).json({ error: "'profile' must be lowercase letters, digits, dash or underscore." });
  }

  if (project !== undefined && !isValidProject(project)) {
    return res.status(400).json({ error: "'project' must be lowercase letters, digits, dash or underscore." });
  }

  if (wantedAgent !== undefined && !isValidAgent(wantedAgent)) {
    return res.status(400).json({ error: "'agent' must be one this server knows." });
  }

  try {
    const agent = await agentSession(sessionId, wantedAgent);

// Live controls in the UI, so they are settings for this turn rather than
    // something fixed when the agent was built.
    agent.contextMessages = window;
    agent.maxTokens = ceiling;
    // Whose long-term memory this turn reads and writes. A live control like
    // the other two: the topbar can switch profiles between two turns of the
    // same conversation, which is what makes "ask the same thing as someone
    // else" a thing you can do rather than a thing you have to rebuild for.
    agent.profileUser = profile ? String(profile).trim().toLowerCase() : DEFAULT_USER;
    // Whose rules this turn is subject to. Unlike the profile there is no
    // falling back to a default when the request is silent: the record
    // remembers which project the conversation belongs to, and resetting that
    // to `default` because one request forgot to say would quietly drop every
    // rule the project has for the length of a turn.
    if (project) agent.project = String(project).trim().toLowerCase();

    const { text, meta } = await agent.run(message);
    res.json({ reply: text, meta });
  } catch (err) {
    // Log the detail server-side; send back only something safe and readable.
    console.error("[/chat]", err);
    res.status(500).json({ error: readableError(err) });
  }
});

app.post("/reset", async (req, res) => {
  const { sessionId } = req.body ?? {};
  if (!isValidSessionId(sessionId)) {
    return res.status(400).json({ error: "A 'sessionId' in UUID v4 form is required." });
