/**
 * Session ids arrive from the client, so nothing downstream may treat one as
 * trustworthy until it has passed through here. A canonical UUID v4 contains
 * no separators, no dots and no slashes, which is exactly what makes it safe
 * to use as a filename.
 *
 * @param {unknown} id
 * @returns {boolean}
 */
export function isValidSessionId(id) {
  return typeof id === "string" && UUID_V4.test(id);
}

const TITLE_MAX = 40;

/**
 * A title given outright rather than derived — a scheduled chat has no user
 * message to derive one from, so it is named after its prompt. Cut to the
 * same length a derived one is.
 */
export function explicitTitle(value) {
  const text = typeof value === "string" ? value.replace(/\s+/g, " ").trim() : "";
  if (!text) return null;
  return text.length > TITLE_MAX ? text.slice(0, TITLE_MAX - 1).trimEnd() + "…" : text;
}

export function titleFrom(messages) {
  const first = messages?.find?.((m) => m?.role === "user")?.content ?? "";
  const text = String(first).replace(/\s+/g, " ").trim();
  if (!text) return UNTITLED;
  return text.length > TITLE_MAX ? text.slice(0, TITLE_MAX - 1).trimEnd() + "…" : text;
}

/**
 * A conversation that has cost nothing yet.
 *
 * A strategy's own calls are counted in their own four fields rather than
 * folded into the conversation totals. Context management is sold as a saving,
 * and a saving whose cost has been quietly added to the thing it is being
 * compared against is not a measurement.
 *
 * @returns {ConversationUsage}
 */
export function emptyUsage() {
  return {
    totalInputTokens: 0,
    totalOutputTokens: 0,
    totalCostUsd: 0,
    turnCount: 0,
    overheadInputTokens: 0,
    overheadOutputTokens: 0,
    overheadCostUsd: 0,
    overheadCalls: 0,
  };
}

/** Day 9 called the overhead "summarizer", because there was only one kind. */
const LEGACY_USAGE_KEYS = {
  overheadInputTokens: "summarizerInputTokens",
  overheadOutputTokens: "summarizerOutputTokens",
  overheadCostUsd: "summarizerCostUsd",
};

/**
 * Coerce whatever is on disk into a usage record. Conversations written before
 * this existed have no `usage` key at all, and they must keep loading — an old
 * file is a conversation that cost an unknown amount, not a corrupt one.
 *
 * @param {unknown} usage
 * @returns {ConversationUsage}
 */
export function normaliseUsage(usage) {
  const base = emptyUsage();
  if (!usage || typeof usage !== "object") return base;
  for (const key of Object.keys(base)) {
    const value = usage[key] ?? usage[LEGACY_USAGE_KEYS[key]];
    if (typeof value === "number" && Number.isFinite(value)) base[key] = value;
  }
  return base;
}

/**
 * Keep exactly the fields a stored message is allowed to have. `tokens` rides
 * along when a turn was measured and is simply absent when it wasn't — which
 * is the case for every message written before that existed.
 *
 * Every message gets an `id`, because that is what a fork is taken at and what
 * the page hangs its fork button on. A message from a file old enough not to
 * have one is numbered by its position, which is the id it would have been
 * given had it been written today.
 *
 * @param {StoredMessage[]} [messages]
 * @returns {StoredMessage[]}
 */
export function normaliseMessages(messages) {
  return withIds(messages ?? []).map((message) => {
    const stored = { role: message.role, content: message.content, id: message.id };
    if (message.tokens) stored.tokens = { ...message.tokens };
    if (message.cost) stored.cost = { ...message.cost };
    if (message.model) stored.model = message.model;
    if (typeof message.ms === "number") stored.ms = message.ms;
    if (message.stopReason) stored.stopReason = message.stopReason;
    if (message.truncated) stored.truncated = true;
    // What the strategy did on the turn that produced this message, so a
    // repainted transcript shows the same overhead the live one did.
    if (message.strategy) stored.strategy = { ...message.strategy };
    // Day 9 wrote the same idea under a different name and only ever for one
    // strategy. Kept so an old transcript still shows its own numbers.
    if (message.compression) stored.compression = { ...message.compression };
    // What the MCP tools did for this reply — a summary, never the raw
    // tool_use / tool_result blocks, which would break every boundary rule.
    if (Array.isArray(message.toolCalls) && message.toolCalls.length) {
      stored.toolCalls = message.toolCalls.map(({ server, tool, input, ok, resultPreview, ms }) => ({

server: String(server ?? ""),
        tool: String(tool ?? ""),
        input: input && typeof input === "object" ? structuredClone(input) : {},
        ok: Boolean(ok),
        resultPreview: String(resultPreview ?? ""),
        ms: typeof ms === "number" ? ms : null,
      }));
    }
    if (message.toolRoundsExceeded) stored.toolRoundsExceeded = true;
    // Which scheduled run posted this message, when a schedule did.
    if (message.run && typeof message.run === "object") {
      const { runId, durationMs, tokens, ok, error } = message.run;
      stored.run = {
        runId: Number(runId),
        durationMs: typeof durationMs === "number" ? durationMs : null,
        tokens: typeof tokens === "number" ? tokens : null,
        ok: ok !== false,
        ...(typeof error === "string" && error ? { error } : {}),
      };
    }
    if (Array.isArray(message.toolsUnavailable) && message.toolsUnavailable.length) {
      stored.toolsUnavailable = message.toolsUnavailable.map(({ server, error }) => ({ server: String(server), error: String(error) }));
    }
    // A pipeline run's step strip: what each step was and how it went. The
    // inputs and outputs live with the run on the scheduler, not here.
    if (Array.isArray(message.steps) && message.steps.length) {
      stored.steps = message.steps.map(({ index, kind, label, status, ms }) => ({
        index: Number(index),
        kind: kind === "tool" ? "tool" : "prompt",
        label: String(label ?? ""),
        status: ["ok", "error", "skipped"].includes(status) ? status : "error",
        ms: typeof ms === "number" ? ms : null,
      }));
    }
    return stored;
  });
}

/**
 * The whole record, coerced: usage, messages, and the branch graph.
 *
 * This is the single place a file from any earlier version becomes something
 * the current code can work with. It is called on read and never on write, so
 * an old file is migrated in memory and only takes its new shape the next time
 * something is actually saved to it.
 *
 * @param {object} data
 * @returns {Conversation}
 */
export function normaliseRecord(data) {
  const flat = flatten(data);
  return {
    id: data?.id,
    title: data?.title,
    createdAt: data?.createdAt,
    updatedAt: data?.updatedAt,
    usage: normaliseUsage(data?.usage),
    // **Which project's rules this conversation is subject to.**
    //
    // It lives on the record rather than being folded into the user key
    // because it is a different question: the user key says whose long-term
    // memory to read, this says whose invariants apply. One person has two
    // codebases with two rule sets, and a field that answered both would have
    // to pick one of them and be wrong about the other. A record written
    // before this field existed loads as the default project, which is the
    // honest answer for a conversation nobody ever said belonged anywhere.
    project: projectOf(data?.project),
    // **Which agent answers this conversation.** It is on the record rather
    // than chosen per request because the transcript below was written by one
    // persona, and a dropdown that silently re-pointed an open chat at another
    // would make the two halves of it disagree for no stated reason. A record
    // written before this field existed reads back as the default agent, which
    // is the honest answer for a conversation nobody ever assigned.
    agentId: agentOf(data?.agentId),
    // **Which conversation this one was split off from**, or null. It is a
    // provenance note and nothing more: a fork is a conversation in its own
    // right from the moment it exists, and deleting its parent does not
    // orphan it, because it holds its own copy of everything.

forkedFrom: forkOriginOf(data?.forkedFrom),
    ...flat,
  };
}

/** A fork's origin, or null for a conversation that was started rather than split. */
function forkOriginOf(value) {
  const conversationId = text(value?.conversationId);
  const messageId = text(value?.messageId);
  return conversationId && messageId ? { conversationId, messageId } : null;
}

/**
 * The messages and the memory state, however the file on disk spells them.
 *
 * There are three shapes in the wild. The current one is a flat `messages`
 * array and a top-level `memory`. Before forks became conversations there was a
 * pool of messages with `parentId` links and a `branches` map, where the
 * memory lived at `branches[x].strategyState.memory` — that reads back as
 * whichever branch was active, because that is the conversation the person was
 * actually in. Anything older is a flat array with no ids and no memory at all.
 *
 * Non-active branches are not reachable this way, on purpose: turning one into
 * its own conversation means *writing a new record*, which a read must not do.
 * `scripts/migrate-conversations.js` does that, once, on demand.
 */
function flatten(data) {
  const raw = Array.isArray(data?.messages) ? data.messages : [];
  const branches = data?.branches;

  if (!branches || typeof branches !== "object" || Array.isArray(branches)) {
    return { memory: memoryOf(data?.memory), messages: normaliseMessages(raw) };
  }

  const activeId = text(data?.activeBranchId);
  const branch = branches[activeId] ?? branches.main ?? Object.values(branches)[0];
  const chained = withIds(raw);
  return {
    memory: memoryOf(branch?.strategyState?.memory ?? data?.memory),
    messages: normaliseMessages(walkBack(chained, branch?.headId)),
  };
}

/**
 * The path from a branch head back to the root, reversed — the walk the branch
 * map used to need on every read.
 *
 * The loop is bounded by the size of the pool, so a file with a `parentId`
 * cycle in it produces a short conversation rather than a hung server. A head
 * that names nothing yields the whole pool in file order, which is the right
 * answer for a record whose branch map was written but never pointed anywhere.
 */
function walkBack(messages, headId) {
  const byId = new Map(messages.map((message) => [message.id, message]));
  if (!headId || !byId.has(headId)) return messages;

  const path = [];
  const seen = new Set();
  let cursor = headId;
  while (cursor && byId.has(cursor) && !seen.has(cursor) && path.length <= messages.length) {
    seen.add(cursor);
    const message = byId.get(cursor);
    path.push(message);
    cursor = message.parentId ?? null;
  }
  return path.reverse();
}

/**
 * Give every message an id, keeping the ones it already has. Sequential and
 * readable in a JSON file, which a UUID per message would not be.
 */
function withIds(messages) {
  const used = new Set();
  const out = [];
  for (const message of messages) {
    const existing = String(message?.id ?? "");
    const id = /^m\d+$/.test(existing) && !used.has(existing) ? existing : nextMessageId(out);
    used.add(id);
    out.push({ ...message, id });
  }
  return out;
}

/** The id the next message appended to a conversation should carry. */
export function nextMessageId(messages) {
  let highest = 0;
  for (const message of messages ?? []) {
    const match = /^m(\d+)$/.exec(String(message?.id ?? ""));
    if (match) highest = Math.max(highest, Number(match[1]));
  }
  return "m" + (highest + 1);
}

/** The strategy's state, or an empty object — never undefined. */
export function memoryOf(value) {
  return value && typeof value === "object" && !Array.isArray(value) ? structuredClone(value) : {};
}

/**
 * Split a conversation at a message: everything up to and including it, plus a
 * **copy** of the memory state.
 *
 * The copy is the whole point. Sharing the state would let something
 * established down one side show up on the other, and it would not present as
 * a storage bug — it would present as the model remembering something nobody
 * ever said in that conversation.
 *
 * @param {Conversation} record
 * @param {string} fromMessageId
 * @returns {{ messages: StoredMessage[], memory: object, forkedFrom: ForkOrigin }}
 */
export function forkFrom(record, fromMessageId) {
  const messages = record?.messages ?? [];
  const index = messages.findIndex((message) => message.id === fromMessageId);
  if (index < 0) throw new Error("No such message to fork from.");

  return {
    messages: messages.slice(0, index + 1).map((message) => ({ ...message })),
    memory: memoryOf(record.memory),
    forkedFrom: { conversationId: record.id, messageId: fromMessageId },
  };
}

function text(value) {
  return typeof value === "string" && value.trim() ? value.trim() : "";
}

/** How many superseded versions of one rule are worth keeping. */
const HISTORY_DEPTH = 8;

/** An invariant's text and its check are one line each in a system prompt. */
const MAX_TEXT = 240;

/**
 * Whether a string may be used as a project id.
 *
 * Exported because the id arrives from the browser — the topbar picker sends
 * it with every request — and a route has to be able to refuse one *before* it
 * reaches the store and becomes a path.
 *
 * @param {unknown} projectId
 */
export function isValidProject(projectId) {
  return typeof projectId === "string" && PROJECT_PATTERN.test(projectId.trim().toLowerCase());
}

/** A project id, or the default. The one coercion every caller shares. */
export function projectOf(value) {
  const id = typeof value === "string" ? value.trim().toLowerCase() : "";
  return isValidProject(id) ? id : DEFAULT_PROJECT;
}

/** How many withdrawn rules are worth keeping as a tombstone. */
const MAX_RETIRED = 12;

/** A project nobody has written a rule for yet. @returns {Invariants} */
export function emptyInvariants(project = DEFAULT_PROJECT) {
  return { project, updatedAt: null, nextId: 1, entries: {}, retired: [] };
}

/**
 * **The subject a key is about**, which is the whole of the collision rule.
 *
 * `invariant.database`, `preference.database` and `constraint.database` share
 * the subject `database`, and that sharing is deliberate: it is what turns
 * "does this new entry conflict with a rule?" into a string comparison rather
 * than a judgement a model would have to be paid to make and would get wrong
 * differently every run.
 *
 * A bare key — `goal` — has no subject and therefore collides with nothing.
 *
 * @param {string} key
 * @returns {string} The dotted remainder, or "" when there is none.
 */
export function subjectOf(key) {
  const text = typeof key === "string" ? key.trim().toLowerCase() : "";
  const dot = text.indexOf(".");
  return dot === -1 ? "" : text.slice(dot + 1);
}

/**
 * Whatever came off disk, coerced into a rule set.
 *
 * An invariant with no `check` is dropped rather than loaded: nothing can
 * create one, and a file hand-edited to contain one would put a rule on the
 * wire that nothing could ever say had been violated.
 *
 * @param {unknown} data
 * @param {string} [project]
 * @returns {Invariants}
 */
export function normaliseInvariants(data, project = DEFAULT_PROJECT) {
  const record = emptyInvariants(typeof data?.project === "string" && data.project ? data.project : project);
  if (!data || typeof data !== "object") return record;

let highest = 0;
  const coerce = (key, entry) => {
    const text = line(entry?.text);
    const check = line(entry?.check);
    // Both halves are required. A rule nobody could catch being broken is
    // the thing the drafting call turns into a `preference.*` instead.
    if (!text || !check) return null;
    const id = typeof entry?.id === "string" && entry.id ? entry.id : `i${++highest}`;
    const coerced = {
      id,
      key,
      subject: subjectOf(key),
      text,
      check,
      supersedes: typeof entry?.supersedes === "string" && entry.supersedes ? entry.supersedes : null,
      updatedAt: typeof entry?.updatedAt === "string" ? entry.updatedAt : null,
      turn: Number.isInteger(entry?.turn) ? entry.turn : 0,
      // **The archive.** An invariant that changed without a trace is worse
      // than none: the entire value of the mechanism is that it is stable,
      // so every version it has ever had stays readable after the fact.
      previous: (Array.isArray(entry?.previous) ? entry.previous : [])
        .map((old) => ({
          text: line(old?.text),
          check: line(old?.check),
          supersededAt: typeof old?.supersededAt === "string" ? old.supersededAt : null,
        }))
        .filter((old) => old.text)
        .slice(-HISTORY_DEPTH),
    };
    const numbered = /^i(\d+)$/.exec(id);
    if (numbered) highest = Math.max(highest, Number(numbered[1]));
    return coerced;
  };

  const source = data.entries;
  if (source && typeof source === "object") {
    for (const [key, entry] of Object.entries(source)) {
      const coerced = coerce(key, entry);
      if (coerced) record.entries[key] = coerced;
    }
  }

// Withdrawing a rule is a change to the rule set, so it leaves a tombstone
  // for the same reason an amendment leaves its old text: the mechanism is
  // worth having only because you can see, afterwards, exactly what it said
  // and when it stopped saying it.
  record.retired = (Array.isArray(data.retired) ? data.retired : [])
    .map((entry) => {
      const coerced = coerce(typeof entry?.key === "string" ? entry.key : "", entry);
      if (!coerced) return null;
      return { ...coerced, retiredAt: typeof entry?.retiredAt === "string" ? entry.retiredAt : null };
    })
    .filter(Boolean)
    .slice(-MAX_RETIRED);

  record.nextId = Number.isInteger(data.nextId) && data.nextId > highest ? data.nextId : highest + 1;
  record.updatedAt = typeof data.updatedAt === "string" ? data.updatedAt : null;
  return record;
}

/**
 * Write one invariant, keeping the id the key already had and archiving the
 * text it replaces.
 *
 * This is the amendment path, and the only one: `supersedes` names the
 * entry being replaced, and the sentence that was there goes into `previous[]`
 * rather than being overwritten.
 *
 * @param {Invariants} record
 * @param {{ key: string, text: string, check: string, turn?: number, at?: string }} params
 * @returns {{ entry: Invariant, amended: boolean }}
 */
export function writeInvariant(record, { key, text, check, turn = 0, at = new Date().toISOString() }) {
  const existing = record.entries[key];
  const changed = existing && (existing.text !== text || existing.check !== check);

  const entry = {
    id: existing?.id ?? `i${record.nextId ?? 1}`,
    key,
    subject: subjectOf(key),
    text,
    check,
    supersedes: changed ? existing.id : (existing?.supersedes ?? null),
    updatedAt: at,
    turn,
    previous: changed
      ? [...(existing.previous ?? []), { text: existing.text, check: existing.check, supersededAt: at }].slice(
          -HISTORY_DEPTH
        )
      : (existing?.previous ?? []),
  };

  if (!existing) record.nextId = (record.nextId ?? 1) + 1;
  record.entries[key] = entry;
  return { entry, amended: Boolean(existing) };
}

/**
 * Withdraw one invariant, keeping the tombstone. The amendment path's other
 * half: a rule that
 * vanished without a trace is the same failure as one that changed without
 * one.
 *
 * @returns {boolean} Whether there was anything to withdraw.
 */
export function retireInvariant(record, key, at = new Date().toISOString()) {
  const existing = record.entries?.[key];
  if (!existing) return false;
  delete record.entries[key];
  record.retired = [...(record.retired ?? []), { ...existing, retiredAt: at }].slice(-MAX_RETIRED);
  return true;
}

export class InvariantStore {
  /**
   * @param {string} [projectId]
   * @returns {Promise<Invariants>} Always a rule set — an unknown project is
   *   an empty one, never null.
   */
  // eslint-disable-next-line no-unused-vars
  async load(projectId) {
    throw new Error("Not implemented");
  }

  /**
   * @param {string} projectId
   * @param {Invariants} record - The whole rule set, as it should now stand.
   * @returns {Promise<Invariants>}
   */
  // eslint-disable-next-line no-unused-vars
  async save(projectId, record) {
    throw new Error("Not implemented");
  }

  /** @param {string} projectId @returns {Promise<void>} */
  // eslint-disable-next-line no-unused-vars
  async clear(projectId) {
    throw new Error("Not implemented");
  }

  /**
   * Which projects exist, for the picker — built from the store rather than
   * from a second list in the UI that can quietly disagree with it.
   *
   * @returns {Promise<{ id: string, entryCount: number, updatedAt: string | null }[]>}
   */
  async list() {
    return [];
  }
}

/**
 * One JSON file per project, in `data/invariants/`.
 *
 * Deliberately **not** in `data/memory/`, which is keyed by the human. Two
 * codebases belonging to one person need two rule sets, and a layer that could
 * only hold one of them would be wrong about the other on every turn.
 */
export class JsonInvariantStore extends InvariantStore {
  #dir;
  #ready;
  /** Writes are serialised per store, so two accepts cannot interleave. */
  #queue = Promise.resolve();

  constructor({ dir = path.join(import.meta.dirname, "..", "..", "data", "invariants") } = {}) {
    super();
    this.#dir = dir;
  }

  get dir() {
    return this.#dir;
  }

  async load(projectId = DEFAULT_PROJECT) {
    const file = this.#fileFor(projectId);
    let raw;
    try {
      raw = await fs.readFile(file, "utf8");
    } catch (err) {
      if (err?.code !== "ENOENT") {
        console.warn(`[invariants] could not read ${file}: ${err?.message ?? err}`);
      }
      return emptyInvariants(projectId);
    }

    try {
      return normaliseInvariants(JSON.parse(raw), projectId);
    } catch (err) {
      console.warn(`[invariants] ignoring unreadable rule set ${file}: ${err?.message ?? err}`);
      return emptyInvariants(projectId);
    }
  }

  async save(projectId = DEFAULT_PROJECT, record) {
    const file = this.#fileFor(projectId);
    const next = { ...normaliseInvariants(record, projectId), updatedAt: new Date().toISOString() };

// Same protocol as the other two file stores: write beside the target and
    // rename, so a crash mid-write cannot leave half a rule set behind.
    this.#queue = this.#queue.then(async () => {
      await this.#ensureDir();
      const tmp = file + ".tmp";
      await fs.writeFile(tmp, JSON.stringify(next, null, 2) + "\n", "utf8");
      await fs.rename(tmp, file);
    }, () => {});
    await this.#queue;
    return next;
  }

  async clear(projectId = DEFAULT_PROJECT) {
    try {
      await fs.unlink(this.#fileFor(projectId));
    } catch (err) {
      if (err?.code !== "ENOENT") throw err;
    }
  }

  async list() {
    let files = [];
    try {
      files = await fs.readdir(this.#dir);
    } catch (err) {
      if (err?.code !== "ENOENT") console.warn(`[invariants] could not list ${this.#dir}: ${err?.message ?? err}`);
      return [];
    }

    const projects = [];
    for (const name of files.sort()) {
      if (!name.endsWith(".json")) continue;
      const id = name.slice(0, -5);
      if (!isValidProject(id)) continue;
      const record = await this.load(id);
      projects.push({ id, entryCount: Object.keys(record.entries).length, updatedAt: record.updatedAt });
    }
    return projects;
  }

  /** The single place a project id becomes a path. */
  #fileFor(projectId) {
    const project = String(projectId ?? "").trim().toLowerCase();
    if (!PROJECT_PATTERN.test(project)) {
      throw new Error("Invalid project id: expected lowercase letters, digits, dash or underscore");
    }
    return path.join(this.#dir, project + ".json");
  }

#ensureDir() {
    this.#ready ??= fs.mkdir(this.#dir, { recursive: true });
    return this.#ready;
  }
}

/** The same contract backed by a Map: the twin the tests use. */
export class MemoryInvariantStore extends InvariantStore {
  /** @type {Map<string, Invariants>} */
  #projects = new Map();

  async load(projectId = DEFAULT_PROJECT) {
    const stored = this.#projects.get(projectId);
    return stored ? normaliseInvariants(structuredClone(stored), projectId) : emptyInvariants(projectId);
  }

  async save(projectId = DEFAULT_PROJECT, record) {
    const next = { ...normaliseInvariants(record, projectId), updatedAt: new Date().toISOString() };
    this.#projects.set(projectId, next);
    return structuredClone(next);
  }

  async clear(projectId = DEFAULT_PROJECT) {
    this.#projects.delete(projectId);
  }

  async list() {
    return [...this.#projects.entries()].map(([id, record]) => ({
      id,
      entryCount: Object.keys(record.entries ?? {}).length,
      updatedAt: record.updatedAt ?? null,
    }));
  }
}

/** @type {JsonInvariantStore | null} */
let shared = null;

/**
 * The process-wide invariant store. Built once and lazily, like the profile
 * store, so that merely listing the strategy catalogue touches no filesystem.
 */
export function defaultInvariantStore() {
  shared ??= new JsonInvariantStore();
  return shared;
}

function line(value) {
  return String(value ?? "").replace(/\s+/g, " ").trim().slice(0, MAX_TEXT);
}

import fs from "node:fs/promises";
import path from "node:path";

import { agentOf } from "../agents.js";
import {
  ConversationStore,
  emptyUsage,
  isValidSessionId,
  memoryOf,
  normaliseMessages,
  normaliseRecord,
  normaliseUsage,
  explicitTitle,
  titleFrom,
  UNTITLED,
} from "./conversationStore.js";
import { projectOf } from "./invariantStore.js";

// Resolved from this module, not the cwd — `npm start` from anywhere must
// read and write the same directory.
const DEFAULT_DIR = path.join(import.meta.dirname, "..", "..", "data", "conversations");

/**
 * One JSON file per conversation, named `<sessionId>.json`.
 *
 * This is the only file that knows about the filesystem: the directory
 * layout, the encoding, and the write protocol all stop here.
 */
export class JsonFileStore extends ConversationStore {
  #dir;
  #ready;

  /**
   * @param {object} [params]
   * @param {string} [params.dir]
   */
  constructor({ dir = DEFAULT_DIR } = {}) {
    super();
    this.#dir = dir;
  }

  get dir() {
    return this.#dir;
  }

  async load(sessionId) {
    const file = this.#fileFor(sessionId);
    await this.#ensureDir();
    return await this.#readRecord(file);
  }

  async save(sessionId, messages, usage, extra) {
    const file = this.#fileFor(sessionId);
    await this.#ensureDir();

    const now = new Date().toISOString();
    const existing = await this.#readRecord(file);
    const turns = normaliseMessages(messages);

const record = {
      id: sessionId,
      // Derived once and preserved afterwards — a conversation that keeps
      // renaming itself is disorienting. But the **placeholder is not a
      // title**, and a record saved before its first message carries one, so
      // it is re-derived until there is something real to derive it from.
      // That also heals any conversation already stuck with the placeholder.
      // An explicit title (a scheduled chat's prompt) wins over both.
      title: explicitTitle(extra?.title) ?? (existing?.title && existing.title !== UNTITLED ? existing.title : titleFrom(turns)),
      createdAt: existing?.createdAt ?? now,
      updatedAt: now,
      usage: usage ? normaliseUsage(usage) : (existing?.usage ?? emptyUsage()),
      // An absent field means "unchanged", not "cleared". A caller that does
      // not know invariants exist must not silently move the conversation to
      // another rule set, and one that is only writing a message must not wipe
      // the memory state or forget where the conversation was forked from.
      project: projectOf(extra?.project ?? existing?.project),
      agentId: agentOf(extra?.agentId ?? existing?.agentId),
      forkedFrom: extra?.forkedFrom ?? existing?.forkedFrom ?? null,
      memory: memoryOf(extra?.memory ?? existing?.memory),
      messages: turns,
    };

    // Write beside the target, then rename: `rename()` is atomic within a
    // directory, so a crash mid-write leaves the previous file intact rather
    // than a half-written one.
    const tmp = file + ".tmp";
    await fs.writeFile(tmp, JSON.stringify(record, null, 2) + "\n", "utf8");
    await fs.rename(tmp, file);

    return record;
  }

  async clear(sessionId) {
    const file = this.#fileFor(sessionId);
    try {
      await fs.unlink(file);
    } catch (err) {
      if (err?.code !== "ENOENT") throw err;
    }
  }

let names;
    try {
      names = await fs.readdir(this.#dir);
    } catch (err) {
      console.warn(`[store] could not read ${this.#dir}: ${err?.message ?? err}`);
      return [];
    }

    const summaries = [];
    for (const name of names) {
      if (!name.endsWith(".json")) continue;
      const record = await this.#readRecord(path.join(this.#dir, name));
      if (!record) continue; // missing or corrupt — skip it, don't fail the list
      // Each agent has its own list. The filter is applied here rather than by
      // the caller so that "how many chats does this agent have" is one read.
      if (agentId && record.agentId !== agentId) continue;
      summaries.push({
        id: record.id,
        title: record.title,
        updatedAt: record.updatedAt,
        messageCount: record.messages.length,
        agentId: record.agentId,
        forkedFrom: record.forkedFrom ?? null,
        totalCostUsd: record.usage.totalCostUsd,
      });
    }

    return summaries.sort((a, b) => String(b.updatedAt).localeCompare(String(a.updatedAt)));
  }

  /**
   * The single place a session id becomes a path. Validating here means an
   * unvalidated id can never reach the filesystem — an id like `../../.env`
   * would otherwise be an arbitrary file read or write.
   */
  #fileFor(sessionId) {
    if (!isValidSessionId(sessionId)) {
      throw new Error("Invalid sessionId: expected a UUID v4");
    }
    return path.join(this.#dir, sessionId + ".json");
  }

  #ensureDir() {
    this.#ready ??= fs.mkdir(this.#dir, { recursive: true });
    return this.#ready;
  }

/** Reads and normalises one file. Missing or corrupt both come back null. */
  async #readRecord(file) {
    let raw;
    try {
      raw = await fs.readFile(file, "utf8");
    } catch (err) {
      if (err?.code === "ENOENT") return null;
      console.warn(`[store] could not read ${file}: ${err?.message ?? err}`);
      return null;
    }

    try {
      const data = JSON.parse(raw);
      if (!data || !Array.isArray(data.messages)) throw new Error("unexpected shape");
      // Files written by earlier versions have no usage, no memory state and
      // no message ids, and some have a branch map instead of a flat list.
      // They read back as an ordinary conversation, not as a parse failure.
      return normaliseRecord(data);
    } catch (err) {
      // A corrupt file is a bad conversation, not a bad server.
      console.warn(`[store] ignoring unreadable conversation ${file}: ${err?.message ?? err}`);
      return null;
    }
  }
}

/** @param {unknown} server */
export function isValidServer(server) {
  return typeof server === "string" && SERVER_PATTERN.test(server);
}

/** @returns {McpAuthRecord} */
export function emptyAuth(server) {
  return { server, updatedAt: null };
}

export class McpAuthStore {
  /**
   * @param {string} server
   * @returns {Promise<McpAuthRecord>} Always a record — a server we have never
   *   talked to is an empty one.
   */
  // eslint-disable-next-line no-unused-vars
  async load(server) {
    throw new Error("Not implemented");
  }

  /**
   * Read, change, write — as one step, so the SDK saving the verifier and the
   * client information back to back cannot lose either.
   *
   * @param {string} server
   * @param {(record: McpAuthRecord) => McpAuthRecord | void} mutate
   * @returns {Promise<McpAuthRecord>}
   */
  // eslint-disable-next-line no-unused-vars
  async update(server, mutate) {
    throw new Error("Not implemented");
  }

  /** Forget the server entirely: registration, tokens, all of it. */
  // eslint-disable-next-line no-unused-vars
  async clear(server) {
    throw new Error("Not implemented");
  }
}

/** Apply a mutation to a copy and stamp it. */
function applied(server, current, mutate) {
  const draft = structuredClone(current);
  const next = mutate(draft) ?? draft;
  return { ...next, server, updatedAt: new Date().toISOString() };
}

/**
 * One JSON file per server, in `data/mcp/`. Git-ignored: it holds tokens.
 *
 * Same write protocol as every other store: beside the target, then renamed,
 * so a crash mid-write cannot leave a half-written token file behind. Written
 * owner-only, because it is a credential.
 */
export class JsonMcpAuthStore extends McpAuthStore {
  #dir;
  #ready;
  /** Updates are serialised per store: each one reads what the last wrote. */
  #queue = Promise.resolve();

  constructor({ dir = path.join(import.meta.dirname, "..", "..", "data", "mcp") } = {}) {
    super();
    this.#dir = dir;
  }

  get dir() {
    return this.#dir;
  }

  async load(server) {
    const file = this.#fileFor(server);
    let raw;
    try {
      raw = await fs.readFile(file, "utf8");
    } catch (err) {
      if (err?.code !== "ENOENT") console.warn(`[mcp-auth] could not read ${file}: ${err?.message ?? err}`);
      return emptyAuth(server);
    }
    try {
      const data = JSON.parse(raw);
      return data && typeof data === "object" ? { ...data, server } : emptyAuth(server);
    } catch (err) {
      console.warn(`[mcp-auth] ignoring unreadable ${file}: ${err?.message ?? err}`);
      return emptyAuth(server);
    }
  }

async update(server, mutate) {
    const file = this.#fileFor(server);
    const run = this.#queue.then(async () => {
      const record = applied(server, await this.load(server), mutate);
      await this.#ensureDir();
      const tmp = file + ".tmp";
      await fs.writeFile(tmp, JSON.stringify(record, null, 2) + "\n", { encoding: "utf8", mode: 0o600 });
      await fs.rename(tmp, file);
      return record;
    });
    // The chain survives a failed write; the caller still hears about it.
    this.#queue = run.catch(() => {});
    return run;
  }

  async clear(server) {
    const file = this.#fileFor(server);
    const run = this.#queue.then(async () => {
      try {
        await fs.unlink(file);
      } catch (err) {
        if (err?.code !== "ENOENT") throw err;
      }
    });
    this.#queue = run.catch(() => {});
    return run;
  }

  /** The single place a server name becomes a path. */
  #fileFor(server) {
    if (!isValidServer(server)) {
      throw new Error("Invalid MCP server name: expected lowercase letters, digits, dash or underscore");
    }
    return path.join(this.#dir, server + ".json");
  }

  #ensureDir() {
    this.#ready ??= fs.mkdir(this.#dir, { recursive: true });
    return this.#ready;
  }
}

/** The same contract backed by a Map: the twin the tests use. */
export class MemoryMcpAuthStore extends McpAuthStore {
  /** @type {Map<string, McpAuthRecord>} */
  #records = new Map();

  async load(server) {
    const stored = this.#records.get(server);
    return stored ? structuredClone(stored) : emptyAuth(server);
  }

  async update(server, mutate) {
    const record = applied(server, await this.load(server), mutate);
    this.#records.set(server, record);
    return structuredClone(record);
  }

  async clear(server) {
    this.#records.delete(server);
  }
}

import { agentOf } from "../agents.js";
import {
  ConversationStore,
  emptyUsage,
  isValidSessionId,
  memoryOf,
  normaliseMessages,
  normaliseRecord,
  normaliseUsage,
  explicitTitle,
  titleFrom,
  UNTITLED,
} from "./conversationStore.js";
import { projectOf } from "./invariantStore.js";

/**
 * The same contract, backed by a Map. Tests get persistence semantics with no
 * disk access, and the server can fall back to it when the data directory
 * turns out to be unwritable.
 */
export class MemoryStore extends ConversationStore {
  /** @type {Map<string, import("./conversationStore.js").Conversation>} */
  #records = new Map();

  async load(sessionId) {
    assertValid(sessionId);
    const record = this.#records.get(sessionId);
    return record ? clone(record) : null;
  }

  async save(sessionId, messages, usage, extra) {
    assertValid(sessionId);

    const now = new Date().toISOString();
    const existing = this.#records.get(sessionId);
    const turns = normaliseMessages(messages);

const record = {
      id: sessionId,
      // Derived once and preserved afterwards — a conversation that keeps
      // renaming itself is disorienting. But the **placeholder is not a
      // title**, and a record saved before its first message carries one, so
      // it is re-derived until there is something real to derive it from.
      // That also heals any conversation already stuck with the placeholder.
      // An explicit title (a scheduled chat's prompt) wins over both.
      title: explicitTitle(extra?.title) ?? (existing?.title && existing.title !== UNTITLED ? existing.title : titleFrom(turns)),
      createdAt: existing?.createdAt ?? now,
      updatedAt: now,
      usage: usage ? normaliseUsage(usage) : (existing?.usage ?? emptyUsage()),
      // An absent field means "unchanged", not "cleared". A caller that does
      // not know invariants exist must not silently move the conversation to
      // another rule set, and one that is only writing a message must not wipe
      // the memory state or forget where the conversation was forked from.
      project: projectOf(extra?.project ?? existing?.project),
      agentId: agentOf(extra?.agentId ?? existing?.agentId),
      forkedFrom: extra?.forkedFrom ?? existing?.forkedFrom ?? null,
      memory: memoryOf(extra?.memory ?? existing?.memory),
      messages: turns,
    };

this.#records.set(sessionId, record);
    return clone(record);
  }

  async clear(sessionId) {
    assertValid(sessionId);
    this.#records.delete(sessionId);
  }

  async listSessions({ agentId } = {}) {
    return [...this.#records.values()]
      .filter((record) => !agentId || record.agentId === agentId)
      .map((record) => ({
        id: record.id,
        title: record.title,
        updatedAt: record.updatedAt,
        messageCount: record.messages.length,
        agentId: record.agentId,
        forkedFrom: record.forkedFrom ?? null,
        totalCostUsd: record.usage?.totalCostUsd ?? 0,
      }))
      .sort((a, b) => String(b.updatedAt).localeCompare(String(a.updatedAt)));
  }
}

function assertValid(sessionId) {
  if (!isValidSessionId(sessionId)) {
    throw new Error("Invalid sessionId: expected a UUID v4");
  }
}

/** Callers get a copy, so they cannot mutate what the store is holding. */
function clone(record) {
  return { ...record, ...normaliseRecord(record) };
}

/**
 * Whether a string may be used as a profile id.
 *
 * Exported because the id now arrives from the browser — the topbar picker
 * sends it on every turn — and a route has to be able to refuse one *before*
 * it reaches the store and becomes a path.
 *
 * @param {unknown} userId
 */
export function isValidUser(userId) {
  return typeof userId === "string" && USER_PATTERN.test(userId.trim().toLowerCase());
}

export class ProfileStore {
  /**
   * @param {string} [userId]
   * @returns {Promise<Profile>} Always a profile — an unknown user is an empty
   *   one, never null. "We have never met" and "we met and learned nothing"
   *   are the same thing to every caller.
   */
  // eslint-disable-next-line no-unused-vars
  async load(userId) {
    throw new Error("Not implemented");
  }

  /**
   * @param {string} userId
   * @param {Profile} profile - The whole profile, as it should now stand.
   * @returns {Promise<Profile>} The record as persisted.
   */
  // eslint-disable-next-line no-unused-vars
  async save(userId, profile) {
    throw new Error("Not implemented");
  }

  /**
   * Forget a user entirely. The only way anything leaves this layer.
   * @param {string} userId
   * @returns {Promise<void>}
   */
  // eslint-disable-next-line no-unused-vars
  async clear(userId) {
    throw new Error("Not implemented");
  }

  /**
   * Which profiles exist, for the picker.
   *
   * The selector is built from the store rather than from a list in the UI,
   * for the same reason the strategy selector is built from the registry: a
   * second list of what exists is a second list that can be wrong.
   *
   * @returns {Promise<{ id: string, entryCount: number, updatedAt: string | null }[]>}
   */
  async list() {
    return [];
  }
}

/** A user we know nothing about yet. @returns {Profile} */
export function emptyProfile(user = DEFAULT_USER) {
  return { user, updatedAt: null, nextId: 1, entries: {} };
}

/**
 * Whatever came off disk, coerced into a profile.
 *
 * Long-term storage is the one place where a bad file is expensive: it is read
 * on every turn of every conversation for the rest of the user's life with the
 * app. So an entry that does not make sense is dropped and the rest still
 * loads, exactly as a corrupt conversation is skipped rather than fatal.
 *
 * @param {unknown} data
 * @param {string} [user]
 * @returns {Profile}
 */
export function normaliseProfile(data, user = DEFAULT_USER) {
  const profile = emptyProfile(typeof data?.user === "string" && data.user ? data.user : user);
  if (!data || typeof data !== "object") return profile;

  const source = data.entries;
  let highest = 0;
  if (source && typeof source === "object") {
    for (const [key, entry] of Object.entries(source)) {
      const value = String(entry?.value ?? "").replace(/\s+/g, " ").trim();
      if (!value) continue;
      const id = typeof entry?.id === "string" && entry.id ? entry.id : null;
      profile.entries[key] = {
        id: id ?? `e${++highest}`,
        key,
        value,
        updatedAt: typeof entry?.updatedAt === "string" ? entry.updatedAt : null,
        // Migration happens on read rather than in a one-off script: a
        // profile written before provenance existed is simply one nothing has
        // been declared in yet, and saying so costs one function call.
        source: provenanceOf(entry?.source),
      };
      const numbered = /^e(\d+)$/.exec(profile.entries[key].id);
      if (numbered) highest = Math.max(highest, Number(numbered[1]));
    }
  }

profile.nextId = Number.isInteger(data.nextId) && data.nextId > highest ? data.nextId : highest + 1;
  profile.updatedAt = typeof data.updatedAt === "string" ? data.updatedAt : null;
  return profile;
}

/**
 * One JSON file per user, in `data/memory/`.
 *
 * Deliberately **not** under `data/conversations/`: a profile that lived
 * beside the conversations would be deleted with one of them, and the whole
 * claim of the long-term layer is that it survives the conversation that
 * established it.
 */
export class JsonProfileStore extends ProfileStore {
  #dir;
  #ready;
  /** Writes are serialised per store, so two promotions cannot interleave. */
  #queue = Promise.resolve();

  constructor({ dir = path.join(import.meta.dirname, "..", "..", "data", "memory") } = {}) {
    super();
    this.#dir = dir;
  }

  get dir() {
    return this.#dir;
  }

  async load(userId = DEFAULT_USER) {
    const file = this.#fileFor(userId);
    let raw;
    try {
      raw = await fs.readFile(file, "utf8");
    } catch (err) {
      if (err?.code !== "ENOENT") {
        console.warn(`[profile] could not read ${file}: ${err?.message ?? err}`);
      }
      return emptyProfile(userId);
    }

    try {
      return normaliseProfile(JSON.parse(raw), userId);
    } catch (err) {
      console.warn(`[profile] ignoring unreadable profile ${file}: ${err?.message ?? err}`);
      return emptyProfile(userId);
    }
  }

  async save(userId = DEFAULT_USER, profile) {
    const file = this.#fileFor(userId);
    const record = { ...normaliseProfile(profile, userId), updatedAt: new Date().toISOString() };

// Same protocol as the conversation store: write beside the target and
    // rename, so a crash mid-write cannot leave a half-written profile behind.
    this.#queue = this.#queue.then(async () => {
      await this.#ensureDir();
      const tmp = file + ".tmp";
      await fs.writeFile(tmp, JSON.stringify(record, null, 2) + "\n", "utf8");
      await fs.rename(tmp, file);
    }, () => {});
    await this.#queue;
    return record;
  }

  async clear(userId = DEFAULT_USER) {
    const file = this.#fileFor(userId);
    try {
      await fs.unlink(file);
    } catch (err) {
      if (err?.code !== "ENOENT") throw err;
    }
  }

  async list() {
    let files = [];
    try {
      files = await fs.readdir(this.#dir);
    } catch (err) {
      // No directory yet is not an error: it is a user who has never been
      // written about, and the picker should still offer the default.
      if (err?.code !== "ENOENT") console.warn(`[profile] could not list ${this.#dir}: ${err?.message ?? err}`);
      return [];
    }

    const profiles = [];
    for (const name of files.sort()) {
      if (!name.endsWith(".json")) continue;
      const id = name.slice(0, -5);
      if (!isValidUser(id)) continue;
      const profile = await this.load(id);
      profiles.push({
        id,
        entryCount: Object.keys(profile.entries).length,
        updatedAt: profile.updatedAt,
      });
    }
    return profiles;
  }

/** The single place a user id becomes a path. */
  #fileFor(userId) {
    const user = String(userId ?? "").trim().toLowerCase();
    if (!USER_PATTERN.test(user)) {
      throw new Error("Invalid user id: expected lowercase letters, digits, dash or underscore");
    }
    return path.join(this.#dir, user + ".json");
  }

  #ensureDir() {
    this.#ready ??= fs.mkdir(this.#dir, { recursive: true });
    return this.#ready;
  }
}

/** The same contract backed by a Map: the twin the tests use. */
export class MemoryProfileStore extends ProfileStore {
  /** @type {Map<string, Profile>} */
  #profiles = new Map();

  async load(userId = DEFAULT_USER) {
    const stored = this.#profiles.get(userId);
    return stored ? normaliseProfile(structuredClone(stored), userId) : emptyProfile(userId);
  }

  async save(userId = DEFAULT_USER, profile) {
    const record = { ...normaliseProfile(profile, userId), updatedAt: new Date().toISOString() };
    this.#profiles.set(userId, record);
    return structuredClone(record);
  }

  async clear(userId = DEFAULT_USER) {
    this.#profiles.delete(userId);
  }

  async list() {
    return [...this.#profiles.entries()].map(([id, profile]) => ({
      id,
      entryCount: Object.keys(profile.entries ?? {}).length,
      updatedAt: profile.updatedAt ?? null,
    }));
  }
}

/** @type {JsonProfileStore | null} */
let shared = null;

/**
 * The process-wide profile store.
 *
 * Long-term memory is one thing shared by every conversation, so it is built
 * once rather than per agent — and lazily, so that merely listing the strategy
 * catalogue never touches the filesystem. A test injects its own instead.
 */
export function defaultProfileStore() {
  shared ??= new JsonProfileStore();
  return shared;
}

/** The sections every summary comes back in, in this order. */
export const SUMMARY_SECTIONS = [
  "## Facts about the user",
  "## Decisions made",
  "## Preferences and constraints",
  "## Open questions",
  "## Discarded / superseded",
];

export class Summarizer {
  #provider;

  /**
   * @param {object} params
   * @param {import("./llm/provider.js").LlmProvider} params.provider
   * @param {string} [params.model] - Optional override; the provider's own
   *   model is used when this is absent. A cheaper model here is a reasonable
   *   trade, which is why it is a knob at all.
   * @param {number} [params.maxTokens]
   */
  constructor({ provider, model, maxTokens = 600 } = {}) {
    if (!provider || typeof provider.complete !== "function") {
      throw new Error("Summarizer requires a provider with a complete() method");
    }
    this.#provider = provider;
    this.model = model;
    this.maxTokens = maxTokens;
  }

  /**
   * Fold newly-dropped messages into the existing summary.
   *
   * The `usage` this returns is the summarizer's own consumption and is handed
   * straight back to the caller rather than swallowed: compression is not free,
   * and a number that is hidden is a number that gets forgotten when the saving
   * is claimed.
   *
   * @param {object} params
   * @param {string | null} [params.previousSummary]
   * @param {import("./llm/provider.js").Message[]} params.messages - Exactly the
   *   messages that have just left the window, oldest first.
   * @returns {Promise<{ text: string, usage: import("./llm/provider.js").Usage, model: string | null, ms: number }>}
   */
  async summarize({ previousSummary = null, messages = [] } = {}) {
    if (!messages.length) {
      throw new Error("Summarizer.summarize() needs at least one message to fold in");
    }

const startedAt = Date.now();
    const result = await this.#provider.complete({
      model: this.model,
      system: SYSTEM_PROMPT,
      messages: [{ role: "user", content: promptFor(previousSummary, messages) }],
      // Nothing about this task benefits from variety, and a summary that
      // rewords itself every turn makes the panel in the UI flicker for no
      // reason.
      temperature: 0,
      maxTokens: this.maxTokens,
    });

    const text = String(result?.text ?? "").trim();
    if (!text) throw new Error("Summarizer got an empty summary back");

    return {
      text,
      usage: result.usage ?? { inputTokens: 0, outputTokens: 0 },
      model: result.model ?? null,
      ms: Date.now() - startedAt,
    };
  }
}

/** The one user message: what we had, and what has just fallen off the end. */
function promptFor(previousSummary, messages) {
  const previous = String(previousSummary ?? "").trim();
  return [
    "SUMMARY SO FAR:",
    previous || "(none — this is the first compression of this conversation)",
    "",
    `MESSAGES THAT HAVE JUST LEFT THE CONTEXT WINDOW (${messages.length}):`,
    ...messages.map((m) => `[${m.role}] ${m.content}`),
    "",
    "Return the updated summary.",
  ].join("\n");
}

/** Model → tools → model, at most this many times in one answer. */
export const MAX_TOOL_ROUNDS = 5;
export const TOOL_ROUNDS_FALLBACK =
  `I looked things up ${MAX_TOOL_ROUNDS} times without reaching an answer, so I stopped there. ` +
  "Try a narrower question, or name the exact title (and year) you mean.";

const RETRY_DELAYS_MS = [500, 1000, 2000];

/**
 * One model call, with up to three attempts, backing off on failures that are
 * worth retrying (rate limits and server-side errors). Everything else fails
 * immediately.
 *
 * @param {import("./llm/provider.js").LlmProvider} provider
 * @param {Parameters<import("./llm/provider.js").LlmProvider["complete"]>[0]} params
 * @param {{ delays?: number[], sleep?: (ms: number) => Promise<void> }} [options]
 */
export async function completeWithRetry(provider, params, { delays = RETRY_DELAYS_MS, sleep = defaultSleep } = {}) {
  let lastError;
  for (let attempt = 0; attempt < delays.length; attempt++) {
    try {
      return await provider.complete(params);
    } catch (err) {
      lastError = err;
      const retryable = err instanceof LlmError && (err.status === 429 || err.status >= 500);
      const attemptsLeft = attempt < delays.length - 1;
      if (!retryable || !attemptsLeft) throw err;
      await sleep(delays[attempt]);
    }
  }
  throw lastError;
}

/**
 * **One answer, however many model calls it takes.**
 *
 * Without tools this is exactly one call. With them, while the model stops on
 * `tool_use`, each requested tool is run, the assistant's blocks and the
 * results go on the end of *this call's* message list, and the model is asked
 * again. A tool that failed goes back as `isError`, so the model can say so or
 * try something else. After `maxRounds` rounds the loop stops with a fallback
 * sentence rather than asking forever.
 *
 * The extended messages live only here. The caller gets the final text.
 *
 * @param {object} params
 * @param {(request: { system?: string, messages: object[], tools?: object[] }) => Promise<import("./llm/provider.js").Completion>} params.complete
 *   One model call; the caller decides the model, the temperature and the retries.
 * @param {string} [params.system]
 * @param {import("./llm/provider.js").Message[]} params.messages
 * @param {import("./llm/provider.js").ToolDefinition[]} [params.tools] - Absent or empty: no tools offered.
 * @param {(name: string, input: object) => Promise<{ server: string, tool: string, ok: boolean, text: string, preview: string, ms: number }>} [params.call]
 * @param {number} [params.maxRounds]
 */
export async function runToolLoop({ complete, system, messages, tools, call, maxRounds = MAX_TOOL_ROUNDS }) {
  const offered = tools?.length ? tools : undefined;

  let wire = messages;
  let result = await complete({ system, messages: wire, ...(offered ? { tools: offered } : {}) });
  const usage = { inputTokens: result.usage?.inputTokens ?? null, outputTokens: result.usage?.outputTokens ?? null };
  const toolCalls = [];
  let rounds = 0;
  let capped = false;

while (offered && result.stopReason === "tool_use") {
    const uses = (result.content ?? []).filter((block) => block.type === "tool_use");
    if (!uses.length) break;
    if (rounds === maxRounds) {
      capped = true;
      break;
    }
    rounds += 1;

    const results = [];
    for (const use of uses) {
      const done = await call(use.name, use.input);
      toolCalls.push({
        server: done.server,
        tool: done.tool,
        input: use.input ?? {},
        ok: done.ok,
        resultPreview: done.preview,
        ms: done.ms,
      });
      results.push({ type: "tool_result", toolUseId: use.id, content: done.text, ...(done.ok ? {} : { isError: true }) });
    }

    wire = [...wire, { role: "assistant", content: result.content }, { role: "user", content: results }];
    result = await complete({ system, messages: wire, tools: offered });
    usage.inputTokens = addCounts(usage.inputTokens, result.usage?.inputTokens);
    usage.outputTokens = addCounts(usage.outputTokens, result.usage?.outputTokens);
  }

  if (capped) {
    const said = result.text?.trim();
    result = { ...result, text: said ? `${said}\n\n${TOOL_ROUNDS_FALLBACK}` : TOOL_ROUNDS_FALLBACK };
  }

  return { result, usage, toolCalls, toolRounds: rounds, toolsCapped: capped };
}

/** Adds two counts where either may be unknown; both unknown stays unknown. */
export function addCounts(a, b) {
  if (typeof a !== "number" && typeof b !== "number") return null;
  return (a ?? 0) + (b ?? 0);
}

function defaultSleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/** OMDb's placeholder for "nothing here". */
function present(value) {
  if (typeof value !== "string") return value ?? null;
  const trimmed = value.trim();
  return trimmed && trimmed !== "N/A" ? trimmed : null;
}

/** `"148 min"` → 148; `"N/A"` → null. */
export function parseRuntime(value) {
  const text = present(value);
  if (!text) return null;
  const match = /(\d+)\s*min/i.exec(text) ?? /^(\d+)$/.exec(text);
  return match ? Number(match[1]) : null;
}

/** `"8.8"` → 8.8; `"N/A"` → null. */
export function parseRating(value) {
  const text = present(value);
  if (!text) return null;
  const number = Number(text.replace(/,/g, ""));
  return Number.isFinite(number) ? number : null;
}

/** `"Action, Adventure"` → ["Action", "Adventure"]; `"N/A"` → []. */
export function splitList(value) {
  const text = present(value);
  if (!text) return [];
  return text.split(",").map((item) => item.trim()).filter(Boolean);
}

/** One search hit. */
export function normalizeSearchItem(item) {
  return {
    title: present(item?.Title),
    year: present(item?.Year),
    imdbId: present(item?.imdbID),
    type: present(item?.Type),
  };
}

/** A search page: at most ten hits, plus how many OMDb says there are. */
export function normalizeSearch(data) {
  const results = (Array.isArray(data?.Search) ? data.Search : []).slice(0, 10).map(normalizeSearchItem);
  const total = Number(data?.totalResults);
  return { results, totalResults: Number.isFinite(total) ? total : results.length };
}

/** One title, in full. */
export function normalizeMovie(data) {
  return {
    title: present(data?.Title),
    year: present(data?.Year),
    runtimeMinutes: parseRuntime(data?.Runtime),
    genres: splitList(data?.Genre),
    director: present(data?.Director),
    actors: splitList(data?.Actors),
    plot: present(data?.Plot),
    imdbRating: parseRating(data?.imdbRating),
    ratings: (Array.isArray(data?.Ratings) ? data.Ratings : [])
      .map((rating) => ({ source: present(rating?.Source), value: present(rating?.Value) }))
      .filter((rating) => rating.source && rating.value),
    imdbId: present(data?.imdbID),
  };
}

export const OMDB_URL = "https://www.omdbapi.com/";
export const DEFAULT_TIMEOUT_MS = 8000;

export class OmdbError extends Error {
  /**
   * @param {string} message
   * @param {"config" | "network" | "timeout" | "http" | "omdb"} kind
   */
  constructor(message, kind) {
    super(message);
    this.name = "OmdbError";
    this.kind = kind;
  }
}

/**
 * @param {{
 *   apiKey?: string | (() => string | undefined),
 *   fetch?: typeof globalThis.fetch,
 *   timeoutMs?: number,
 *   baseUrl?: string,
 * }} [options] - `apiKey` may be a function, so a key added to `.env` after
 *   start-up is not the difference between a crash and a readable error.
 */
export function createOmdbClient({
  apiKey = () => process.env.OMDB_API_KEY,
  fetch = globalThis.fetch,
  timeoutMs = DEFAULT_TIMEOUT_MS,
  baseUrl = OMDB_URL,
} = {}) {
  const keyOf = typeof apiKey === "function" ? apiKey : () => apiKey;

  /** @param {Record<string, string | number | undefined>} params */
  async function get(params) {
    const key = String(keyOf() ?? "").trim();
    if (!key) {
      throw new OmdbError(
        "OMDB_API_KEY is not set on the OMDb MCP server. Get a free key at https://www.omdbapi.com/apikey.aspx and put it in imdb_mcp_server/.env.",
        "config"
      );
    }

    const url = new URL(baseUrl);
    for (const [name, value] of Object.entries(params)) {
      if (value !== undefined && value !== null && value !== "") url.searchParams.set(name, String(value));
    }
    url.searchParams.set("apikey", key);

let response;
    try {
      response = await fetch(url, { signal: AbortSignal.timeout(timeoutMs) });
    } catch (err) {
      if (err?.name === "TimeoutError" || err?.name === "AbortError") {
        throw new OmdbError(`OMDb did not answer within ${timeoutMs} ms.`, "timeout");
      }
      // Deliberately not the URL: it carries the key.
      const cause = err?.cause?.code ? ` (${err.cause.code})` : "";
      throw new OmdbError(`Could not reach OMDb: ${err?.message ?? err}${cause}.`, "network");
    }

    const raw = await response.text().catch(() => "");
    let data;
    try {
      data = JSON.parse(raw);
    } catch {
      throw new OmdbError(`OMDb answered HTTP ${response.status} with something that was not JSON.`, "http");
    }

    // OMDb reports its own failures in the body, sometimes with a 200 and
    // sometimes with a 401 — the body is the more specific of the two.
    if (data?.Response === "False") {
      throw new OmdbError(`OMDb: ${data.Error || "the request failed"}`, "omdb");
    }
    if (!response.ok) {
      throw new OmdbError(`OMDb answered HTTP ${response.status}.`, "http");
    }
    return data;
  }

return {
    /** `?s=` — a page of up to ten matches. */
    search({ query, year, type, page }) {
      return get({ s: query, y: year, type, page });
    },
    /** `?i=` — one title by its IMDb id. */
    byId(imdbId, { plot = "short" } = {}) {
      return get({ i: imdbId, plot });
    },
    /** `?t=` — OMDb's best single match for a title. */
    byTitle(title, { year, plot = "short" } = {}) {
      return get({ t: title, y: year, plot });
    },
  };
}

import path from "node:path";

import dotenv from "dotenv";
import { createMcpExpressApp } from "@modelcontextprotocol/sdk/server/express.js";
import { StreamableHTTPServerTransport } from "@modelcontextprotocol/sdk/server/streamableHttp.js";

import { createOmdbClient } from "./omdbClient.js";
import { createServer } from "./tools.js";

// The server's own .env, wherever it was started from.
dotenv.config({ path: path.join(import.meta.dirname, "..", ".env"), quiet: true });

const HOST = "127.0.0.1";
const PORT = Number(process.env.PORT) || 3001;

// The key is read per call, so it is never copied anywhere else and a missing
// one is a tool error rather than a refusal to start.
const omdb = createOmdbClient({ apiKey: () => process.env.OMDB_API_KEY });

// DNS-rebinding protection for a localhost server comes with this helper.
const app = createMcpExpressApp({ host: HOST });

/**
 * Stateless streamable HTTP: a fresh server and transport per POST, no session
 * ids. There is nothing to remember between calls — every tool is a lookup.
 */
app.post("/mcp", async (req, res) => {
  const server = createServer({ omdb });
  const transport = new StreamableHTTPServerTransport({ sessionIdGenerator: undefined });
  res.on("close", () => {
    transport.close();
    server.close();
  });
  try {
    await server.connect(transport);
    await transport.handleRequest(req, res, req.body);
  } catch (err) {
    console.error("[mcp]", err?.message ?? err);
    if (!res.headersSent) {
      res.status(500).json({ jsonrpc: "2.0", error: { code: -32603, message: "Internal server error" }, id: null });
    }
  }
});

// No sessions, so no server-initiated stream and nothing to delete.
const notAllowed = (_req, res) => {
