}

/** A plan as the tools hand it in, checked; a bad list is a readable error. */
function checkedPlan(plan) {
  try {
    return validateSteps(plan);
  } catch (err) {
    if (err instanceof StepsError) throw new SchedulerError(err.message.replace(/^steps must/, "plan must"));
    throw err;
  }
}

function checkedProposal(proposal) {
  try {
    return validateProposal(proposal);
  } catch (err) {
    if (err instanceof StepsError) throw new SchedulerError(err.message);
    throw err;
  }
}

const MAX_GOAL_CHARS = 4000;

function checkGoal(goal) {
  if (typeof goal !== "string" || goal.length > MAX_GOAL_CHARS) {
    throw new SchedulerError(`goal must be text of at most ${MAX_GOAL_CHARS} characters.`);
  }
}

function checkMode(mode) {
  if (!MODES.includes(mode)) throw new SchedulerError(`mode must be "once" or "interval".`);
}

/**
 * Open (or create) the database and hand back the operations on it.
 *
 * @param {{ file?: string, now?: () => number }} [options] - `now` is the
 *   clock every default time is read from, which is how the tests move time.
 */
export function openScheduler({ file = DEFAULT_DB_PATH, now = Date.now } = {}) {
  if (file !== ":memory:") fs.mkdirSync(path.dirname(file), { recursive: true });
  const db = new Database(file);
  db.pragma("journal_mode = WAL");
  db.pragma("foreign_keys = ON");
  db.pragma("busy_timeout = 5000");
  const migrated = migrate(db);
  db.exec(SCHEMA);

ORDER BY COALESCE(s.runNowAt, s.nextRunAt), s.id`
    ),
    insertRun: db.prepare(`INSERT INTO runs (scheduleId, status, claimedAt) VALUES (?, 'running', ?)`),

first: db.prepare("SELECT label, createdAt FROM records WHERE scheduleId = ? ORDER BY createdAt, id LIMIT 1"),
    last: db.prepare("SELECT label, createdAt FROM records WHERE scheduleId = ? ORDER BY createdAt DESC, id DESC LIMIT 1"),
  };

function requireSchedule(id) {
    const row = q.scheduleById.get(id);
    if (!row) throw new SchedulerError(`No schedule with id ${id}.`);
    return row;
  }

  function checkInterval(seconds) {
    if (!Number.isInteger(seconds) || seconds < MIN_INTERVAL_SECONDS) {
      throw new SchedulerError(`intervalSeconds must be a whole number of at least ${MIN_INTERVAL_SECONDS}.`);
    }
  }

  const claim = db.transaction((at, graceMs) => {
    // A run that has been "running" for five minutes lost its runner — a crash,
    // a restart, a hung call. Closing it here is what lets its schedule be
    // claimed again below, in the same transaction.
    const released = q.releaseStale.run({ now: at, cutoff: at - STALE_AFTER_MS, staleMinutes: STALE_AFTER_MS / 60000 }).changes;
    const claimed = [];
    for (const row of q.due.all({ due: at + graceMs })) {
      const runId = Number(q.insertRun.run(row.id, at).lastInsertRowid);
      // An interval schedule that is on counts its next run from this claim;
      // a "once" schedule has none; one that is off keeps what it had.
      const nextRunAt = row.mode === "once" ? null : row.enabled ? at + row.intervalSeconds * 1000 : row.nextRunAt;
      q.pushNextRun.run({ id: row.id, nextRunAt });
      claimed.push({ run: runOut(q.runById.get(runId)), schedule: scheduleOut({ ...row, nextRunAt, runNowAt: null }) });
    }
    return { claimed, released };
  });

/**
   * The run's row and its step rows, in one transaction: a reader sees a
   * finished run with all of its steps, or a running one with none.
   */
  const finish = db.transaction((runId, fields, steps) => {
    if (q.finishRun.run({ id: runId, ...fields }).changes !== 1) {
      throw new SchedulerError(`Run ${runId} is already finished.`);
    }
    for (const step of steps) {
      q.insertStep.run({
        runId,
        index: step.index,
        kind: step.kind,
        server: step.server ?? null,
        tool: step.tool ?? null,
        input: toJson(step.input),
        output: toJson(step.output),
        toolCalls: step.toolCalls?.length ? JSON.stringify(step.toolCalls) : null,
        status: step.status,
        error: step.error ?? null,
        ms: step.ms ?? null,
        tokens: step.tokens ?? null,
      });
    }
  });

  return {
    /** The file it is backed by, for the start-up line. */
    file,
    /** How many Day 18/19 schedules this open migrated to goal + plan (0 almost always). */
    migrated,

createSchedule({ conversationId, mode = "interval", goal = "", plan = [], proposal = null, intervalSeconds = 60, enabled = false }) {
      checkMode(mode);
      checkInterval(intervalSeconds);
      checkGoal(goal);
      const clean = checkedPlan(plan);
      const pending = checkedProposal(proposal);
      if (q.scheduleByConversation.get(conversationId)) {
        throw new SchedulerError(`Conversation ${conversationId} already has a schedule.`);
      }
      const at = now();
      const id = Number(
        q.insertSchedule.run({
          conversationId,
          mode,
          goal,
          plan: JSON.stringify(clean),
          proposal: toJson(pending),
          intervalSeconds,
          enabled: enabled ? 1 : 0,
          nextRunAt: mode === "interval" ? at : null,
          now: at,
        }).lastInsertRowid
      );
      return scheduleOut(q.scheduleById.get(id));
    },

    /** @returns {object | null} */
    getSchedule({ conversationId }) {
      return scheduleOut(q.scheduleByConversation.get(conversationId));
    },

/**
     * Change any of mode, goal, plan, proposal, interval and enabled.
     * `proposal: null` clears a pending one. Switching an interval
     * schedule on (or switching an enabled one to interval) makes it due now —
     * nobody enables a task to wait a full interval for the first result — and
     * shortening the interval pulls the next run in. "once" has no next run.
     */
    updateSchedule({ scheduleId, mode, goal, plan, proposal, intervalSeconds, enabled }) {
      const row = requireSchedule(scheduleId);
      if (mode !== undefined) checkMode(mode);
      if (intervalSeconds !== undefined) checkInterval(intervalSeconds);
      if (goal !== undefined) checkGoal(goal);
      const at = now();
      const next = {
        id: row.id,
        mode: mode ?? row.mode,
        goal: goal ?? row.goal,
        plan: plan === undefined ? row.plan : JSON.stringify(checkedPlan(plan)),
        proposal: proposal === undefined ? row.proposal : toJson(checkedProposal(proposal)),
        intervalSeconds: intervalSeconds ?? row.intervalSeconds,
        enabled: enabled === undefined ? row.enabled : enabled ? 1 : 0,
        nextRunAt: row.nextRunAt,
        now: at,
      };
      const wasTicking = row.mode === "interval" && row.enabled;
      if (next.mode === "once") next.nextRunAt = null;
      else if (next.enabled && !wasTicking) next.nextRunAt = at;
      else if (row.nextRunAt == null) next.nextRunAt = at;
      else next.nextRunAt = Math.min(row.nextRunAt, at + next.intervalSeconds * 1000);
      q.updateSchedule.run(next);
      return scheduleOut(q.scheduleById.get(row.id));
    },

/** Runs and records go with it (ON DELETE CASCADE). */
    deleteSchedule({ scheduleId }) {
      const deleted = q.deleteSchedule.run(scheduleId).changes > 0;
      return { deleted, scheduleId };
    },

    listSchedules() {
      return q.allSchedules.all().map(scheduleOut);
    },

    /**
     * **The one place a run starts.** Every enabled schedule that is due and is
     * not already running gets a run row and its next time, in one transaction:
     * two tickers asking at once get disjoint answers.
     *
     * `graceMs` (default 0) widens only "is it due": a schedule due within
     * that much of `now` is claimed now. The next run is still measured from
     * the real claim time. A ticker whose period equals the interval needs a
     * little of it — its ticks are a few milliseconds early or late relative
     * to the last claim, and without slack "a few ms early" skips a whole tick.
     */
    claimDueRuns({ now: when, graceMs = 0 } = {}) {
      if (!Number.isFinite(graceMs) || graceMs < 0 || graceMs > MAX_GRACE_MS) {
        throw new SchedulerError(`graceMs must be between 0 and ${MAX_GRACE_MS}.`);
      }
      return claim(msOf(when, now), graceMs);
    },

/**
     * Close a run, with the steps it took. The run and its steps are written
     * together or not at all: a step list the table refuses (two steps with
     * one index, say) leaves the run open and nothing stored.
     */
    finishRun({ runId, ok, output = null, error = null, tokens = null, steps = [] }) {
      const run = q.runById.get(runId);
      if (!run) throw new SchedulerError(`No run with id ${runId}.`);
      if (run.status !== "running") {
        throw new SchedulerError(`Run ${runId} is already finished (${run.status}${run.error ? `: ${run.error}` : ""}).`);
      }
      try {
        finish(runId, { status: ok ? "ok" : "error", now: now(), output, error, tokens }, steps);
      } catch (err) {
        if (err instanceof SchedulerError) throw err;
        throw new SchedulerError(`The run and its steps were not stored: ${err.message}`);
      }
      return runOut(q.runById.get(runId));
    },

    /** One run with every step it took, in order. */
    getRun({ runId }) {
      const run = q.runById.get(runId);
      if (!run) throw new SchedulerError(`No run with id ${runId}.`);
      return { run: runOut(run), steps: q.stepsOfRun.all(runId).map(stepOut) };
    },

    listRuns({ scheduleId, limit = 10 }) {
      requireSchedule(scheduleId);
      return q.listRuns.all(scheduleId, limit).map(runOut);
    },

/**
     * A run is wanted: the next claim takes it, whatever the mode and whether
     * or not the schedule is enabled — the button is an explicit ask.
     */
    runNow({ scheduleId }) {
      requireSchedule(scheduleId);
      q.runNow.run({ id: scheduleId, now: now() });
      return scheduleOut(q.scheduleById.get(scheduleId));
    },

/**
     * Close every run still marked running. For an app that has just started:
     * whatever it was running before it stopped is not coming back, and
     * waiting out the five-minute stale window would pause those schedules.
     */
    releaseRuns({ reason = "Abandoned: the app restarted while this run was in flight." } = {}) {
      return { released: q.releaseAll.run({ now: now(), reason }).changes };
    },

    record({ scheduleId, key, label, data }) {
      requireSchedule(scheduleId);
      const at = now();
      const id = Number(
        q.insertRecord.run({ scheduleId, key, label, data: data === undefined ? null : JSON.stringify(data), now: at }).lastInsertRowid
      );
      return { id, scheduleId, key, label, createdAt: iso(at) };
    },

    /** Numbers about the records, computed in SQL. No rows leave. */
    aggregate({ scheduleId }) {
      requireSchedule(scheduleId);
      const { invocations, uniqueKeys } = q.counts.get(scheduleId);
      const top = q.mostRepeated.get(scheduleId);
      const first = q.first.get(scheduleId);
      const last = q.last.get(scheduleId);
      return {
        invocations,
        uniqueKeys,
        mostRepeated: top ? { label: top.label, count: top.count } : null,
        first: first ? { label: first.label, at: iso(first.createdAt) } : null,
        last: last ? { label: last.label, at: iso(last.createdAt) } : null,
      };
    },

    close() {
      db.close();
    },
  };
}

import path from "node:path";

import dotenv from "dotenv";
import express from "express";
import { localhostHostValidation } from "@modelcontextprotocol/sdk/server/middleware/hostHeaderValidation.js";
import { StreamableHTTPServerTransport } from "@modelcontextprotocol/sdk/server/streamableHttp.js";

import { DEFAULT_DB_PATH, openScheduler } from "./db.js";
import { createServer } from "./tools.js";

// The server's own .env, wherever it was started from.
dotenv.config({ path: path.join(import.meta.dirname, "..", ".env"), quiet: true });

const HOST = "127.0.0.1";
const PORT = Number(process.env.PORT) || 3002;
const DB_FILE = process.env.SCHEDULER_DB ? path.resolve(process.env.SCHEDULER_DB) : DEFAULT_DB_PATH;

// One database handle for the life of the process; one MCP server per request.
const scheduler = openScheduler({ file: DB_FILE });

// What `createMcpExpressApp` does — DNS-rebinding protection, then JSON — but
// with room for a finish_run that carries every step's input and output:
// express's default 100 kB is one long search result away.
const app = express();
app.use(localhostHostValidation());
app.use(express.json({ limit: "8mb" }));

/**
 * Stateless streamable HTTP, like the OMDb server: a fresh server and
 * transport per POST, no session ids. Everything worth remembering is in
 * SQLite, not in a session.
 */
app.post("/mcp", async (req, res) => {
  const server = createServer({ scheduler });
  const transport = new StreamableHTTPServerTransport({ sessionIdGenerator: undefined });
  res.on("close", () => {
    transport.close();
    server.close();
  });
  try {
    await server.connect(transport);
    await transport.handleRequest(req, res, req.body);
  } catch (err) {
    console.error("[mcp]", err?.message ?? err);
    if (!res.headersSent) {
      res.status(500).json({ jsonrpc: "2.0", error: { code: -32603, message: "Internal server error" }, id: null });
    }
  }
});

const notAllowed = (_req, res) => {
  res.status(405).json({ jsonrpc: "2.0", error: { code: -32000, message: "Method not allowed." }, id: null });
};
app.get("/mcp", notAllowed);
app.delete("/mcp", notAllowed);

const listener = app.listen(PORT, HOST, (err) => {
  if (err) {
    console.error(`Could not start on ${HOST}:${PORT}: ${err.message}`);
    process.exit(1);
  }
  console.log(`Scheduler MCP server listening at http://${HOST}:${PORT}/mcp`);
  console.log(`Database: ${scheduler.file}`);
  if (scheduler.migrated) console.log(`Migrated ${scheduler.migrated} older schedule(s) to goal + plan.`);
});

// Close the database cleanly, so the WAL is checkpointed on the way out.
for (const signal of ["SIGINT", "SIGTERM"]) {
  process.on(signal, () => {
    listener.close();
    scheduler.close();
    process.exit(0);
  });
}

export const MAX_STEPS = 20;
export const MAX_PROMPT_CHARS = 8000;
export const MAX_ARGS_CHARS = 20000;

export const MAX_WHY_CHARS = 500;
export const MAX_SCHEMA_CHARS = 8000;
export const STEP_KINDS = ["tool", "prompt"];

export const FORMATS = ["text", "json"];

const TEMPLATE = /\{\{\s*([^{}]*?)\s*\}\}/g;
const REFERENCE = /^(prev|now|steps\.(\d+))((?:\.[^.\s]+)*)$/;

const NAME = /^[A-Za-z0-9_.-]{1,64}$/;

/** A step list that does not pass, with every reason in one sentence. */
export class StepsError extends Error {
  constructor(problems) {
    super(problems.join(" "));
    this.name = "StepsError";
    this.problems = problems;
  }
}

/**
 * Check a whole list and hand back a clean copy (unknown keys are refused, not
 * dropped, so a typo is an error rather than a silently ignored field).
 *
 * @param {unknown} steps
 * @returns {Array<{ kind: "tool", server: string, tool: string, args: object, why?: string } | { kind: "prompt", text: string, allowTools: boolean, format?: "text" | "json", outputSchema?: object, why?: string }>}
 */
export function validateSteps(steps) {
  if (!Array.isArray(steps)) throw new StepsError(["steps must be an array."]);
  if (steps.length > MAX_STEPS) throw new StepsError([`At most ${MAX_STEPS} steps.`]);

  const problems = [];
  const clean = steps.map((step, i) => {
    const n = i + 1;
    const say = (text) => problems.push(`Step ${n}: ${text}`);
    if (!step || typeof step !== "object" || Array.isArray(step)) {
      say("must be an object.");
      return null;
    }
    if (!STEP_KINDS.includes(step.kind)) {
      say(`kind must be "tool" or "prompt".`);
      return null;
    }

let out;
    if (step.kind === "tool") {
      extraKeys(step, ["kind", "server", "tool", "args", "why"], say);
      if (typeof step.server !== "string" || !NAME.test(step.server)) say("needs a server.");
      if (typeof step.tool !== "string" || !NAME.test(step.tool)) say("needs a tool.");
      const args = step.args ?? {};
      if (!args || typeof args !== "object" || Array.isArray(args)) say("args must be a JSON object.");
      else if (JSON.stringify(args).length > MAX_ARGS_CHARS) say(`args must be at most ${MAX_ARGS_CHARS} characters of JSON.`);
      out = { kind: "tool", server: step.server, tool: step.tool, args };
    } else {
      extraKeys(step, ["kind", "text", "allowTools", "format", "outputSchema", "why"], say);
      if (typeof step.text !== "string" || !step.text.trim()) say("needs a prompt text.");
      else if (step.text.length > MAX_PROMPT_CHARS) say(`text must be at most ${MAX_PROMPT_CHARS} characters.`);
      if (step.allowTools !== undefined && typeof step.allowTools !== "boolean") say("allowTools must be true or false.");

out = { kind: "prompt", text: step.text, allowTools: step.allowTools === true };
      if (step.format !== undefined) {
        if (!FORMATS.includes(step.format)) say(`format must be "text" or "json".`);
        out.format = step.format;
      }
      if (step.outputSchema !== undefined) {
        const schema = step.outputSchema;
        if (step.format !== "json") say(`outputSchema needs format "json".`);
        if (!schema || typeof schema !== "object" || Array.isArray(schema)) say("outputSchema must be a JSON Schema object.");
        else if (JSON.stringify(schema).length > MAX_SCHEMA_CHARS) say(`outputSchema must be at most ${MAX_SCHEMA_CHARS} characters of JSON.`);
        out.outputSchema = schema;
      }
    }
    if (step.why !== undefined) {
      if (typeof step.why !== "string") say("why must be a string.");
      else if (step.why.length > MAX_WHY_CHARS) say(`why must be at most ${MAX_WHY_CHARS} characters.`);
      out.why = step.why;
    }

for (const problem of templateProblems(out, n)) say(problem);
    return out;
  });

  if (problems.length) throw new StepsError(problems);
  return clean;
}

function extraKeys(step, allowed, say) {
  const extra = Object.keys(step).filter((key) => !allowed.includes(key));
  if (extra.length) say(`unknown field${extra.length > 1 ? "s" : ""} ${extra.map((key) => `"${key}"`).join(", ")}.`);
}

/** Every template in a step that cannot resolve when step `n` runs. */
export function templateProblems(step, n) {
  const problems = [];
  for (const text of strings(step.kind === "tool" ? step.args : step.text)) {
    for (const [whole, inner] of text.matchAll(TEMPLATE)) {
      const ref = REFERENCE.exec(inner);
      if (!ref) {
        problems.push(`${whole} is not a template: use {{prev}}, {{steps.N}} or {{now}}.`);
      } else if (ref[1] === "prev" && n === 1) {
        problems.push(`${whole} has no previous step to refer to.`);
      } else if (ref[1] === "now" && ref[3]) {
        problems.push(`${whole}: {{now}} has no fields.`);
      } else if (ref[2] !== undefined) {
        const target = Number(ref[2]);
        if (target < 1 || target >= n) problems.push(`${whole} must refer to an earlier step (1 to ${n - 1}).`.replace("(1 to 0)", "(there is none)"));
      }
    }
  }
  return problems;
}

/** Every string value inside a value. Keys are never resolved, so they are not checked. */
function* strings(value) {
  if (typeof value === "string") yield value;
  else if (Array.isArray(value)) for (const item of value) yield* strings(item);
  else if (value && typeof value === "object") for (const item of Object.values(value)) yield* strings(item);
}

/**
 * **A plan waiting for a person to accept or discard it.** Null, or
 * `{ steps, notes?, createdAt, reason, errors?, run? }`.
 *
 * Its steps are checked for shape only — a list of objects — not with
 * `validateSteps`: a repair the planner could not make valid is still stored,
 * with its `errors`, so the panel can show what went wrong; it just cannot be
 * accepted. Accepting is what puts steps through the full check, as the plan.
 * `run` is the failed run a repair answers: `{ id, error }`.
 *
 * @param {unknown} proposal
 * @returns {object | null}
 */
export function validateProposal(proposal) {
  if (proposal === null) return null;
  if (!proposal || typeof proposal !== "object" || Array.isArray(proposal)) throw new StepsError(["proposal must be an object or null."]);
  const problems = [];
  const say = (text) => problems.push(`Proposal: ${text}`);
  extraKeys(proposal, ["steps", "notes", "createdAt", "reason", "errors", "run"], say);
  const { steps, notes, createdAt, reason, errors, run } = proposal;
  if (!Array.isArray(steps)) say("steps must be an array.");

else if (steps.length > MAX_STEPS) say(`at most ${MAX_STEPS} steps.`);
  else if (steps.some((step) => !step || typeof step !== "object" || Array.isArray(step))) say("every step must be an object.");
  if (notes !== undefined && typeof notes !== "string") say("notes must be a string.");
  if (typeof createdAt !== "string" || !Number.isFinite(Date.parse(createdAt))) say("createdAt must be an ISO time.");
  if (!PROPOSAL_REASONS.includes(reason)) say(`reason must be "generated" or "repair".`);
  if (errors !== undefined && !(Array.isArray(errors) && errors.every((error) => typeof error === "string"))) say("errors must be a list of strings.");
  if (run !== undefined && (!run || typeof run !== "object" || !Number.isInteger(run.id))) say("run must be { id, error }.");
  if (JSON.stringify(proposal).length > MAX_PROPOSAL_CHARS) say(`must be at most ${MAX_PROPOSAL_CHARS} characters of JSON.`);
  if (problems.length) throw new StepsError(problems);
  return proposal;
}

import * as z from "zod";
import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";

import pkg from "../package.json" with { type: "json" };
import { MAX_GRACE_MS, MIN_INTERVAL_SECONDS, MODES } from "./db.js";
import { MAX_STEPS } from "./steps.js";

/**
 * **The tools, and the one place they are registered.**
 *
 * Two audiences. Most tools are for the app's own code — the ticker and the
 * routes — and first-agent never offers them to a model. `record` and
 * `aggregate` are for the model and the planner: they are how a run keeps a
 * result and reads back what earlier runs kept, and they declare an
 * `outputSchema` so a plan can refer to their fields. Both take a
 * `scheduleId`, which the app strips from the schema the model sees and fills
 * in itself, so a run can only ever write to its own schedule.
 *
 * Like the OMDb server: a handler returns data or throws, and `toolResult` is
 * the only place either becomes a `CallToolResult`. Nothing crashes the server.
 */

// The shape of each step is checked by `validateSteps` (steps.js), which can
// say which step is wrong and why — including a template that points forward.
const plan = z
  .array(z.record(z.string(), z.unknown()))
  .max(MAX_STEPS)
  .describe(
    'The accepted pipeline, in order: what a run executes. Each step is { kind: "tool", server, tool, args?, why? } or ' +
      '{ kind: "prompt", text, allowTools?, format?: "text" | "json", outputSchema?, why? }. ' +
      "Strings may use {{prev}}, {{steps.N}} (an earlier step, 1-based, optionally .path) and {{now}}."
  );

const goal = z.string().max(4000).describe("What the pipeline is for, in prose: what the planner plans from.");
// Checked by `validateProposal` (steps.js).
const proposal = z
  .record(z.string(), z.unknown())
  .nullable()
  .describe('A plan waiting to be accepted: { steps, notes?, createdAt, reason: "generated" | "repair", errors?, run? }, or null to clear it.');

/** Data or an error, as MCP wants it back. `structuredContent` must be an object. */
export async function toolResult(run) {
  try {
    const data = await run();
    return {
      content: [{ type: "text", text: JSON.stringify(data, null, 2) }],
      structuredContent: data,
    };
  } catch (err) {
    return { content: [{ type: "text", text: readable(err) }], isError: true };
  }
}

function readable(err) {
  if (err instanceof z.ZodError) {
    return "Invalid input: " + err.issues.map((issue) => (issue.path.length ? `${issue.path.join(".")}: ` : "") + issue.message).join("; ");
  }
  return err?.message ?? String(err);
}

/**
 * A fresh server over the shared database. Stateless HTTP builds one per
 * request; the database handle is the only thing that lives longer.
 *
 * @param {{ scheduler: ReturnType<typeof import("./db.js").openScheduler> }} deps
 */
export function createServer({ scheduler }) {
  const server = new McpServer({ name: "scheduler-mcp", version: pkg.version });
  const app = { readOnlyHint: false, openWorldHint: false };

  /**
   * One registration, wrapped so every handler ends up in `toolResult`. A tool
   * the planner may put in a plan declares its `output`, so the planner knows
   * the shape of what it returns before calling it.
   */
  const tool = (name, { title, description, input, output, annotations = app }, handler) =>
    server.registerTool(
      name,
      { title, description, inputSchema: input, ...(output ? { outputSchema: output } : {}), annotations },
      (args) => toolResult(() => handler(args))
    );

  // ---- for the app ---------------------------------------------------------

  tool(
    "create_schedule",
    {
      title: "Create a schedule",
      description:
        "App tool. Create the schedule (a pipeline) for one conversation (one per conversation). In interval mode it " +
        "starts due now and runs once enabled; in once mode it runs only on run_now. It is never claimed without a plan.",
      input: z.object({
        conversationId,
        mode: mode.optional(),
        goal: goal.optional(),
        plan: plan.optional(),
        proposal: proposal.optional(),
        intervalSeconds: intervalSeconds.optional(),
        enabled: z.boolean().optional(),
      }),
    },
    (args) => scheduler.createSchedule(args)
  );

tool(
    "get_schedule",
    {
      title: "Get a schedule",
      description: "App tool. The schedule of one conversation, or { schedule: null }.",
      input: z.object({ conversationId }),
      annotations: { readOnlyHint: true, openWorldHint: false },
    },
    (args) => ({ schedule: scheduler.getSchedule(args) })
  );

  tool(
    "update_schedule",
    {
      title: "Update a schedule",
      description:
        "App tool. Change mode, goal, plan, proposal, intervalSeconds and/or enabled. Enabling an interval schedule makes it due now.",
      input: z.object({
        scheduleId,
        mode: mode.optional(),
        goal: goal.optional(),
        plan: plan.optional(),
        proposal: proposal.optional(),
        intervalSeconds: intervalSeconds.optional(),
        enabled: z.boolean().optional(),
      }),
    },
    (args) => scheduler.updateSchedule(args)
  );

  tool(
    "delete_schedule",
    {
      title: "Delete a schedule",
      description: "App tool. Delete a schedule with all of its runs and records.",
      input: z.object({ scheduleId }),
      annotations: { destructiveHint: true, openWorldHint: false },
    },
    (args) => scheduler.deleteSchedule(args)
  );

  tool(
    "list_schedules",
    {
      title: "List schedules",
      description: "App tool. Every schedule.",
      input: z.object({}),
      annotations: { readOnlyHint: true, openWorldHint: false },
    },
    () => ({ schedules: scheduler.listSchedules() })
  );

tool(
    "claim_due_runs",
    {
      title: "Claim due runs",
      description:
        "App tool, for the ticker. In one transaction: release runs stuck in 'running' for over 5 minutes, then for " +
        "every schedule that has an accepted plan, is not running, and is either due (interval mode, enabled, nextRunAt <= now + graceMs) or " +
        "has a pending run_now (any mode), insert a run, clear the run_now, and set nextRunAt = now + interval " +
        "(null in once mode). Returns { claimed: [{ run, schedule }], released }.",
      input: z.object({
        now: when,
        graceMs: z.number().int().min(0).max(MAX_GRACE_MS).optional().describe("Also claim schedules due this soon. Default 0."),
      }),
    },
    (args) => scheduler.claimDueRuns(args)
  );

tool(
    "get_run",
    {
      title: "Get a run",
      description: "App tool. One run and its steps, each with its exact resolved input and output: { run, steps }.",
      input: z.object({ runId: z.number().int().positive() }),
      annotations: { readOnlyHint: true, openWorldHint: false },
    },
    (args) => scheduler.getRun(args)
  );

  tool(
    "list_runs",
    {
      title: "List runs",
      description: "App tool. A schedule's most recent runs, newest first.",
      input: z.object({ scheduleId, limit: z.number().int().min(1).max(200).optional() }),
      annotations: { readOnlyHint: true, openWorldHint: false },
    },
    (args) => ({ runs: scheduler.listRuns(args) })
  );

  tool(
    "run_now",
    {
      title: "Run now",
      description: "App tool. Ask for a run: the next claim takes it, in either mode, enabled or not.",
      input: z.object({ scheduleId }),
    },
    (args) => scheduler.runNow(args)
  );

  tool(
    "release_runs",
    {
      title: "Release running runs",
      description: "App tool, for a ticker that just started: mark every run still 'running' as an error, so nothing waits out the stale window.",
      input: z.object({ reason: z.string().max(500).optional() }),
    },
    (args) => scheduler.releaseRuns(args)
  );

  // ---- for the model -------------------------------------------------------

tool(
    "record",
    {
      title: "Record a result",
      description:
        "Store one result of this run so later runs can count it. `key` identifies the thing (e.g. an IMDb id) and " +
        "decides what counts as a repeat; `label` is how it reads (e.g. \"Inception (2010)\"); `data` is optional extra JSON.",
      input: z.object({
        scheduleId,
        key: z.string().trim().min(1).max(200),
        label: z.string().trim().min(1).max(300),
        data: z.record(z.string(), z.unknown()).optional(),
      }),
      output: z.object({
        id: z.number().int().describe("The record's id."),
        scheduleId: z.number().int(),
        key: z.string(),
        label: z.string(),
        createdAt: z.string().describe("ISO time it was recorded."),
      }),
    },
    (args) => scheduler.record(args)
  );

tool(
    "aggregate",
    {
      title: "Aggregate the records",
      description:
        "Numbers about everything recorded so far, across all runs: { invocations, uniqueKeys, mostRepeated: " +
        "{ label, count }, first: { label, at }, last: { label, at } }. No raw rows.",
      input: z.object({ scheduleId }),
      output: z.object({
        invocations: z.number().int().describe("How many records there are."),
        uniqueKeys: z.number().int().describe("How many distinct keys."),
        mostRepeated: z.object({ label: z.string(), count: z.number().int() }).nullable().describe("The most recorded key's label, or null."),
        first: z.object({ label: z.string(), at: z.string() }).nullable().describe("The first record, or null."),
        last: z.object({ label: z.string(), at: z.string() }).nullable().describe("The latest record, or null."),
      }),
      annotations: { readOnlyHint: true, openWorldHint: false },
    },
    (args) => scheduler.aggregate(args)
  );

  return server;
}
